THIS^.OutputDimmer:=OutputDimmer;
THIS^.Qos_Dimm:=Qos_Dimm;
THIS^.Delta_Dimm:=Delta_Dimm;

(* Two entities, because this block is two things on one topic tree: a wall pushbutton and a dim level.
The button is announced exactly as FB_INPUT_PUSHBUTTON_MQTT announces one - an event entity carrying SINGLE, DOUBLE and LONG. That is why the three press payloads below are JSON: Home Assistant's event platform reads event_type out of the payload, and a bare 'SINGLE' is not a payload it can read.
The level is a sensor, not a light. A light entity would have to be commandable, and this block has no subscribe side at all - no callback collector, no command topics. FB_OUTPUT_DIMMER_MQTT is the block that does have those, and it is what to reach for when Home Assistant has to set the level rather than watch it.
ExpiryAfter is 0 on purpose. There is no heartbeat here: DIM publishes on change, gated by Delta_Dimm, so any positive expiry would grey out a level that is merely steady.
No per-entity availability topic either. Nothing in this block can be individually untrustworthy the way an RTD channel can, so both availability slots stay with the PLC device. *) IF bInitMqttDone AND NOT bInitMqttDiscoveryDone THEN
id := SUPER^.ResolveEntityId(overruleId);
Device^.CreateEventEntity( Name := Name, Id := id, Meta := meta, StateTopic := THIS^.sMQTTPublishTopic, EventTypes := eventTypes, Deviceclass := 'button');
Device^.CreateSensorEntity( Name := CONCAT(Name, ' level'), Id := CONCAT(id, '_DIM'), Meta := meta, StateTopic := CONCAT(THIS^.sMQTTPublishTopic, '/DIM'), ExpiryAfter := 0);
bInitMqttDiscoveryDone := TRUE; END_IF

SUPER^._sInstancePath := THIS^.sInstancePath; // Due to reflection its location is important

(*pass trough*)
THIS^.pMqttPublishQueue := pMqttPublishQueue;
THIS^.psMqttPublishTopicPrefix:=MQTTPublishPrefix;
SUPER^.InitBaseMqtt();

IF bInitMqttDone AND NOT bInitMqttDiscoveryDone THEN
id := SUPER^.ResolveEntityId(overruleId);
Device^.CreateEventEntity( Name := name, Id := id, Meta := meta, StateTopic := THIS^.sMQTTPublishTopic, EventTypes := eventTypes, Deviceclass := 'button');
bInitMqttDiscoveryDone := TRUE; END_IF

(* --- self-wiring prologue ---------------------------------------------------- Set FriendlyName at the declaration and this block wires itself from GVL_MQTT on its first cyclic call, then announces itself to Home Assistant. Same idiom, and the same reasons, as every other block here: see FB_INPUT_BINARYSENSOR_MQTT.
A block wired this way MUST be called cyclically. An instance whose body never runs stays unwired and never appears in Home Assistant, and nothing warns about it. *) IF FriendlyName <> '' THEN
IF NOT bInitMqttDone THEN THIS^.InitMqtt( MQTTPublishPrefix := ADR(GVL_MQTT.MqttPubAnalogInputPrefix), pMqttPublishQueue := ADR(GVL_MQTT.fbMqttPublishQueue)); END_IF
IF bInitMqttDone AND NOT bInitMqttDiscoveryDone THEN THIS^.InitMqttDiscovery( Device := ADR(GVL_MQTT.PLC_Device), Name := FriendlyName); END_IF
END_IF
(* --- is this a temperature, and is it a temperature THIS sensor could see? --- Two bounds, answering two different questions, and only the second one is much use on real hardware.
ciRtdMinRaw/MaxRaw is IEC 60751: what a platinum RTD can physically report at all. Anything outside it is the module talking about the wiring rather than the temperature, whatever value it picks to say so.
PlausibleMin/Max is what this particular sensor could be measuring, and it is the check that catches the failure this block actually met. A WAGO 750-463 reports an open circuit as 150.0 C - a perfectly legal Pt1000 temperature, inside IEC 60751, which sailed through the range check and published as a healthy reading for the fifteen minutes it took StaleTimeout to notice. No room, buffer tank or floor loop ever reaches 150 C. Saying so rejects it on the first scan. *) (* --- lead resistance, on a module that cannot compensate for it -------------- 2-conductor measurement puts the leads in series with the element, so the channel reads high by LeadResistance / 3.9 degrees. Corrected here, in tenths and in integers, so the single decimal the module actually has reaches the payload unchanged rather than through a REAL round trip.
Zero by default and REAL_TO_INT(0.0) is 0, so a channel that names no lead resistance behaves exactly as it did before this existed. *) iLeadOffset := REAL_TO_INT(LeadResistance / crPt1000OhmsPerDegree * 10.0); iCorrectedRaw := Raw - iLeadOffset;
bInRange := (iCorrectedRaw >= ciRtdMinRaw) AND (iCorrectedRaw <= ciRtdMaxRaw); (* Tenths of a degree, so the scaling is exact rather than a calibration. *) rReading := INT_TO_REAL(iCorrectedRaw) / 10.0; bPlausible := (PlausibleMax <= PlausibleMin) OR ((rReading >= PlausibleMin) AND (rReading <= PlausibleMax)); (* --- has this channel produced a reading at all? ----------------------------- Two gates before the value is looked at, because a zero has two meanings.
ProcessImageValid says the bus is exchanging process data. Necessary, and NOT sufficient: it goes TRUE slightly before an RTD module has delivered its first conversion, and until then the word is still the zero the process image was cleared to. That gap is well under a second and it was enough to publish a fabricated 0.0 C on every restart, ahead of the real value.
So a zero is not believed until the module has had time to convert. After ctFirstConversion it is believed like any other reading, because 0.0 C is a real temperature and a sensor sitting at it must not go unavailable forever. Raw and not iCorrectedRaw: it is the module's own word that is zeroed, and a lead correction would move it off zero for the wrong reason. *) fbFirstConversion(IN := ProcessImageValid, PT := ctFirstConversion); bZeroIsBelievable := (Raw <> 0) OR fbFirstConversion.Q;
Valid := ProcessImageValid AND bZeroIsBelievable AND bInRange AND bPlausible;
IF Valid THEN Temperature := rReading; DataAvailable := TRUE; END_IF
(* Out of range or implausible is the whole of the fault surface. There was a movement check here too - a channel that had not changed a digit for StaleTimeout was called Stuck and faulted - and it was removed because it does not survive contact with a quiet room. Measured on the bench, a Pt1000 moved one digit every 75 minutes or so and sat perfectly still in between, which any plausible timeout reads as a dead channel. A false fault takes a WORKING sensor out of Home Assistant, which is worse than the case it was guarding against - and that case, an open circuit parked at an end of scale, is caught on the first scan by PlausibleMin/PlausibleMax anyway. *) Fault := NOT Valid;
(* Self-restarting, so the heartbeat is a floor on how often the value is published rather than a timer anything has to remember to reset. *) fbHeartbeat(IN := NOT fbHeartbeat.Q, PT := HeartbeatInterval);
(* --- publishing -------------------------------------------------------------- Three reasons to publish and no others: the channel word changed, the heartbeat elapsed, or this is the first reading.
There was a PublishDeadband input here, defaulting to 0.2 C, on the reasoning that an RTD's last digit dithers continuously and nobody wants that in their history. This bench measured the opposite - one digit every 75 minutes or so, dead still in between - so on a quiet channel it suppressed nothing, and it is gone. Every change is published, which is what setting it to zero always did.
While the value is out of range nothing is published, deliberately: Temperature holds the last trustworthy reading, and the discovery config's expire_after lets Home Assistant retire the entity on its own if the silence lasts - a truer signal than publishing a made-up number, or the module's fault code dressed up as a temperature. *) IF bInitMqttDone AND Valid THEN IF NOT bPublishedValid OR fbHeartbeat.Q OR (iCorrectedRaw <> iPublishedRaw) THEN (* Formatted from the integer rather than through REAL_TO_STRING, which would publish 21.299999 for a channel reading 213. One decimal is all the module has, and all anyone should be told it has. *) iWhole := iCorrectedRaw / 10; iTenth := ABS(iCorrectedRaw MOD 10); sPayload := INT_TO_STRING(iWhole); IF (Raw < 0) AND (iWhole = 0) THEN sPayload := CONCAT('-', sPayload); END_IF sPayload := CONCAT(sPayload, '.'); sPayload := CONCAT(sPayload, INT_TO_STRING(iTenth));
pMqttPublishQueue^.AddMessage( Payload := sPayload, Topic := CONCAT(THIS^.sMQTTPublishTopic, '/TEMP'), Qos := MQTT.QoS.ExactlyOnce, MqttRetain := TRUE);
iPublishedRaw := iCorrectedRaw; bPublishedValid := TRUE; END_IF END_IF
(* --- available, or not ------------------------------------------------------- Published on change, both ways, plus once at startup - and that startup publish is not optional: Home Assistant treats a missing availability payload as unavailable, so an entity whose topic has never been written stays greyed out however healthy the channel is.
This is the whole fault surface. There is no separate problem entity to go looking for: a channel that cannot be trusted greys out the temperature where somebody is already reading it. The value itself keeps being published while that happens, so a stuck channel's number is still on the broker for anyone who wants to judge it - it is just no longer presented as a measurement.
The payloads come from GVL_MQTT rather than being spelled here, because they have to match the pl_avail / pl_not_avail that the discovery device published in the config, and that is where those come from. *) fbFaultEdge(CLK := Fault); fbHealEdge(CLK := Fault);
IF bInitMqttDone AND (bStartup OR fbFaultEdge.Q OR fbHealEdge.Q) THEN IF Fault THEN sPayload := GVL_MQTT.MqttAvailabilityOfflinePayload; ELSE sPayload := GVL_MQTT.MqttAvailabilityOnlinePayload; END_IF pMqttPublishQueue^.AddMessage( Payload := sPayload, Topic := CONCAT(THIS^.sMQTTPublishTopic, '/availability'), Qos := MQTT.QoS.ExactlyOnce, MqttRetain := TRUE); bStartup := FALSE; END_IF

SUPER^._sInstancePath := THIS^.sInstancePath; // Due to reflection its location is important

(*pass trough*)
