id := SUPER^.ResolveEntityId(overruleId);
Device^.CreateLockEntity( Name := name, Id := id, Meta := meta, CommandTopic := THIS^.sMQTTSubscribeTopic, PayloadLock := BOOL_TO_STRING(RelayType = E_RELAY_TYPE.NO), PayloadUnlock := BOOL_TO_STRING(RelayType = E_RELAY_TYPE.NC), StateTopic := THIS^.sMQTTPublishTopic, StateUnlocked := BOOL_TO_STRING(RelayType = E_RELAY_TYPE.NC), StateLocked := BOOL_TO_STRING(RelayType = E_RELAY_TYPE.NO));
bInitMqttDiscoveryDone := TRUE; END_IF

IF bInitMqttDone AND NOT bInitMqttDiscoveryDone THEN
id := SUPER^.ResolveEntityId(overruleId);
Device^.CreateLightEntity( Name := name, Id := id, Meta := meta, CommandTopic := THIS^.sMQTTSubscribeTopic, PayloadOn := BOOL_TO_STRING(RelayType = E_RELAY_TYPE.NO), PayloadOff := BOOL_TO_STRING(RelayType = E_RELAY_TYPE.NC), StateTopic := THIS^.sMQTTPublishTopic);
bInitMqttDiscoveryDone := TRUE; END_IF

IF bInitMqttDone AND NOT bInitMqttDiscoveryDone THEN
id := SUPER^.ResolveEntityId(overruleId);
Device^.CreateSwitchEntity( Name := name, Id := id, Meta := meta, CommandTopic := THIS^.sMQTTSubscribeTopic, PayloadOn := BOOL_TO_STRING(RelayType = E_RELAY_TYPE.NO), PayloadOff := BOOL_TO_STRING(RelayType = E_RELAY_TYPE.NC), StateTopic := THIS^.sMQTTPublishTopic, StateOnPayload := BOOL_TO_STRING(RelayType = E_RELAY_TYPE.NO), StateOffPayload := BOOL_TO_STRING(RelayType = E_RELAY_TYPE.NC), DeviceClass := DeviceClass);
bInitMqttDiscoveryDone := TRUE; END_IF

//first check if Mqtt is initialized, otherwise do nothing
IF NOT(bInitMqttDone) THEN
	//mark the interface call from the collector as done
	PublishReceived := TRUE;
//check if the packet is for this FB
ELSIF CommonTypesAndFunctions.StrEquals(str1:= ADR(sMQTTSubscribeTopic), str2:= Data.TopicOut) THEN
	//mark the interface call from the collector as done
	PublishReceived := TRUE;
	//now process the data
	IF CommonTypesAndFunctions.StrEquals(str1:= Data.PayloadString, str2:= ADR('TRUE')) THEN
		bMqttHighRequest := TRUE;
	ELSIF CommonTypesAndFunctions.StrEquals(str1:= Data.PayloadString, str2:= ADR('FALSE')) THEN
		bMqttLowRequest := TRUE;
	// Siren sends out a JSON
	ELSIF FIND(Data.PayloadString^, 'TRUE') > 0 THEN
		bMqttHighRequest := TRUE;
	ELSIF FIND(Data.PayloadString^, 'FALSE') > 0 THEN
		bMqttLowRequest := TRUE;
	END_IF
END_IF

SUPER^._sInstancePath := THIS^.sInstancePath; // Due to reflection its location is important

(*pass trough*)
THIS^.pMqttPublishQueue := pMqttPublishQueue;
THIS^.psMqttPublishTopicPrefix:=MQTTPublishPrefix;
THIS^.psMqttSubscribeTopicPrefix:=MQTTSubscribePrefix;
THIS^.pMqttPublishQueue:=pMqttPublishQueue;

SUPER^.InitBaseMqtt();
pMqttCallbackCollector^.put(instance:= THIS^); // register the FB agains the collector so mqtt events can be received

IF bInitMqttDone AND NOT bInitMqttDiscoveryDone THEN
id := SUPER^.ResolveEntityId(overruleId);
Device^.CreateValveEntity( Name := name, Id := id, Meta := meta, CommandTopic := THIS^.sMQTTSubscribeTopic, PayloadOpen := BOOL_TO_STRING(RelayType = E_RELAY_TYPE.NO), PayloadClosed := BOOL_TO_STRING(RelayType = E_RELAY_TYPE.NC), StateTopic := THIS^.sMQTTPublishTopic, StateOpen := BOOL_TO_STRING(RelayType = E_RELAY_TYPE.NC), StateClosed := BOOL_TO_STRING(RelayType = E_RELAY_TYPE.NO), Deviceclass := DeviceClass);
bInitMqttDiscoveryDone := TRUE; END_IF

IF bInitMqttDone AND NOT bInitMqttDiscoveryDone THEN
id := SUPER^.ResolveEntityId(overruleId);
(* An on/off fan: no percentage or oscillation topics, because a binary output has no speed to report. A E_DIMMER-backed fan would pass those. *) Device^.CreateFanEntity( Name := name, Id := id, Meta := meta, CommandTopic := THIS^.sMQTTSubscribeTopic, PayloadOn := BOOL_TO_STRING(RelayType = E_RELAY_TYPE.NO), PayloadOff := BOOL_TO_STRING(RelayType = E_RELAY_TYPE.NC), StateTopic := THIS^.sMQTTPublishTopic);
bInitMqttDiscoveryDone := TRUE; END_IF

(* --- self-wiring prologue ---------------------------------------------------- Makes the InitMqtt and InitMqttDiscovery* calls optional. Set FriendlyName at the declaration site and this block wires itself from GVL_MQTT on its first cyclic call, then announces itself to Home Assistant.
Deliberately in the body rather than in FB_init: it dereferences GVL members and reads the reflection instance path, and doing that during initialisation would rely on an ordering nothing enforces and the compiler cannot check. The body is the same lifecycle phase the init actions used, so this is not merely safe, it is the phase that already works today.
The wiring calls this block's own unmodified InitMqtt / InitMqttDiscovery* methods, so anything published - topics and discovery JSON alike - is produced by exactly the code that produces it today. Only the trigger moved.
Dormant while FriendlyName is empty, so existing projects and existing call sites keep working untouched.
A block wired this way MUST be called cyclically. An instance whose body never runs is now unwired and absent from Home Assistant, where the init action used to wire it regardless. Nothing warns about that. *) IF FriendlyName <> '' THEN
IF NOT bInitMqttDone THEN THIS^.InitMqtt( MQTTPublishPrefix := ADR(GVL_MQTT.MqttPubSwitchPrefix), MQTTSubscribePrefix := ADR(GVL_MQTT.MqttSubSwitchPrefix), pMqttPublishQueue := ADR(GVL_MQTT.fbMqttPublishQueue), pMqttCallbackCollector := ADR(GVL_MQTT.collector_FB_OUTPUT_SWITCH_MQTT)); END_IF
IF bInitMqttDone AND NOT bInitMqttDiscoveryDone THEN IF EntityType = E_MQTT_ENTITY.Light THEN THIS^.InitMqttDiscoveryAsLight( Device := ADR(GVL_MQTT.PLC_Device), Name := FriendlyName, RelayType := RelayType); ELSIF EntityType = E_MQTT_ENTITY.Lock THEN THIS^.InitMqttDiscoveryAsLock( Device := ADR(GVL_MQTT.PLC_Device), Name := FriendlyName, RelayType := RelayType); ELSIF EntityType = E_MQTT_ENTITY.Siren THEN THIS^.InitMqttDiscoveryAsSiren( Device := ADR(GVL_MQTT.PLC_Device), Name := FriendlyName, RelayType := RelayType); ELSIF EntityType = E_MQTT_ENTITY.Fan THEN THIS^.InitMqttDiscoveryAsFan( Device := ADR(GVL_MQTT.PLC_Device), Name := FriendlyName, RelayType := RelayType); ELSE (* Default, and any platform this block cannot announce as. *) THIS^.InitMqttDiscoveryAsSwitch( Device := ADR(GVL_MQTT.PLC_Device), Name := FriendlyName, RelayType := RelayType); END_IF END_IF
END_IF
fbHoldTimer(PT:= T_hold);
IF PRIO_HIGH THEN IF NOT FEEDBACK THEN bPulseTrigger:=TRUE; END_IF ELSIF(PRIO_LOW AND NOT (PRIO_HIGH)) THEN IF FEEDBACK THEN bPulseTrigger:=TRUE; END_IF OUT:= FALSE; ELSIF bMqttHighRequest THEN IF NOT FEEDBACK THEN bPulseTrigger:=TRUE; END_IF bMqttHighRequest := FALSE; bMqttLowRequest := FALSE; ELSIF bMqttLowRequest THEN IF FEEDBACK THEN bPulseTrigger:=TRUE; END_IF bMqttHighRequest := FALSE; bMqttLowRequest := FALSE; ELSIF(TOGGLE) THEN bPulseTrigger:=TRUE; END_IF;
IF ((bPreviousFeedback <> FEEDBACK) OR bStartup) AND bInitMqttDone THEN pMqttPublishQueue^.AddMessage( Payload := BOOL_TO_STRING(FEEDBACK), Topic := CONCAT(psMqttPublishTopicPrefix^, MqttPublishTopicSuffix), Qos := MQTT.QoS.ExactlyOnce, MqttRetain := TRUE ); bStartup:=FALSE; END_IF
bPreviousFeedback := FEEDBACK; fbHoldTimer.IN := bPulseTrigger; OUT := fbHoldTimer.Q;
bPulseTrigger:=FALSE;

IF bInitMqttDone AND NOT bInitMqttDiscoveryDone THEN
id := SUPER^.ResolveEntityId(overruleId);
Device^.CreateLightEntity( Name := name, Id := id, Meta := meta, CommandTopic := THIS^.sMQTTSubscribeTopic, PayloadOn := BOOL_TO_STRING(RelayType = E_RELAY_TYPE.NO), PayloadOff := BOOL_TO_STRING(RelayType = E_RELAY_TYPE.NC), StateTopic := THIS^.sMQTTPublishTopic);
bInitMqttDiscoveryDone := TRUE; END_IF

IF bInitMqttDone AND NOT bInitMqttDiscoveryDone THEN
id := SUPER^.ResolveEntityId(overruleId);
Device^.CreateLockEntity( Name := name, Id := id, Meta := meta, CommandTopic := THIS^.sMQTTSubscribeTopic, PayloadLock := BOOL_TO_STRING(RelayType = E_RELAY_TYPE.NO), PayloadUnlock := BOOL_TO_STRING(RelayType = E_RELAY_TYPE.NC), StateTopic := THIS^.sMQTTPublishTopic, StateUnlocked := BOOL_TO_STRING(RelayType = E_RELAY_TYPE.NC), StateLocked := BOOL_TO_STRING(RelayType = E_RELAY_TYPE.NO));
bInitMqttDiscoveryDone := TRUE; END_IF

IF bInitMqttDone AND NOT bInitMqttDiscoveryDone THEN
id := SUPER^.ResolveEntityId(overruleId);
Device^.CreateSirenEntity( Name := name, Id := id, Meta := meta, CommandTopic := THIS^.sMQTTSubscribeTopic, PayloadOn := BOOL_TO_STRING(RelayType = E_RELAY_TYPE.NO), PayloadOff := BOOL_TO_STRING(RelayType = E_RELAY_TYPE.NC), StateTopic := THIS^.sMQTTPublishTopic, StateOnPayload := BOOL_TO_STRING(RelayType = E_RELAY_TYPE.NO), StateOffPayload := BOOL_TO_STRING(RelayType = E_RELAY_TYPE.NC) );
bInitMqttDiscoveryDone := TRUE; END_IF

SUPER^._sInstancePath := THIS^.sInstancePath; // Due to reflection its location is important

(*pass trough*)
THIS^.pMqttPublishQueue := pMqttPublishQueue;
THIS^.psMqttPublishTopicPrefix:=MQTTPublishPrefix;
THIS^.psMqttSubscribeTopicPrefix:=MQTTSubscribePrefix;
THIS^.pMqttPublishQueue:=pMqttPublishQueue;



SUPER^.InitBaseMqtt();
pMqttCallbackCollector^.put(instance:= THIS^); // register the FB agains the collector so mqtt events can be received

//first check if Mqtt is initialized, otherwise do nothing
IF NOT(bInitMqttDone) THEN
	//mark the interface call from the collector as done
	PublishReceived := TRUE;
//check if the packet is for this FB
ELSIF CommonTypesAndFunctions.StrEquals(str1:= ADR(sMQTTSubscribeTopic), str2:= Data.TopicOut) THEN
	//mark the interface call from the collector as done
	PublishReceived := TRUE;
	//now process the data
	IF CommonTypesAndFunctions.StrEquals(str1:= Data.PayloadString, str2:= ADR('TRUE')) THEN
		bMqttHighRequest := TRUE;
	ELSIF CommonTypesAndFunctions.StrEquals(str1:= Data.PayloadString, str2:= ADR('FALSE')) THEN
		bMqttLowRequest := TRUE;
	// Siren sends out a JSON
	ELSIF FIND(Data.PayloadString^, 'TRUE') > 0 THEN
		bMqttHighRequest := TRUE;
	ELSIF FIND(Data.PayloadString^, 'FALSE') > 0 THEN
		bMqttLowRequest := TRUE;
	END_IF
END_IF

IF bInitMqttDone AND NOT bInitMqttDiscoveryDone THEN
id := SUPER^.ResolveEntityId(overruleId);
Device^.CreateSwitchEntity( Name := name, Id := id, Meta := meta, CommandTopic := THIS^.sMQTTSubscribeTopic, PayloadOn := BOOL_TO_STRING(RelayType = E_RELAY_TYPE.NO), PayloadOff := BOOL_TO_STRING(RelayType = E_RELAY_TYPE.NC), StateTopic := THIS^.sMQTTPublishTopic, StateOnPayload := BOOL_TO_STRING(RelayType = E_RELAY_TYPE.NO), StateOffPayload := BOOL_TO_STRING(RelayType = E_RELAY_TYPE.NC), DeviceClass := DeviceClass);
bInitMqttDiscoveryDone := TRUE; END_IF

IF bInitMqttDone AND NOT bInitMqttDiscoveryDone THEN
id := SUPER^.ResolveEntityId(overruleId);
(* An on/off fan: no percentage or oscillation topics, because a binary output has no speed to report. A E_DIMMER-backed fan would pass those. *) Device^.CreateFanEntity( Name := name, Id := id, Meta := meta, CommandTopic := THIS^.sMQTTSubscribeTopic, PayloadOn := BOOL_TO_STRING(RelayType = E_RELAY_TYPE.NO), PayloadOff := BOOL_TO_STRING(RelayType = E_RELAY_TYPE.NC), StateTopic := THIS^.sMQTTPublishTopic);
bInitMqttDiscoveryDone := TRUE; END_IF

(* --- self-wiring prologue ----------------------------------------------------
   Makes the InitMqtt and InitMqttDiscovery* calls optional. Set FriendlyName at
   the declaration site and this block wires itself from GVL_MQTT on its
   first cyclic call, then announces itself to Home Assistant.

   Deliberately in the body rather than in FB_init: it dereferences GVL members
   and reads the reflection instance path, and doing that during initialisation
   would rely on an ordering nothing enforces and the compiler cannot check. The
   body is the same lifecycle phase the init actions used, so this is not merely
   safe, it is the phase that already works today.

   The wiring calls this block's own unmodified InitMqtt / InitMqttDiscovery*
   methods, so anything published - topics and discovery JSON alike - is produced
   by exactly the code that produces it today. Only the trigger moved.

   Dormant while FriendlyName is empty, so existing projects and existing call
   sites keep working untouched.

   A block wired this way MUST be called cyclically. An instance whose body never
   runs is now unwired and absent from Home Assistant, where the init action used
   to wire it regardless. Nothing warns about that.  *)
IF FriendlyName <> '' THEN

	IF NOT bInitMqttDone THEN
		THIS^.InitMqtt(
			MQTTPublishPrefix := ADR(GVL_MQTT.MqttPubCoverPrefix),
			MQTTSubscribePrefix := ADR(GVL_MQTT.MqttSubCoverPrefix),
			pMqttPublishQueue := ADR(GVL_MQTT.fbMqttPublishQueue),
			pMqttCallbackCollector := ADR(GVL_MQTT.collector_FB_OUTPUT_COVER_MQTT));
	END_IF

	IF bInitMqttDone AND NOT bInitMqttDiscoveryDone THEN
		THIS^.InitMqttDiscovery(
			Device := ADR(GVL_MQTT.PLC_Device),
			Name := FriendlyName);
	END_IF

END_IF

(* Run the timer to not power the motors for to long *)
fbCoverStateTimer(PT:=T_UD);
fbCoverStateTimer.IN:=FALSE;
fbMuRTrigger(CLK:=MU);
fbMdRTrigger(CLK:=MD);
fbMuFTrigger(CLK:=MU);
fbMdFTrigger(CLK:=MD);

(* Publish once at boot so the entity has a value before the first movement.
   Deliberately 'STOPPED' rather than a derived OPEN/CLOSED: bInternalDir is
   PERSISTENT and does carry the last direction, but its meaning is ambiguous -
   the declaration comment says "down = false, up = true" while the logic below
   sets bInternalDir := FALSE after a completed upward move. 'STOPPED' is an
   honest "position unknown", and a confidently wrong OPEN or CLOSED would
   mislead automations more than no position does. *)
IF bStartup AND bInitMqttDone THEN
	bStartup := FALSE;
	pMqttPublishQueue^.AddMessage(
		Payload := 'STOPPED',
		Topic := CONCAT(psMqttPublishTopicPrefix^, MqttPublishTopicSuffix),
		Qos := MQTT.QoS.ExactlyOnce,
		MqttRetain := TRUE
	);
END_IF

IF fbMuRTrigger.Q AND bInitMqttDone THEN
	pMqttPublishQueue^.AddMessage(
		Payload := 'OPENING',
		Topic := CONCAT(psMqttPublishTopicPrefix^, MqttPublishTopicSuffix),
		Qos := MQTT.QoS.ExactlyOnce,
		MqttRetain := TRUE
	);
END_IF

IF fbMdRTrigger.Q AND bInitMqttDone THEN
	pMqttPublishQueue^.AddMessage(
		Payload := 'CLOSING',
		Topic := CONCAT(psMqttPublishTopicPrefix^, MqttPublishTopicSuffix),
		Qos := MQTT.QoS.ExactlyOnce,
		MqttRetain := TRUE
	);
END_IF	

IF (fbMdFTrigger.Q OR fbMuFTrigger.Q) AND fbCoverStateTimer.Q AND bInitMqttDone THEN
	pMqttPublishQueue^.AddMessage(
		Payload := 'STOPPED',
		Topic := CONCAT(psMqttPublishTopicPrefix^, MqttPublishTopicSuffix),
		Qos := MQTT.QoS.ExactlyOnce,
		MqttRetain := TRUE
	);
END_IF	


IF (NOT(fbCoverStateTimer.Q) AND bInternalUp) AND bInitMqttDone THEN
	pMqttPublishQueue^.AddMessage(
		Payload := 'OPEN',
		Topic := CONCAT(psMqttPublishTopicPrefix^, MqttPublishTopicSuffix),
		Qos := MQTT.QoS.ExactlyOnce,
		MqttRetain := TRUE
	);
END_IF

IF (NOT(fbCoverStateTimer.Q) AND bInternalDown) AND bInitMqttDone THEN
	pMqttPublishQueue^.AddMessage(
		Payload := 'CLOSED',
		Topic := CONCAT(psMqttPublishTopicPrefix^, MqttPublishTopicSuffix),
		Qos := MQTT.QoS.ExactlyOnce,
		MqttRetain := TRUE
	);
END_IF


(* Check what to do *)
IF NOT(fbCoverStateTimer.Q) AND bInternalUp THEN // don't run the motors for to long, assume we've reached end and toggle dir
	bInternalUp := FALSE;
	bInternalDown := FALSE;
	bInternalDir := FALSE;
ELSIF NOT(fbCoverStateTimer.Q) AND bInternalDown THEN // don't run the motors for to long, assume we've reached end and toggle dir
	bInternalUp := FALSE;
	bInternalDown := FALSE;
	bInternalDir := TRUE;
ELSIF PRIO_LOCK THEN	
	bInternalUp := FALSE;
	bInternalDown := FALSE;
ELSIF PRIO_UP THEN	
	bInternalUp := TRUE;
	bInternalDown := FALSE;
	fbCoverStateTimer.IN:=TRUE;
ELSIF PRIO_DN THEN	
	bInternalUp := FALSE;
	bInternalDown := TRUE;
	fbCoverStateTimer.IN:=TRUE;
ELSIF TOGGLE AND (bInternalUp OR bInternalDown) THEN	// stop and toggle dir
	bInternalUp := FALSE;
	bInternalDown := FALSE;
	bInternalDir := NOT(bInternalDir);
ELSIF TOGGLE AND NOT(bInternalDir) THEN //move down
	bInternalUp := FALSE;
	bInternalDown := TRUE;
	fbCoverStateTimer.IN:=TRUE;
ELSIF TOGGLE AND bInternalDir THEN //move upwards
	bInternalUp := TRUE;
	bInternalDown := FALSE;	
	fbCoverStateTimer.IN:=TRUE;
ELSIF bMqttRequestStop THEN
	bInternalUp := FALSE;
	bInternalDown := FALSE;
	bMqttRequestStop := FALSE;
ELSIF bMqttRequestOpen THEN
	bInternalUp := TRUE;
	bInternalDown := FALSE;
	bMqttRequestOpen := FALSE;
	fbCoverStateTimer.IN:=TRUE;;
ELSIF bMqttRequestClose THEN
	bInternalUp := FALSE;
	bInternalDown := TRUE;
	bMqttRequestClose := FALSE;
	fbCoverStateTimer.IN:=TRUE;
END_IF

(* make sure only one motor is active at a given time *)
fbLock(i1 := bInternalUp, I2 := bInternalDown, TL := T_lockout);
MU := fbLock.Q1;
MD := fbLock.Q2;

IF bInitMqttDone AND NOT bInitMqttDiscoveryDone THEN
id := SUPER^.ResolveEntityId(overruleId);
Device^.CreateCoverEntity( Name := name, Id := id, Meta := meta, CommandTopic := THIS^.sMQTTSubscribeTopic, PayloadOpen := 'OPEN', PayloadClose := 'CLOSE', PayloadStop := 'STOP', StateTopic := THIS^.sMQTTPublishTopic, StateOpen := 'OPEN', StateOpening := 'OPENING', StateClosed := 'CLOSED', StateClosing := 'CLOSING', StateStopped := 'STOPPED', DeviceClass := DeviceClass );
bInitMqttDiscoveryDone := TRUE; END_IF

//first check if Mqtt is initialized, otherwise do nothing
IF NOT(bInitMqttDone) THEN
	//mark the interface call from the collector as done
	PublishReceived := TRUE;
//check if the packet is for this FB
ELSIF CommonTypesAndFunctions.StrEquals(str1:= ADR(sMQTTSubscribeTopic), str2:= Data.TopicOut) THEN
	//mark the interface call from the collector as done
	PublishReceived := TRUE;
	//now process the data
	IF CommonTypesAndFunctions.StrEquals(str1:= Data.PayloadString, str2:= ADR('STOP')) THEN			
		THIS^.bMqttRequestStop:=TRUE;
	ELSIF CommonTypesAndFunctions.StrEquals(str1:= Data.PayloadString, str2:= ADR('OPEN')) THEN
		THIS^.bMqttRequestOpen:=TRUE;
	ELSIF CommonTypesAndFunctions.StrEquals(str1:= Data.PayloadString, str2:= ADR('CLOSE')) THEN
		THIS^.bMqttRequestClose:=TRUE;
	END_IF

END_IF

SUPER^._sInstancePath := THIS^.sInstancePath; // Due to reflection its location is important

(*pass trough*)
THIS^.pMqttPublishQueue := pMqttPublishQueue;
THIS^.psMqttPublishTopicPrefix:=MQTTPublishPrefix;
THIS^.psMqttSubscribeTopicPrefix:=MQTTSubscribePrefix;

SUPER^.InitBaseMqtt();
pMqttCallbackCollector^.put(instance:= THIS^); // register the FB agains the collector so mqtt events can be received

(* --- self-wiring prologue ----------------------------------------------------
   Set FriendlyName at the declaration and this block wires itself from
   GVL_MQTT on its first cyclic call, then announces itself to Home
   Assistant. Same idiom, and the same reasons, as every other block here: see
   FB_OUTPUT_COVER_MQTT.

   It shares the cover prefix and the cover collector with that block. Nothing
   distinguishes the two on the wire - both are covers, and the collector asks
   every registered instance whether a message is theirs.

   A block wired this way MUST be called cyclically. An instance whose body never
   runs stays unwired and never appears in Home Assistant, and nothing warns
   about it. *)
IF FriendlyName <> '' THEN

	IF NOT bInitMqttDone THEN
		THIS^.InitMqtt(
			MQTTPublishPrefix := ADR(GVL_MQTT.MqttPubCoverPrefix),
			MQTTSubscribePrefix := ADR(GVL_MQTT.MqttSubCoverPrefix),
			pMqttPublishQueue := ADR(GVL_MQTT.fbMqttPublishQueue),
			pMqttCallbackCollector := ADR(GVL_MQTT.collector_FB_OUTPUT_COVER_MQTT));
	END_IF

	IF bInitMqttDone AND NOT bInitMqttDiscoveryDone THEN
		THIS^.InitMqttDiscovery(
			Device := ADR(GVL_MQTT.PLC_Device),
			Name := FriendlyName);
	END_IF

END_IF

IF bInitMqttDone AND (PositionTopic = '') THEN
	PositionTopic := CONCAT(THIS^.sMQTTPublishTopic, '/POSITION');
	SetPositionTopic := CONCAT(THIS^.sMQTTSubscribeTopic, '/POSITION');
END_IF

(* --- how much time has passed -------------------------------------------------
   The position is integrated from run time, so the length of a cycle is the one
   measurement this block cannot do without. A tick longer than cudiMaxTickMs is a
   download, a breakpoint or a task overrun rather than travel, and is dropped:
   integrating it would teleport the cover. *)
tNow := TIME();
IF NOT bValid THEN
	bValid := TRUE;
	udiDtMs := 0;
ELSE
	udiDtMs := TIME_TO_UDINT(tNow) - TIME_TO_UDINT(tLast);
	IF udiDtMs > cudiMaxTickMs THEN
		udiDtMs := 0;
	END_IF
END_IF
tLast := tNow;

(* --- integrate ---------------------------------------------------------------
   Whatever the motor did last cycle is what moved the cover, so the estimate is
   advanced before this cycle's decision is taken. *)
IF iDriving = ciDriveUp THEN
	udiTravelMs := TIME_TO_UDINT(T_TravelUp);
	IF udiTravelMs > 0 THEN
		rStep := UDINT_TO_REAL(udiDtMs) * 100.0 / UDINT_TO_REAL(udiTravelMs);
		rPositionReal := rPositionReal + rStep;
	END_IF
ELSIF iDriving = ciDriveDown THEN
	udiTravelMs := TIME_TO_UDINT(T_TravelDown);
	IF udiTravelMs > 0 THEN
		rStep := UDINT_TO_REAL(udiDtMs) * 100.0 / UDINT_TO_REAL(udiTravelMs);
		rPositionReal := rPositionReal - rStep;
	END_IF
END_IF

IF rPositionReal > 100.0 THEN
	rPositionReal := 100.0;
END_IF
IF rPositionReal < 0.0 THEN
	rPositionReal := 0.0;
END_IF

(* --- a held button wins -------------------------------------------------------
   A person watching the cover beats anything Home Assistant asked for, and beats
   it by abandoning the rTarget rather than queueing behind it: releasing the
   button pins the rTarget to wherever the cover got to, so nothing resumes.

   Both buttons at once is not a command. There is no sane guess to make. *)
IF UP AND NOT DN THEN
	iManualDrive := ciDriveUp;
ELSIF DN AND NOT UP THEN
	iManualDrive := ciDriveDown;
ELSE
	IF iManualDrive <> ciDriveStop THEN
		rTarget := rPositionReal;
		bArrived := TRUE;
		bReferencing := FALSE;
	END_IF
	iManualDrive := ciDriveStop;
END_IF

(* --- and what Home Assistant asked for ---------------------------------------
   Latched by the callback, consumed here, so a command that arrives mid-cycle is
   acted on exactly once. *)
IF bMqttRequestStop THEN
	bMqttRequestStop := FALSE;
	(* Hold here. The rTarget has to be dragged to the present position or the
	   interrupted journey would resume on the next cycle - a stop that only
	   pauses is not a stop. *)
	rTarget := rPositionReal;
	bArrived := TRUE;
	bReferencing := FALSE;
ELSIF bMqttRequestOpen THEN
	bMqttRequestOpen := FALSE;
	rTarget := 100.0;
	bArrived := FALSE;
	bReferencing := TRUE;
ELSIF bMqttRequestClose THEN
	bMqttRequestClose := FALSE;
	rTarget := 0.0;
	bArrived := FALSE;
	bReferencing := TRUE;
ELSIF bMqttRequestPosition THEN
	bMqttRequestPosition := FALSE;
	rTarget := BYTE_TO_REAL(byMqttRequestPositionPct);
	bArrived := FALSE;
	(* A slider dragged to either extreme is a full-travel command like any other,
	   and gets the same re-reference. *)
	bReferencing := (rTarget >= 100.0) OR (rTarget <= 0.0);
END_IF

(* --- decide -------------------------------------------------------------------
   An end stop is driven into rather than stopped at: the motor keeps running for
   T_EndStop once the estimate reaches the limit, which is what makes the position
   measured there rather than integrated forever, and what lets a cover that has
   drifted find itself again. *)
(* --- a full command re-references, and does not trust the estimate ------------
   The run is timed from the whole travel time rather than from the distance the
   estimate believes is left. That distinction is the difference between a cover
   that heals and one that cannot: if the estimate reads 80 while the shutter is
   at 20, a run of "the remaining 20%" ends nowhere near the stop and the error
   survives. A run of the full travel always ends against it.

   The timer only accumulates while a motor is actually turning, so a fbLockout
   delay or a PRIO_LOCK pause does not eat into the travel - and a lock that
   interrupts a run restarts it from the beginning, which is the safe direction to
   fail in. *)
IF rTarget >= 100.0 THEN
	tRefTime := T_TravelUp + T_EndStop;
ELSE
	tRefTime := T_TravelDown + T_EndStop;
END_IF

fbRefRun(IN := bReferencing AND (iDrivingLast <> ciDriveStop), PT := tRefTime);

IF iManualDrive <> ciDriveStop THEN
	iDriving := iManualDrive;

ELSIF bArrived THEN
	(* Nothing outstanding. Without this the motor restarts the moment a timer
	   resets, and the cover hunts at the limit forever. *)
	iDriving := ciDriveStop;

ELSIF bReferencing THEN
	IF fbRefRun.Q THEN
		(* Against the stop by the clock. This is the one moment the position is
		   measured rather than integrated, so the estimate is set, not nudged. *)
		iDriving := ciDriveStop;
		bArrived := TRUE;
		bReferencing := FALSE;
		PositionKnown := TRUE;
		IF rTarget >= 100.0 THEN
			rPositionReal := 100.0;
		ELSE
			rPositionReal := 0.0;
		END_IF
	ELSIF rTarget >= 100.0 THEN
		iDriving := ciDriveUp;
	ELSE
		iDriving := ciDriveDown;
	END_IF

ELSIF (rTarget - rPositionReal) > BYTE_TO_REAL(Tolerance) THEN
	iDriving := ciDriveUp;

ELSIF (rPositionReal - rTarget) > BYTE_TO_REAL(Tolerance) THEN
	iDriving := ciDriveDown;

ELSE
	(* Close enough. A shutter cannot be positioned finer than its own start and
	   stop time, so this is where a mid-range journey ends - and a mid-range
	   journey is the one case that cannot re-reference, because it does not go
	   anywhere the position is known. *)
	iDriving := ciDriveStop;
	bArrived := TRUE;
END_IF

IF PRIO_LOCK THEN
	iDriving := ciDriveStop;
END_IF

(* --- fbLockout ------------------------------------------------------------------
   A reversing contactor must never be asked to change direction while the motor
   is still turning, so a direction change always passes through a stop of at
   least T_Lockout. Starting from standstill is not delayed. *)
IF (iDriving <> ciDriveStop) AND (iDrivingLast <> ciDriveStop) AND (iDriving <> iDrivingLast) THEN
	iDriving := ciDriveStop;
END_IF

(* The timer runs on where the cover WAS, not on what has just been decided.
   Feeding it the decision deadlocks the block: asking to move makes IN FALSE,
   which resets the very timer that would have permitted moving, so the request
   is refused again on the next cycle and forever after. That cost a bench run,
   and the symptom was a cover that byReported STOPPED at 0% no matter what was
   asked of it. *)
fbLockout(IN := (iDrivingLast = ciDriveStop), PT := T_Lockout);

IF (iDriving <> ciDriveStop) AND (iDrivingLast = ciDriveStop) AND NOT fbLockout.Q THEN
	(* Stopped too recently to start again - the contactor gets its dead time. *)
	iDriving := ciDriveStop;
END_IF

iDrivingLast := iDriving;

MU := (iDriving = ciDriveUp);
MD := (iDriving = ciDriveDown);
Moving := MU OR MD;
Position := REAL_TO_BYTE(rPositionReal + 0.5);

(* --- what to tell Home Assistant ---------------------------------------------
   Position is the estimate, and the estimate is a guess until something has
   driven to an end stop. Publishing that guess as exactly 0 or 100 is worse than
   imprecise: Home Assistant reads those as the limits and disables the button in
   that direction, which is precisely the command that would have re-referenced
   the cover. So an unreferenced cover reports 1 or 99 instead, the slider keeps
   both ends reachable, and one full command puts the matter to rest.

   The Position output is deliberately left alone - logic on the PLC side should
   see the estimate, not a number bent for a user interface. *)
byReported := Position;
IF NOT PositionKnown THEN
	IF byReported >= 100 THEN
		byReported := 99;
	ELSIF byReported = 0 THEN
		byReported := 1;
	END_IF
END_IF

(* --- sState -------------------------------------------------------------------
   Moving beats resting, and an end stop beats the middle. A cover that has not
   reached a stop since power-up says STOPPED rather than guessing: the estimate
   starts at 0, which looks exactly like a shutter resting closed and is in fact
   an assumption. FB_OUTPUT_COVER_MQTT publishes STOPPED at boot for the same
   reason. *)
IF MU THEN
	sState := 'OPENING';
ELSIF MD THEN
	sState := 'CLOSING';
ELSIF NOT PositionKnown THEN
	sState := 'STOPPED';
ELSIF Position >= 100 THEN
	sState := 'OPEN';
ELSIF Position = 0 THEN
	sState := 'CLOSED';
ELSE
	sState := 'STOPPED';
END_IF

IF bInitMqttDone AND (bStartup OR (sState <> sPublishedState)) THEN
	sPublishedState := sState;
	pMqttPublishQueue^.AddMessage(
		Payload := sState,
		Topic := THIS^.sMQTTPublishTopic,
		Qos := MQTT.QoS.ExactlyOnce,
		MqttRetain := TRUE);
END_IF

(* --- position ----------------------------------------------------------------
   While moving, every PublishStep percent, so the slider tracks the shutter
   without flooding the broker. When movement ends, the exact value, because that
   is the number somebody will read off a dashboard for the next hour. *)
IF bInitMqttDone THEN
	iDiff := BYTE_TO_INT(byReported) - BYTE_TO_INT(byPublishedPosition);
	IF iDiff < 0 THEN
		iDiff := -iDiff;
	END_IF

	IF bStartup
		OR NOT bPositionPublished
		OR (NOT Moving AND (byReported <> byPublishedPosition))
		OR (iDiff >= BYTE_TO_INT(PublishStep))
	THEN
		byPublishedPosition := byReported;
		bPositionPublished := TRUE;
		Payload := BYTE_TO_STRING(byReported);
		pMqttPublishQueue^.AddMessage(
			Payload := Payload,
			Topic := PositionTopic,
			Qos := MQTT.QoS.ExactlyOnce,
			MqttRetain := TRUE);
	END_IF

	bStartup := FALSE;
END_IF

//first check if Mqtt is initialized, otherwise do nothing
IF NOT(bInitMqttDone) THEN
	//mark the interface call from the collector as done
	PublishReceived := TRUE;

//the command topic: the same three payloads the older cover block takes
ELSIF CommonTypesAndFunctions.StrEquals(str1:= ADR(sMQTTSubscribeTopic), str2:= Data.TopicOut) THEN
	PublishReceived := TRUE;
	IF CommonTypesAndFunctions.StrEquals(str1:= Data.PayloadString, str2:= ADR('STOP')) THEN
		THIS^.bMqttRequestStop := TRUE;
	ELSIF CommonTypesAndFunctions.StrEquals(str1:= Data.PayloadString, str2:= ADR('OPEN')) THEN
		THIS^.bMqttRequestOpen := TRUE;
	ELSIF CommonTypesAndFunctions.StrEquals(str1:= Data.PayloadString, str2:= ADR('CLOSE')) THEN
		THIS^.bMqttRequestClose := TRUE;
	END_IF

//and the position topic, which carries a bare number
ELSIF CommonTypesAndFunctions.StrEquals(str1:= ADR(SetPositionTopic), str2:= Data.TopicOut) THEN
	PublishReceived := TRUE;
	(* Home Assistant sends the number as text. STRING_TO_BYTE returns 0 for
	   anything it cannot parse, which is indistinguishable from a genuine
	   request to close - so an unparseable payload is dropped instead, and
	   'closed' has to be asked for as 0 or as CLOSE. *)
	IF CommonTypesAndFunctions.StrEquals(str1:= Data.PayloadString, str2:= ADR('0'))
		OR (STRING_TO_BYTE(Data.PayloadString^) > 0)
	THEN
		THIS^.byMqttRequestPositionPct := STRING_TO_BYTE(Data.PayloadString^);
		IF THIS^.byMqttRequestPositionPct > 100 THEN
			THIS^.byMqttRequestPositionPct := 100;
		END_IF
		THIS^.bMqttRequestPosition := TRUE;
	END_IF
END_IF

IF bInitMqttDone AND NOT bInitMqttDiscoveryDone THEN
id := SUPER^.ResolveEntityId(overruleId);
(* A different method, not extra arguments to the one FB_OUTPUT_COVER_MQTT uses: Home Assistant rejects position_topic and set_position_topic as null, so the two configs have to differ by which keys exist rather than by their values. Everything else is deliberately identical, so swapping one block for the other keeps the same behaviour for open, close and stop. *) Device^.CreateCoverEntityWithPosition( Name := name, Id := id, Meta := meta, CommandTopic := THIS^.sMQTTSubscribeTopic, PayloadOpen := 'OPEN', PayloadClose := 'CLOSE', PayloadStop := 'STOP', StateTopic := THIS^.sMQTTPublishTopic, StateOpen := 'OPEN', StateOpening := 'OPENING', StateClosed := 'CLOSED', StateClosing := 'CLOSING', StateStopped := 'STOPPED', DeviceClass := DeviceClass, PositionTopic := CONCAT(THIS^.sMQTTPublishTopic, '/POSITION'), SetPositionTopic := CONCAT(THIS^.sMQTTSubscribeTopic, '/POSITION'), PositionOpen := 100, PositionClosed := 0);
bInitMqttDiscoveryDone := TRUE; END_IF

SUPER^._sInstancePath := THIS^.sInstancePath; // Due to reflection its location is important

(*pass trough*)
THIS^.pMqttPublishQueue := pMqttPublishQueue;
THIS^.psMqttPublishTopicPrefix := MQTTPublishPrefix;
THIS^.psMqttSubscribeTopicPrefix := MQTTSubscribePrefix;

SUPER^.InitBaseMqtt();
pMqttCallbackCollector^.put(instance := THIS^); // register the FB against the collector so mqtt events can be received

(* --- self-wiring prologue ----------------------------------------------------
   Makes the InitMqtt and InitMqttDiscovery* calls optional. Set FriendlyName at
   the declaration site and this block wires itself from GVL_MQTT on its
   first cyclic call, then announces itself to Home Assistant.

   Deliberately in the body rather than in FB_init: it dereferences GVL members
   and reads the reflection instance path, and doing that during initialisation
   would rely on an ordering nothing enforces and the compiler cannot check. The
   body is the same lifecycle phase the init actions used, so this is not merely
   safe, it is the phase that already works today.

   The wiring calls this block's own unmodified InitMqtt / InitMqttDiscovery*
   methods, so anything published - topics and discovery JSON alike - is produced
   by exactly the code that produces it today. Only the trigger moved.

   Dormant while FriendlyName is empty, so existing projects and existing call
   sites keep working untouched.

   A block wired this way MUST be called cyclically. An instance whose body never
   runs is now unwired and absent from Home Assistant, where the init action used
   to wire it regardless. Nothing warns about that.  *)
IF FriendlyName <> '' THEN

	IF NOT bInitMqttDone THEN
		THIS^.InitMqtt(
			MQTTPublishPrefix := ADR(GVL_MQTT.MqttPubDimmerPrefix),
			MQTTSubscribePrefix := ADR(GVL_MQTT.MqttSubDimmerPrefix),
			pMqttPublishQueue := ADR(GVL_MQTT.fbMqttPublishQueue),
			pMqttCallbackCollector := ADR(GVL_MQTT.collector_FB_DIMMER_MQTT),
			OutputDimmer := TRUE,
			Qos_Dimm := MQTT.QoS.ExactlyOnce,
			Delta_Dimm := 5);
	END_IF

	IF bInitMqttDone AND NOT bInitMqttDiscoveryDone THEN
		THIS^.InitMqttDiscovery(
			Device := ADR(GVL_MQTT.PLC_Device),
			Name := FriendlyName);
	END_IF

END_IF

IF bStartup THEN
	byOutInternal := byPreviousOUT;
	Q := bPreviousQ;
END_IF

IF RST THEN
	IF rst_out THEN byOutInternal := 0; END_IF;
	Q := FALSE;
	dir := byOutInternal > 127;
ELSIF PRIO_HIGH THEN
	Q := TRUE;
	byOutInternal := 255;
ELSIF PRIO_LOW THEN
	Q := FALSE;
ELSIF bMqttHighRequest THEN
	Q:= TRUE;
	bMqttHighRequest := FALSE;
	bMqttLowRequest := FALSE;
ELSIF bMqttLowRequest THEN
	Q:= FALSE;
	bMqttHighRequest := FALSE;
	bMqttLowRequest := FALSE;
ELSIF set THEN
	byOutInternal := val;
	Q := TRUE;
	(* set direction to up when value < 127 otherwise set dir down dir is reversed because next action will reverse again *)
	dir := byOutInternal > 127;
ELSIF SINGLE THEN
	(* a single click reverses output Q *)
	Q := NOT Q;
	(* when E_DIMMER is turned on we need to limit out to min and max limits *)
	IF Q THEN byOutInternal := LIMIT(MAX(byOutInternal,1), byOutInternal, MAX_ON);	END_IF;
	(* set the appropriate direction of E_DIMMER dir is reversed because next action will reverse again *)
	dir := byOutInternal > 127;
ELSIF LONG THEN
	IF NOT Q THEN
		IF SOFT_DIMM THEN
			byOutInternal := 1;
			dir := TRUE;
		ELSE
			byOutInternal := LIMIT(MAX(MIN_ON,1), byOutInternal, MAX_ON);
			DIR := byOutInternal < 127;
		END_IF;
		Q := TRUE;
	ELSE
		(* reverse direction with every long click *)
		dir := NOT dir;
	END_IF;
END_IF;


(* while dimming is active ramp the output out up or down *)
dim(DIR := dir, e := P_LONG AND Q, TR := T_DIMM, rmp := byOutInternal);

(* reverse direction when limits are reached *)
IF byOutInternal = 0 THEN
	dir := TRUE;
ELSIF byOutInternal = 255 THEN
	dir := FALSE;
END_IF;

(* limit the maximum runtime *)
IF t_ON_MAX > t#0s THEN
	fbT3(in := q, pt := T_ON_MAX);
	Q := Q XOR fbT3.Q;
END_IF;

(* Scale the internal OUT to the actual OUT *)
LIN_TRAFO(
		IN:= byOutInternal,
		IN_MIN:= 0,
		IN_MAX:= 255,
		OUT_MIN:=OUT_LinearScaleMin,
		OUT_MAX:=OUT_LinearScaleMax
	);
OUT:= REAL_TO_WORD(LIN_TRAFO.OUT);
IF Q THEN
	Q_OUT:= OUT;
ELSE
	Q_OUT:= 0;
END_IF

IF ((ABS(BYTE_TO_INT(byPreviousOUT) - BYTE_TO_INT(byOutInternal)) >= Delta_Dimm AND byOutInternal <> byPreviousOUT) OR bStartup AND byOutInternal <> byPreviousOUT OR bStartup AND OutputDimmer) AND bInitMqttDone THEN
	byPreviousOUT:=byOutInternal;
	pMqttPublishQueue^.AddMessage(		
		Payload := BYTE_TO_STRING(byOutInternal),
		Topic := CONCAT(CONCAT(psMqttPublishTopicPrefix^, MqttPublishTopicSuffix), '/OUT'),
		Qos := MQTT.QoS.ExactlyOnce,
		MqttRetain := TRUE
	);
END_IF

IF (Q <> bPreviousQ OR bStartup) AND bInitMqttDone THEN
	bPreviousQ:=Q;
	pMqttPublishQueue^.AddMessage(
		Payload := BOOL_TO_STRING(Q),
		Topic := CONCAT(CONCAT(psMqttPublishTopicPrefix^, MqttPublishTopicSuffix), '/Q'),
		Qos := Qos_Dimm,
		MqttRetain := TRUE
	);
END_IF

bStartup:=FALSE;

//first check if Mqtt is initialized, otherwise do nothing
IF NOT(bInitMqttDone) THEN
	//mark the interface call from the collector as done
	PublishReceived := TRUE;
//check if the packet is for this FB
ELSIF CONCAT(sMQTTSubscribeTopic,'/Q') =  Data.TopicOut^ THEN
	//mark the interface call from the collector as done
	PublishReceived := TRUE;
	IF CommonTypesAndFunctions.StrEquals(str1:= Data.PayloadString, str2:= ADR('TRUE')) THEN
		bMqttHighRequest := TRUE;
	ELSIF CommonTypesAndFunctions.StrEquals(str1:= Data.PayloadString, str2:= ADR('FALSE')) THEN
		bMqttLowRequest := TRUE;
	END_IF;

ELSIF CONCAT(sMQTTSubscribeTopic,'/OUT') =  Data.TopicOut^ THEN
	//mark the interface call from the collector as done
	PublishReceived := TRUE;
	IF OSCAT_BASIC.IS_CC(str:= Data.PayloadString^,cmp:='0123456789.') AND THIS^.PRIO_HIGH = FALSE THEN
		THIS^.byOutInternal:=STRING_TO_BYTE(Data.PayloadString^);
	END_IF
END_IF

THIS^.T_Debounce:=T_Debounce;
THIS^.T_Reconfig:=T_Reconfig;
THIS^.T_On_Max:=T_On_Max;
THIS^.T_Dimm_Start:=T_Dimm_Start;
THIS^.T_Dimm:=T_Dimm;
THIS^.Min_On:=Min_On;
THIS^.Max_On:=Max_On;
THIS^.Soft_Dimm:=Soft_Dimm;
THIS^.Rst_Out:=Rst_Out;
