id := SUPER^.ResolveEntityId(overruleId);
Device^.CreateLightDimmerEntity( Name := name, Id := Id, Meta := meta, CommandTopic := CONCAT(THIS^.sMQTTSubscribeTopic,'/Q'), PayloadOn := 'TRUE', PayloadOff := 'FALSE', StateTopic := CONCAT(THIS^.sMQTTPublishTopic,'/Q'), BrightnessCommandTopic := CONCAT(THIS^.sMQTTSubscribeTopic,'/OUT'), BrightnessStateTopic := CONCAT(THIS^.sMQTTPublishTopic,'/OUT'), BrightnessScale := 255);
bInitMqttDiscoveryDone := TRUE; END_IF

fbDaliSendFadeTime(
	typBallast := BALLAST,
	bFadeTime := 2, // 1 sec
	xUpdate := fbDaliConfigSyncSignalGenerator.OUT
	);

fbDaliSendFadeRate(
	typBallast := BALLAST,
	bFadeRate := 2, // 1 sec
	xUpdate := fbDaliConfigSyncSignalGenerator.OUT
	);

fbDaliSendDimValue(
	typBallast := BALLAST,
	rDimValue := rDimValue,
	xUpdate := fbDaliSyncSignalGenerator.OUT OR bMqttSendOffUpdate OR bMqttSendOnUpdate);

fbDaliSyncSignalGenerator(
	ENABLE := TRUE,
	TIMEHIGH := T#1S,
	TIMELOW := T#1M);

fbDaliConfigSyncSignalGenerator(
	ENABLE := TRUE,
	TIMEHIGH := T#1S,
	TIMELOW := T#24H);

fbToggleRTrigger(CLK:=TOGGLE);

// Regular push
IF(fbToggleRTrigger.Q AND rDimValue = 0) THEN
	SetDimValue(100);
ELSIF(fbToggleRTrigger.Q AND rDimValue > 0) THEN
	SetDimValue(0);
END_IF

// Long push
IF P_LONG THEN
	SetDimValue(rDimValue + iDimDirection);
END_IF

IF bMqttSendBrightnessUpdate OR bStartup AND bInitMqttDone THEN
	pMqttPublishQueue^.AddMessage(		
		Payload := REAL_TO_STRING(rDimValue),
		Topic := CONCAT(THIS^.sMQTTPublishTopic, '/BRIGHTNESS'),
		Qos := MQTT.QoS.ExactlyOnce,
		MqttRetain := TRUE
	);
	bMqttSendBrightnessUpdate := FALSE;
END_IF

IF bMqttSendOnUpdate OR (bStartup AND rDimValue > 0) AND bInitMqttDone THEN
	pMqttPublishQueue^.AddMessage(		
		Payload := 'ON',
		Topic := THIS^.sMQTTPublishTopic,
		Qos := MQTT.QoS.ExactlyOnce,
		MqttRetain := TRUE
	);
	bMqttSendOnUpdate := FALSE;
END_IF

IF bMqttSendOffUpdate OR (bStartup AND rDimValue = 0) AND bInitMqttDone THEN
	pMqttPublishQueue^.AddMessage(
		Payload := 'OFF',
		Topic := THIS^.sMQTTPublishTopic,
		Qos := MQTT.QoS.ExactlyOnce,
		MqttRetain := TRUE
	);
	bMqttSendOffUpdate := FALSE;
END_IF

bStartup:=FALSE;
STATUS_LED := REAL_TO_BOOL(rDimValue);

SUPER^._sInstancePath := THIS^.sInstancePath; // Due to reflection its location is important

(*pass trough*)
THIS^.pMqttPublishQueue := pMqttPublishQueue;
THIS^.psMqttPublishTopicPrefix:=MQTTPublishPrefix;
THIS^.psMqttSubscribeTopicPrefix:=MQTTSubscribePrefix;
THIS^.pMqttPublishQueue:=pMqttPublishQueue;

SUPER^.InitBaseMqtt();
pMqttCallbackCollector^.put(instance:= THIS^); // register the FB agains the collector so mqtt events can be received

//first check if Mqtt is initialized, otherwise do nothing
IF NOT(bInitMqttDone) THEN
	//mark the interface call from the collector as done
	PublishReceived := TRUE;

ELSIF sMQTTSubscribeTopic =  Data.TopicOut^ THEN
	IF CommonTypesAndFunctions.StrEquals(str1:= Data.PayloadString, str2:= ADR('ON')) THEN
		SetDimValue(100);
	ELSIF CommonTypesAndFunctions.StrEquals(str1:= Data.PayloadString, str2:= ADR('OFF')) THEN
		SetDimValue(0);
	END_IF

ELSIF CONCAT(sMQTTSubscribeTopic, '/BRIGHTNESS') =  Data.TopicOut^ THEN
	IF OSCAT_BASIC.IS_CC(str:= Data.PayloadString^,cmp:='0123456789.') AND THIS^.PRIO_HIGH = FALSE THEN
		SetDimValue(STRING_TO_REAL(Data.PayloadString^));
	END_IF
END_IF

THIS^.bMqttSendBrightnessUpdate := TRUE;

IF THIS^.rDimValue = 0 AND Value > 0 THEN
	THIS^.bMqttSendOnUpdate := TRUE;
END_IF

IF THIS^.rDimValue > 0 AND Value = 0 THEN
	THIS^.bMqttSendOffUpdate := TRUE;
END_IF

IF Value = 0 THEN
	iDimDirection := 1;
ELSIF Value = 100 THEN
	iDimDirection := -1;
END_IF

THIS^.rDimValue := Value;

(* --- self-wiring prologue ----------------------------------------------------
   Makes the InitMqtt and InitMqttDiscovery* calls optional. Set FriendlyName at
   the declaration site and this block wires itself from GVL_MQTT on its
   first cyclic call, then announces itself to Home Assistant.

   Deliberately in the body rather than in FB_init: it dereferences GVL members
   and reads the reflection instance path, and doing that during initialisation
   would rely on an ordering nothing enforces and the compiler cannot check. The
   body is the same lifecycle phase the init actions used, so this is not merely
   safe, it is the phase that already works today.

   The wiring calls this block's own unmodified InitMqtt / InitMqttDiscovery*
   methods, so anything published - topics and discovery JSON alike - is produced
   by exactly the code that produces it today. Only the trigger moved.

   Dormant while FriendlyName is empty, so existing projects and existing call
   sites keep working untouched.

   A block wired this way MUST be called cyclically. An instance whose body never
   runs is now unwired and absent from Home Assistant, where the init action used
   to wire it regardless. Nothing warns about that.  *)
IF FriendlyName <> '' THEN

	IF NOT bInitMqttDone THEN
		THIS^.InitMqtt(
			MQTTPublishPrefix := ADR(GVL_MQTT.MqttPubDimmerPrefix),
			MQTTSubscribePrefix := ADR(GVL_MQTT.MqttSubDimmerPrefix),
			pMqttPublishQueue := ADR(GVL_MQTT.fbMqttPublishQueue),
			pMqttCallbackCollector := ADR(GVL_MQTT.collector_FB_DIMMER_MQTT),
			OutputDimmer := TRUE,
			Qos_Dimm := MQTT.QoS.ExactlyOnce,
			Delta_Dimm := 5);
	END_IF

	IF bInitMqttDone AND NOT bInitMqttDiscoveryDone THEN
		THIS^.InitMqttDiscovery(
			Device := ADR(GVL_MQTT.PLC_Device),
			Name := FriendlyName);
	END_IF

END_IF

IF bStartup THEN
	byOutInternal := byPreviousOUT;
	Q := bPreviousQ;
END_IF

IF RST THEN
	IF rst_out THEN byOutInternal := 0; END_IF;
	Q := FALSE;
	dir := byOutInternal > 127;
ELSIF PRIO_HIGH THEN
	Q := TRUE;
	byOutInternal := 255;
ELSIF PRIO_LOW THEN
	Q := FALSE;
ELSIF bMqttHighRequest THEN
	Q:= TRUE;
	bMqttHighRequest := FALSE;
	bMqttLowRequest := FALSE;
ELSIF bMqttLowRequest THEN
	Q:= FALSE;
	bMqttHighRequest := FALSE;
	bMqttLowRequest := FALSE;
ELSIF set THEN
	byOutInternal := val;
	Q := TRUE;
	(* set direction to up when value < 127 otherwise set dir down dir is reversed because next action will reverse again *)
	dir := byOutInternal > 127;
ELSIF SINGLE THEN
	(* a single click reverses output Q *)
	Q := NOT Q;
	(* when E_DIMMER is turned on we need to limit out to min and max limits *)
	IF Q THEN byOutInternal := LIMIT(MAX(byOutInternal,1), byOutInternal, MAX_ON);	END_IF;
	(* set the appropriate direction of E_DIMMER dir is reversed because next action will reverse again *)
	dir := byOutInternal > 127;
ELSIF LONG THEN
	IF NOT Q THEN
		IF SOFT_DIMM THEN
			byOutInternal := 1;
			dir := TRUE;
		ELSE
			byOutInternal := LIMIT(MAX(MIN_ON,1), byOutInternal, MAX_ON);
			DIR := byOutInternal < 127;
		END_IF;
		Q := TRUE;
	ELSE
		(* reverse direction with every long click *)
		dir := NOT dir;
	END_IF;
END_IF;


(* while dimming is active ramp the output out up or down *)
dim(DIR := dir, e := P_LONG AND Q, TR := T_DIMM, rmp := byOutInternal);

(* reverse direction when limits are reached *)
IF byOutInternal = 0 THEN
	dir := TRUE;
ELSIF byOutInternal = 255 THEN
	dir := FALSE;
END_IF;

(* limit the maximum runtime *)
IF t_ON_MAX > t#0s THEN
	fbT3(in := q, pt := T_ON_MAX);
	Q := Q XOR fbT3.Q;
END_IF;

(* Scale the internal OUT to the actual OUT *)
LIN_TRAFO(
		IN:= byOutInternal,
		IN_MIN:= 0,
		IN_MAX:= 255,
		OUT_MIN:=OUT_LinearScaleMin,
		OUT_MAX:=OUT_LinearScaleMax
	);
OUT:= REAL_TO_WORD(LIN_TRAFO.OUT);
IF Q THEN
	Q_OUT:= OUT;
ELSE
	Q_OUT:= 0;
END_IF

IF ((ABS(BYTE_TO_INT(byPreviousOUT) - BYTE_TO_INT(byOutInternal)) >= Delta_Dimm AND byOutInternal <> byPreviousOUT) OR bStartup AND byOutInternal <> byPreviousOUT OR bStartup AND OutputDimmer) AND bInitMqttDone THEN
	byPreviousOUT:=byOutInternal;
	pMqttPublishQueue^.AddMessage(		
		Payload := BYTE_TO_STRING(byOutInternal),
		Topic := CONCAT(THIS^.sMQTTPublishTopic,'/OUT'),
		Qos := MQTT.QoS.ExactlyOnce,
		MqttRetain := TRUE
	);
END_IF

IF (Q <> bPreviousQ OR bStartup) AND bInitMqttDone THEN
	bPreviousQ:=Q;
	pMqttPublishQueue^.AddMessage(
		Payload := BOOL_TO_STRING(Q),
		Topic := CONCAT(THIS^.sMQTTPublishTopic,'/Q'),
		Qos := Qos_Dimm,
		MqttRetain := TRUE
	);
END_IF

bStartup:=FALSE;

(* DMX specific *)
IF bInitDmxDone THEN 
	IF Q THEN
		IF pDmxValues^.BUFFER[DmxChannel-1] <> byOutInternal THEN
			pDmxValues^.BUFFER[DmxChannel-1] := byOutInternal;
		END_IF
	ELSE 
		IF pDmxValues^.BUFFER[DmxChannel-1] <> 0 THEN
			pDmxValues^.BUFFER[DmxChannel-1] := 0;
		END_IF
	END_IF
END_IF

IF bInitMqttDone AND NOT bInitMqttDiscoveryDone THEN
id := SUPER^.ResolveEntityId(overruleId);
Device^.CreateLightDimmerEntity( Name := name, Id := Id, Meta := meta, CommandTopic := CONCAT(THIS^.sMQTTSubscribeTopic,'/Q'), PayloadOn := 'TRUE', PayloadOff := 'FALSE', StateTopic := CONCAT(THIS^.sMQTTPublishTopic,'/Q'), BrightnessCommandTopic := CONCAT(THIS^.sMQTTSubscribeTopic,'/OUT'), BrightnessStateTopic := CONCAT(THIS^.sMQTTPublishTopic,'/OUT'), BrightnessScale := 255, DmxChannel := THIS^.DmxChannel, DmxWidth := THIS^.DmxWidth, DmxUniverse := THIS^.DmxUniverse);
bInitMqttDiscoveryDone := TRUE; END_IF

IF NOT THIS^.bInitDmxDone THEN
	THIS^.DmxChannel := DmxChannel;
	THIS^.pDmxValues := pDmxValues;
	THIS^.DmxWidth := DmxWidth;
	THIS^.DmxUniverse := DmxUniverse;
	THIS^.bInitDmxDone := TRUE;
END_IF

SUPER^._sInstancePath := THIS^.sInstancePath; // Due to reflection its location is important

(*pass trough*)
THIS^.pMqttPublishQueue := pMqttPublishQueue;
THIS^.psMqttPublishTopicPrefix:=MQTTPublishPrefix;
THIS^.psMqttSubscribeTopicPrefix:=MQTTSubscribePrefix;
THIS^.pMqttPublishQueue:=pMqttPublishQueue;

// E_DIMMER specific
THIS^.OutputDimmer:=OutputDimmer;
THIS^.Qos_Dimm:=Qos_Dimm;
THIS^.Delta_Dimm:=Delta_Dimm;


SUPER^.InitBaseMqtt();
pMqttCallbackCollector^.put(instance:= THIS^); // register the FB agains the collector so mqtt events can be received

THIS^.T_Debounce:=T_Debounce;
THIS^.T_Reconfig:=T_Reconfig;
THIS^.T_On_Max:=T_On_Max;
THIS^.T_Dimm_Start:=T_Dimm_Start;
THIS^.T_Dimm:=T_Dimm;
THIS^.Min_On:=Min_On;
THIS^.Max_On:=Max_On;
THIS^.Soft_Dimm:=Soft_Dimm;
THIS^.Rst_Out:=Rst_Out;
THIS^.OUT_LinearScaleMin:=OUT_LinearScaleMin;
THIS^.OUT_LinearScaleMax:=OUT_LinearScaleMax;

//first check if Mqtt is initialized, otherwise do nothing
IF NOT(bInitMqttDone) THEN
	//mark the interface call from the collector as done
	PublishReceived := TRUE;
//check if the packet is for this FB
ELSIF CONCAT(sMQTTSubscribeTopic,'/Q') =  Data.TopicOut^ THEN
	IF CommonTypesAndFunctions.StrEquals(str1:= Data.PayloadString, str2:= ADR('TRUE')) THEN
		bMqttHighRequest := TRUE;
	ELSIF CommonTypesAndFunctions.StrEquals(str1:= Data.PayloadString, str2:= ADR('FALSE')) THEN
		bMqttLowRequest := TRUE;
	END_IF;

ELSIF CONCAT(sMQTTSubscribeTopic,'/OUT') =  Data.TopicOut^ THEN
	IF OSCAT_BASIC.IS_CC(str:= Data.PayloadString^,cmp:='0123456789.') AND THIS^.PRIO_HIGH = FALSE THEN
		THIS^.byOutInternal:=STRING_TO_BYTE(Data.PayloadString^);
	END_IF


// Legacy! backwards compatiably with /+ topics instead of /#
ELSIF CommonTypesAndFunctions.StrEqualsAtStart(str1:= ADR(sMQTTSubscribeTopic), str2:= Data.TopicOut) THEN
	//mark the interface call from the collector as done
	PublishReceived := TRUE;
	//now process the data
	IF CommonTypesAndFunctions.StrEquals(str1:= Data.PayloadString, str2:= ADR('TRUE')) THEN
		bMqttHighRequest := TRUE;
	ELSIF CommonTypesAndFunctions.StrEquals(str1:= Data.PayloadString, str2:= ADR('FALSE')) THEN
		bMqttLowRequest := TRUE;
	ELSIF OSCAT_BASIC.IS_CC(str:= Data.PayloadString^,cmp:='0123456789.') AND THIS^.PRIO_HIGH = FALSE THEN
		THIS^.byOutInternal:=STRING_TO_BYTE(Data.PayloadString^);
	END_IF
END_IF

SUPER^._sInstancePath := THIS^.sInstancePath; // Due to reflection its location is important

(*pass trough*)
THIS^.pMqttPublishQueue := pMqttPublishQueue;
THIS^.psMqttPublishTopicPrefix:=MQTTPublishPrefix;
SUPER^.InitBaseMqtt();

IF bInitMqttDone AND NOT bInitMqttDiscoveryDone THEN
id := SUPER^.ResolveEntityId(overruleId);
Device^.CreateBinarySensorEntity( Id := id, Name := name, Meta := meta, StateTopic := THIS^.sMQTTPublishTopic, PayloadOn := 'TRUE', PayloadOff := 'FALSE', DeviceClass := DeviceClass);
bInitMqttDiscoveryDone := TRUE; END_IF

// What the circuits are asking for. Built from THERMOSTAT and deliberately NOT from
// VALVE - see the interlock note below, where that distinction is the whole point.
bHeatRequest := FALSE;
FOR iI := 1 TO ciValveCount DO
	bHeatRequest := bHeatRequest OR THERMOSTAT[iI];
END_FOR

// Valves are NC: a valve is powered - open - exactly when its own circuit asks for
// heat, and closed otherwise.
//
// The exception is the interlock: FB_HVAC_PUMP_MQTT holds its output for MIN_ONTIME
// after its IN drops, so a manifold that closes the instant demand ends leaves the
// pump turning against shut valves. Whether that became a real dead-head depended on
// two timings configured on two different blocks - ValveCycleTime here against the
// pump's MIN_ONTIME there - with nothing in the code relating them. So while
// PUMP_MIN_ONTIME_ACTIVE is set, the circuits that were last flowing stay open and
// the pump keeps a path. This is requirement 2.3 in PRG_HVAC.HVAC_RUN, written down
// when this chain was designed and not implemented until now.
//
// The hold cannot latch on. It re-opens valves, but bHeatRequest stays FALSE, so
// this block never re-requests the pump: the pump's minimum on-time expires,
// PUMP_MIN_ONTIME_ACTIVE clears and the valves close. Building bHeatRequest from
// VALVE[] instead would close that loop and hold the pump on for ever. That used to
// be an identity - every VALVE[iI] was THERMOSTAT[iI], so the two ORs were the same
// value, and a comment here said so - and it is not an identity any more. Do not
// simplify it back.
IF bHeatRequest THEN
	FOR iI := 1 TO ciValveCount DO
		VALVE[iI] := THERMOSTAT[iI];
		abValveHeld[iI] := THERMOSTAT[iI];
	END_FOR
ELSE
	// No circuit is asking for heat: the valves are shut unless the pump is still
	// running out its minimum on-time, in which case the ones that were flowing
	// stay open until it stops.
	FOR iI := 1 TO ciValveCount DO
		VALVE[iI] := PUMP_MIN_ONTIME_ACTIVE AND abValveHeld[iI];
	END_FOR
END_IF

// Pump should only start when valves had time to switch to their correct position
fbPumpDelay(IN := bHeatRequest,
	PT := ValveCycleTime);

PUMP := bHeatRequest AND fbPumpDelay.Q;

// Detect edges on valves for MQTT messaging, and publish only the ones that moved.
// The topics are retained because Home Assistant reads them on reconnect, which is
// also why bStartup forces a publish of all eight on the first cycle after init.
// A valve held open by the interlock publishes TRUE for as long as it is held, which
// is what Home Assistant should see: the valve really is open.
FOR iI := 1 TO ciValveCount DO
	afbRTrigValve[iI](CLK := VALVE[iI]);
	afbFTrigValve[iI](CLK := VALVE[iI]);

	IF ((afbRTrigValve[iI].Q OR afbFTrigValve[iI].Q) OR bStartup) AND bInitMqttDone THEN
		pMqttPublishQueue^.AddMessage(
			Payload := BOOL_TO_STRING(VALVE[iI]),
			Topic := CONCAT(sMQTTPublishTopic, CONCAT('/Valves/', casValveNames[iI])),
			Qos := MQTT.QoS.ExactlyOnce,
			MqttRetain := TRUE
		);
	END_IF
END_FOR

bStartup := FALSE;

SUPER^._sInstancePath := THIS^.sInstancePath; // Due to reflection its location is important

(*pass trough*)
THIS^.pMqttPublishQueue := pMqttPublishQueue;
THIS^.psMqttPublishTopicPrefix:=MQTTPublishPrefix;
SUPER^.InitBaseMqtt();

(* --- self-wiring prologue ---------------------------------------------------- Makes the InitMqtt and InitMqttDiscovery* calls optional. Set FriendlyName at the declaration site and this block wires itself from GVL_MQTT on its first cyclic call, then announces itself to Home Assistant.
Deliberately in the body rather than in FB_init: it dereferences GVL members and reads the reflection instance path, and doing that during initialisation would rely on an ordering nothing enforces and the compiler cannot check. The body is the same lifecycle phase the init actions used, so this is not merely safe, it is the phase that already works today.
The wiring calls this block's own unmodified InitMqtt / InitMqttDiscovery* methods, so anything published - topics and discovery JSON alike - is produced by exactly the code that produces it today. Only the trigger moved.
Dormant while FriendlyName is empty, so existing projects and existing call sites keep working untouched.
A block wired this way MUST be called cyclically. An instance whose body never runs is now unwired and absent from Home Assistant, where the init action used to wire it regardless. Nothing warns about that. *) IF FriendlyName <> '' THEN
IF NOT bInitMqttDone THEN THIS^.InitMqtt( MQTTPublishPrefix := ADR(GVL_MQTT.MqttPubHVACPrefix), pMqttPublishQueue := ADR(GVL_MQTT.fbMqttPublishQueue)); END_IF
IF bInitMqttDone AND NOT bInitMqttDiscoveryDone THEN THIS^.InitMqttDiscovery( Device := ADR(GVL_MQTT.PLC_Device), Name := FriendlyName); END_IF
END_IF
fbMinOntimeTimer(IN := IN, PT := MIN_ONTIME); MIN_ONTIME_ACTIVE := NOT(fbMinOntimeTimer.Q) AND PUMP;
fbActuator( IN := IN, MANUAL := FALSE, RST := FALSE, MIN_ONTIME := MIN_ONTIME, MIN_OFFTIME := MIN_OFFTIME, RUN_EVERY := T#0S, PUMP => PUMP, RUNTIME := RUNTIME, CYCLES := CYCLES);
//Timer to keep track of ontime
HEAT_REQUEST := PUMP;
IF ((bPreviousState <> PUMP) OR bStartup) AND bInitMqttDone THEN pMqttPublishQueue^.AddMessage( Payload := BOOL_TO_STRING(PUMP), Topic := sMQTTPublishTopic, Qos := MQTT.QoS.ExactlyOnce, MqttRetain := TRUE ); bStartup:=FALSE; END_IF
bPreviousState := PUMP;

SUPER^._sInstancePath := THIS^.sInstancePath; // Due to reflection its location is important

(*pass trough*)
THIS^.pMqttPublishQueue := pMqttPublishQueue;
THIS^.psMqttPublishTopicPrefix:=MQTTPublishPrefix;
SUPER^.InitBaseMqtt();

IF bInitMqttDone AND NOT bInitMqttDiscoveryDone THEN
id := SUPER^.ResolveEntityId(overruleId);
Device^.CreateBinarySensorEntity( Id := id, Name := name, Meta := meta, StateTopic := THIS^.sMQTTPublishTopic, PayloadOn := 'TRUE', PayloadOff := 'FALSE', DeviceClass := DeviceClass);
bInitMqttDiscoveryDone := TRUE; END_IF

SUPER^._sInstancePath := THIS^.sInstancePath; // Due to reflection its location is important

(*pass trough*)
THIS^.pMqttPublishQueue := pMqttPublishQueue;
THIS^.psMqttPublishTopicPrefix:=MQTTPublishPrefix;
THIS^.psMqttSubscribeTopicPrefix:=MQTTSubscribePrefix;
THIS^.pMqttPublishQueue:=pMqttPublishQueue;

SUPER^.InitBaseMqtt();
pMqttCallbackCollector^.put(instance:= THIS^); // register the FB agains the collector so mqtt events can be received

IF bInitMqttDone AND NOT bInitMqttDiscoveryDone THEN
id := SUPER^.ResolveEntityId(overruleId);
Device^.CreateClimateEntity( Id := id, Name := name, Meta := meta, InitialDesiredTemperature := REAL_TO_INT(rDesiredTemp), CurrentTemperatureTopic := CONCAT(sMQTTPublishTopic, '/TEMP'), CurrentHumidityTopic := CONCAT(sMQTTPublishTopic, '/HUM'), ModeCommandTopic := CONCAT(THIS^.sMQTTSubscribeTopic, '/MODE'), ModeStateTopic := CONCAT(THIS^.sMQTTPublishTopic, '/MODE'), TemperatureCommandTopic := CONCAT(THIS^.sMQTTSubscribeTopic, '/DESIRED_TEMP') , TemperatureStateTopic := CONCAT(THIS^.sMQTTPublishTopic, '/DESIRED_TEMP'), TempStep := TempStep);
bInitMqttDiscoveryDone := TRUE; END_IF

//first check if Mqtt is initialized, otherwise do nothing
IF NOT(bInitMqttDone) THEN
	//mark the interface call from the collector as done
	PublishReceived := TRUE;
//check if the packet is for this FB
ELSIF CONCAT(sMQTTSubscribeTopic,'/DESIRED_TEMP') =  Data.TopicOut^ THEN
	//mark the interface call from the collector as done
	PublishReceived := TRUE;
	//check if temp is numeric, then assign it;
	IF OSCAT_BASIC.IS_CC(str:= Data.PayloadString^,cmp:='0123456789.') THEN
		 // temperature requested higher then max allowed temp; set to max allowed temp
		 IF STRING_TO_REAL(Data.PayloadString^) > THIS^.MaxAllowedTemp THEN
			 THIS^.rDesiredTemp := THIS^.MaxAllowedTemp;		 
			 THIS^.pMqttPublishQueue^.AddMessage(
				Payload := REAL_TO_STRING(THIS^.MaxAllowedTemp),
				Topic := CONCAT(sMQTTPublishTopic, '/DESIRED_TEMP'),
				Qos := MQTT.QoS.ExactlyOnce,
				MqttRetain := TRUE
			);
		 // temperature requested lower then min allowed temp: set to min allowed temp
		 ELSIF STRING_TO_REAL(Data.PayloadString^) < THIS^.MinAllowedTemp THEN
			 THIS^.rDesiredTemp := THIS^.MinAllowedTemp;			 
			 THIS^.pMqttPublishQueue^.AddMessage(
				Payload := REAL_TO_STRING(THIS^.MinAllowedTemp),
				Topic := CONCAT(sMQTTPublishTopic, '/DESIRED_TEMP'),
				Qos := MQTT.QoS.ExactlyOnce,
				MqttRetain := TRUE
			);
		 ELSE
			 THIS^.rDesiredTemp := STRING_TO_REAL(Data.PayloadString^);			 
			 THIS^.pMqttPublishQueue^.AddMessage(
				Payload := Data.PayloadString^,
				Topic := CONCAT(sMQTTPublishTopic, '/DESIRED_TEMP'),
				Qos := MQTT.QoS.ExactlyOnce,
				MqttRetain := TRUE
			);
		 END_IF
	END_IF

ELSIF CONCAT(sMQTTSubscribeTopic,'/MODE') =  Data.TopicOut^ THEN
	//mark the interface call from the collector as done
	PublishReceived := TRUE;
	//check if the mode is known and if so set it
	IF CommonTypesAndFunctions.StrEquals(str1:= Data.PayloadString, str2:= ADR('auto')) THEN
		THIS^.eHvacMode := E_HVAC_MODE.auto;		
	 	THIS^.pMqttPublishQueue^.AddMessage(
			Payload := Data.PayloadString^,
			Topic := CONCAT(sMQTTPublishTopic, '/MODE'),
			Qos := MQTT.QoS.ExactlyOnce,
			MqttRetain := TRUE
		);
	ELSIF CommonTypesAndFunctions.StrEquals(str1:= Data.PayloadString, str2:= ADR('off')) THEN
		THIS^.eHvacMode := E_HVAC_MODE.off;		
	 	THIS^.pMqttPublishQueue^.AddMessage(
			Payload := Data.PayloadString^,
			Topic := CONCAT(sMQTTPublishTopic, '/MODE'),
			Qos := MQTT.QoS.ExactlyOnce,
			MqttRetain := TRUE
		);
	ELSIF CommonTypesAndFunctions.StrEquals(str1:= Data.PayloadString, str2:= ADR('heat')) THEN
		THIS^.eHvacMode := E_HVAC_MODE.heat;		
	 	THIS^.pMqttPublishQueue^.AddMessage(
			Payload := Data.PayloadString^,
			Topic := CONCAT(sMQTTPublishTopic, '/MODE'),
			Qos := MQTT.QoS.ExactlyOnce,
			MqttRetain := TRUE
		);
	END_IF;
END_IF

THIS^.MinAllowedTemp := MinAllowedTemp;
THIS^.MaxAllowedTemp := MaxAllowedTemp;
THIS^.Hysteresis := Hysteresis;

(*Define instance names*)
psInstanceNamePt := CommonTypesAndFunctions.FindLastDot(ADR(_sInstancePath)) + 1;

DeviceName := LEFT(_sInstancePath,find(_sInstancePath, '.' )-1  ) ;

// Publish (Out);
IF	psMqttPublishTopicPrefix <> 0 THEN
	THIS^.MqttPublishTopicSuffix := psInstanceNamePt^;
	THIS^.sMQTTPublishTopic := CONCAT(psMqttPublishTopicPrefix^, THIS^.MqttPublishTopicSuffix);
END_IF

// Subscribe (In)
IF	psMqttSubscribeTopicPrefix <> 0 THEN
	THIS^.sMqttSubscribeTopicSuffix := psInstanceNamePt^;
	THIS^.sMQTTSubscribeTopic := CONCAT(psMqttSubscribeTopicPrefix^ ,THIS^.sMqttSubscribeTopicSuffix);
END_IF

(* Make truncation detectable. IEC cuts an over-long CONCAT short without any
   error, so without this the only symptom is an entity that never appears. *)
IF psMqttPublishTopicPrefix <> 0 THEN
	IF LEN(psMqttPublishTopicPrefix^) + LEN(THIS^.MqttPublishTopicSuffix) > GVL_MQTT.MQTT_TOPIC_LEN THEN
		THIS^.bTopicTruncated := TRUE;
	END_IF
END_IF
IF psMqttSubscribeTopicPrefix <> 0 THEN
	IF LEN(psMqttSubscribeTopicPrefix^) + LEN(THIS^.sMqttSubscribeTopicSuffix) > GVL_MQTT.MQTT_TOPIC_LEN THEN
		THIS^.bTopicTruncated := TRUE;
	END_IF
END_IF

bInitMqttDone := TRUE;

(* Copy the slot out before releasing it: advancing iPr is what tells a producer the
   slot may be overwritten, so it has to be the last thing that happens. *)
IF THIS^.HasMessage() THEN
	GetMessage := astFifo[iPr];
	iPr := OSCAT_BASIC.INC1(iPr,ciN);
END_IF;

(* Written straight into the slot: the old code staged every message through a
   single FB member, which four tasks shared as scratch space. iPw is advanced only
   once all four fields are in place, and GetMessage never reads a slot while
   iPr = iPw, so the reader cannot observe a half-written entry.

   NOTE: that reasoning holds against the READER, not against a second WRITER. Two
   tasks in AddMessage at once still read the same iPw and collide. See the block
   comment on the function block. *)
IF NOT THIS^.IsFull() THEN
	astFifo[iPw].Payload := Payload;
	astFifo[iPw].Topic := Topic;
	astFifo[iPw].Qos := Qos;
	astFifo[iPw].MqttRetain := MqttRetain;
	(* Last: advancing iPw is what publishes the slot to the reader. *)
	iPw := OSCAT_BASIC.INC1(iPw,ciN);
ELSE
	DroppedCount := DroppedCount + 1;
END_IF;

//need to call fbPublish here because of FB nums
fbPublish(
	Topic:= ADR(stLocalMqttMessage.Topic), 
	PayloadString:= ADR(stLocalMqttMessage.Payload), 
	PublishAsString:= TRUE, 
	QoSIn:= stLocalMqttMessage.Qos, 
	MRetain:= stLocalMqttMessage.MqttRetain, 
	send:= Send);

IF NOT bInitDone THEN RETURN; END_IF

IF bRequestToSend THEN
	Send := TRUE;
	SendDone := FALSE;
END_IF

fbSendTimeout(IN := Send, PT := T#10S);

IF fbPublish.done THEN
	 SendDone := TRUE;
	 bRequestToSend:=FALSE;
	 Send:=FALSE;
	 fbSendTimeout(IN := FALSE);
ELSIF fbSendTimeout.Q THEN
	(* Give the worker back to the pool rather than losing it for good. A fbPublish
	   that never completes - a broker dropping the connection mid-QoS-2
	   handshake, say - used to strand this instance forever. *)
	 SendErrorCount := SendErrorCount + 1;
	 SendDone := TRUE;
	 bRequestToSend:=FALSE;
	 Send:=FALSE;
	 fbSendTimeout(IN := FALSE);
END_IF

fbPublish.SetMqttInOut(MQTT_IN_OUT := inputMQTT_IN_OUT^);

bInitDone := TRUE;
SendDone := TRUE;

// Returns TRUE if successful, FALSE if the string could not be parsed.
// The result is written back into the string in-place.

F_STRIP_JSON_ROOT := FALSE;

// Find actual string length by scanning for null terminator
diContentLen := 0;
FOR diI := 0 TO UINT_TO_DINT(uiSize) - 1 DO
    IF pJson[diI] = 0 THEN
        diContentLen := diI;
        EXIT;
    END_IF
END_FOR

IF diContentLen < 5 THEN
    RETURN;
END_IF

// Find the first occurrence of ':{' (byte values 58 and 123)
bFoundStart := FALSE;
FOR diI := 0 TO diContentLen - 2 DO
    IF (pJson[diI] = 16#3A) AND (pJson[diI + 1] = 16#7B) THEN
        diStart := diI + 1; // index of the inner '{'
        bFoundStart := TRUE;
        EXIT;
    END_IF
END_FOR

IF NOT bFoundStart THEN
    RETURN;
END_IF

// Find the last '}' (byte value 125) scanning backwards
bFoundEnd := FALSE;
FOR diI := diContentLen - 1 TO 0 BY -1 DO
    IF pJson[diI] = 16#7D THEN
        diEnd := diI;
        bFoundEnd := TRUE;
        EXIT;
    END_IF
END_FOR

IF NOT bFoundEnd THEN
    RETURN;
END_IF

// diEnd is the outer '}', the inner object runs from diStart to diEnd - 1
// Move the inner content to the beginning of the buffer
SysMemMove(pDest := pJson, pSrc := ADR(pJson[diStart]), udiCount := DINT_TO_UDINT(diEnd - diStart));

// Null-terminate
pJson[diEnd - diStart] := 0;

F_STRIP_JSON_ROOT := TRUE;

