IF NOT CommonTypesAndFunctions.StrEquals(str1:= ADR(OscillationCommandTopic), str2:= ADR('')) THEN
	stMqttDiscMsgFan.osc_cmd_t.CharString := OscillationCommandTopic;
	stMqttDiscMsgFan.osc_stat_t.CharString := OscillationStateTopic;
	stMqttDiscMsgFan.pl_osc_on.CharString := 'oscillate_on';
	stMqttDiscMsgFan.pl_osc_off.CharString := 'oscillate_off';
END_IF



THIS^.PublishEntityConfig(
	pStruct := ADR(stMqttDiscMsgFan),
	StructSize := SIZEOF(stMqttDiscMsgFan),
	EntityId := EntityId,
	Id := Id);

IF pBase = 0 THEN
	RETURN;
END_IF

// 	Entity related: Basis
pBase^.name.CharString :=  Name; // friendly name
pBase^.default_entity_id.CharString :=  CONCAT(CONCAT(EntityId, '.'), Id);
pBase^.uniq_id.CharString :=  Id;

// Availabilty related
pBase^.avty[1].topic.CharString := THIS^.availabilityTopic1;
pBase^.avty[2].topic.CharString := THIS^.availabilityTopic2;
pBase^.avty_mode.CharString := 'all';
pBase^.pl_avail.CharString :=   THIS^.availabilityOnline;
pBase^.pl_not_avail.CharString :=  THIS^.availabilityOffline;
pBase^.qos.Integer := 2;

// Device related
pBase^.dev.cu.CharString := THIS^.cu;
pBase^.dev.name.CharString := THIS^.name;
pBase^.dev.hw.CharString := THIS^.hw;
pBase^.dev.ids.CharString := THIS^.ids;
pBase^.dev.sw.CharString := THIS^.sw;
pBase^.dev.mdl.CharString := THIS^.mdl;
pBase^.dev.mf.CharString := THIS^.mf;

// Extra meta-data
IF NOT CommonTypesAndFunctions.StrEquals(str1:= ADR(Meta), str2:= ADR('')) THEN
	pBase^.meta.CharString := Meta;
END_IF

PublishEntityConfig := FALSE;
IF pStruct = 0 OR StructSize = 0 THEN
	RETURN;
END_IF

sMqttTopic := CONCAT(CONCAT(CONCAT(CONCAT(THIS^.MqttDiscoveryPrefix, EntityId),'/'), Id),'/config' );

fbComposeJSON(
	JSONString:= ADR(sMqttJSON),
	JSONStringSize:= SIZEOF(sMqttJSON),
	JSONVars:= pStruct,
	NumberOfVars:= StructSize / SIZEOF(JSONVAR),
	MaxLevel := 3,
	Rootless := TRUE,
);
fbComposeJSON.Execute := TRUE;
fbComposeJSON();

bStripJsonRootOk := F_STRIP_JSON_ROOT(pJson := ADR(sMqttJSON), uiSize := SIZEOF(sMqttJSON));

(* A composed config that does not end in a closing brace is truncated, and
   publishing it is worse than publishing nothing: Home Assistant rejects the
   whole config and the entity silently disappears, while the log cheerfully
   reports the discovery as added.

   Walk to the null terminator rather than asking a string function where the
   end is. This check used to read

       bJsonComplete := RIGHT(sMqttJSON, 1) = '}';

   and RIGHT is declared over STRING(255), so sMqttJSON was silently narrowed to
   its first 255 bytes on the way in and RIGHT returned character 255 instead of
   the last one. Every discovery config here is longer than that, so the guard
   rejected all of them - and this PLC published no discovery config at all
   between that check landing and this fix. The buffer was never the problem:
   1500 bytes with 665 in use. The FUNCTION SIGNATURE was the narrow part, in a
   check whose whole job is detecting values that got cut short. *)
pJsonByte := ADR(sMqttJSON);
diJsonLen := 0;
FOR diI := 0 TO DINT#1499 DO
	IF pJsonByte[diI] = 0 THEN
		diJsonLen := diI;
		EXIT;
	END_IF
END_FOR
bJsonComplete := (diJsonLen > 0) AND (pJsonByte[diJsonLen - 1] = 16#7D);

IF sMqttJSON = '' THEN
	SendLogMessage(str:=CONCAT(CONCAT('ERROR ',Id), ' had empty MqttJSON'), instance := sInstanceName);
ELSIF bStripJsonRootOk = FALSE THEN
	SendLogMessage(str:=CONCAT(CONCAT('ERROR ',Id), ' failed json root strip'), instance := sInstanceName);
ELSIF NOT bJsonComplete THEN
	SendLogMessage(str:=CONCAT(CONCAT('ERROR ',Id), ' composed truncated json'), instance := sInstanceName);
ELSIF NOT (sMqttJSON = '') THEN
	pMqttPublishQueue^.AddMessage(
		Payload:= sMqttJSON,
		Topic := sMqttTopic,
		Qos := MQTT.QoS.ExactlyOnce,
		MqttRetain := TRUE,
	);
	SendLogMessage(str:=CONCAT(CONCAT('Added ',Id), ' as MQTT discovery'), instance := sInstanceName);
	PublishEntityConfig := TRUE;
END_IF

(* A cover with a position slider, published from its own struct.

   Deliberately a second method and a second struct rather than four optional
   parameters on CreateCoverEntity, because Home Assistant will not accept the
   fields as null. It validates set_position_topic and position_topic as strings,
   and a null fails the whole config rather than just the slider:

     Error 'string value is None for dictionary value @ data['set_position_topic']'
     when processing MQTT discovery message topic:
     'homeassistant/cover/..._FB_DO_COVER_001/config'

   which cost a working cover entity for as long as the null was published. A key
   that must not be there cannot be nulled; it has to be absent, and the way this
   project makes a key absent is a struct without it. Same reason
   MQTT_DISCOVERY_BINARY_SENSOR_ENT_CAT exists beside MQTT_DISCOVERY_BINARY_SENSOR
   rather than the category being an optional field. *)
THIS^.FillCommonFields(
	pBase := ADR(stMqttDiscMsgCoverPos),
	EntityId := EntityId,
	Name := name,
	Id := Id,
	Meta := meta);

// Entity related: Specific
stMqttDiscMsgCoverPos.cmd_t.CharString := CommandTopic;
stMqttDiscMsgCoverPos.pl_open.CharString := PayloadOpen;
stMqttDiscMsgCoverPos.pl_cls.CharString := PayloadClose;
stMqttDiscMsgCoverPos.pl_stop.CharString := PayloadStop;
stMqttDiscMsgCoverPos.stat_t.CharString := StateTopic;
stMqttDiscMsgCoverPos.stat_open.CharString := StateOpen;
stMqttDiscMsgCoverPos.stat_opening.CharString := StateOpening;
stMqttDiscMsgCoverPos.stat_clsd.CharString := StateClosed;
stMqttDiscMsgCoverPos.stat_closing.CharString := StateClosing;
stMqttDiscMsgCoverPos.stat_stopped.CharString := StateStopped;
stMqttDiscMsgCoverPos.opt.Boolean := FALSE;
stMqttDiscMsgCoverPos.dev_cla.CharString := Deviceclass;

// Position
stMqttDiscMsgCoverPos.pos_t.CharString := PositionTopic;
stMqttDiscMsgCoverPos.set_pos_t.CharString := SetPositionTopic;
stMqttDiscMsgCoverPos.pos_open.Integer := PositionOpen;
stMqttDiscMsgCoverPos.pos_clsd.Integer := PositionClosed;

THIS^.PublishEntityConfig(
	pStruct := ADR(stMqttDiscMsgCoverPos),
	StructSize := SIZEOF(stMqttDiscMsgCoverPos),
	EntityId := EntityId,
	Id := Id);

dwVar := SHL(WORD_TO_DWORD(wHi),16) OR WORD_TO_DWORD(wLo);
prReal := ADR(dwVar);
F_SWAP_WORDS_TO_REAL := prReal^;

(* Nothing works until Init has supplied a transport. Failing quietly here is
   better than dereferencing a null interface on a running controller. *)
IF NOT bInitialised THEN
	RETURN;
END_IF

(* The transport is serviced every cycle, not only while a step is in flight -
   it is what opens and re-opens the serial port, and it needs cycles to do that
   before anyone asks it to carry anything. *)
eStepState := Transport.Service();

fbStartupTimer(IN := TRUE, PT := StartupDelay);
fbSilence(IN := bSilenceRun AND NOT bRestartSilence, PT := SilenceTime);
fbWatchdog(IN := (iState = 1 OR iState = 2) AND NOT bRestartWatchdog, PT := StepTimeout);
bRestartSilence	:= FALSE;
bRestartWatchdog	:= FALSE;

CASE iState OF

0:	(* ---------------------------------------------------------------- idle *)
	BusOcupied := NOT fbStartupTimer.Q;

	IF fbStartupTimer.Q AND iDevicesCount > 0 THEN
		iChosen := THIS^.SelectNext();
		IF iChosen >= 0 THEN
			ActiveDevice	:= iChosen;
			Cursor			:= (iChosen + 1) MOD iDevicesCount;
			BusOcupied		:= TRUE;

			(* One call, all of this device's work. *)
			iStepCount := aitfDevices[iChosen].BuildTransaction(pSteps := ADR(eSteps));
			IF iStepCount < 0 THEN
				iStepCount := 0;
			ELSIF iStepCount > (DINT_TO_INT(UPPER_BOUND(eSteps, 1)) + 1) THEN
				iStepCount := DINT_TO_INT(UPPER_BOUND(eSteps, 1)) + 1;
			END_IF

			StepIndex	:= 0;
			StepsRun	:= 0;
			Failures	:= 0;

			IF iStepCount = 0 THEN
				(* Withdrew after asking. Release rather than hold the bus. *)
				iState := 4;
			ELSE
				bRestartWatchdog := TRUE;
				iState := 1;
			END_IF
		END_IF
	END_IF

1:	(* ------------------------------------------------- hand the step over *)
	BusOcupied := TRUE;
	IF Transport.Start(pStep := ADR(eSteps[StepIndex])) THEN
		iState := 2;
	ELSIF fbWatchdog.Q THEN
		(* Refused for as long as the fbWatchdog allows: the port is down, or the
		   function code is one this transport will not frame. Either way the
		   step is over - retrying forever would wedge the whole bus. *)
		Watchdogs := Watchdogs + 1;
		THIS^.FinishStep(Failed := TRUE, pData := 0, Count := 0);
	END_IF

2:	(* ------------------------------------------------------ wait it out *)
	BusOcupied := TRUE;
	IF eStepState = E_RS485_STEP_STATE.OK THEN
		THIS^.FinishStep(Failed := FALSE,
		                 pData := Transport.ReadBuffer(),
		                 Count := Transport.Registers());
	ELSIF eStepState = E_RS485_STEP_STATE.FAILED THEN
		THIS^.FinishStep(Failed := TRUE, pData := Transport.ReadBuffer(), Count := 0);
	ELSIF fbWatchdog.Q THEN
		Watchdogs := Watchdogs + 1;
		THIS^.FinishStep(Failed := TRUE, pData := 0, Count := 0);
	END_IF

3:	(* ------------------------ fbSilence between two eSteps of one transaction *)
	(* The bus is NOT released here. This gap is the inter-frame fbSilence RTU
	   needs; letting another device in would break the guarantee that makes a
	   read-after-write worth doing. *)
	BusOcupied := TRUE;
	IF fbSilence.Q THEN
		bSilenceRun		:= FALSE;
		bRestartWatchdog	:= TRUE;
		iState			:= 1;
	END_IF

4:	(* ------------------------------------------------------------- release *)
	BusOcupied := TRUE;
	aitfDevices[ActiveDevice].OnTransactionDone(StepsRun := StepsRun, Failures := Failures);
	Transactions	:= Transactions + 1;
	ActiveDevice	:= -1;
	bSilenceRun		:= TRUE;
	bRestartSilence	:= TRUE;
	iState			:= 5;

5:	(* --------------------------------- fbSilence before anyone else may start *)
	BusOcupied := TRUE;
	IF fbSilence.Q THEN
		bSilenceRun	:= FALSE;
		iState		:= 0;
	END_IF

END_CASE

(* One step is over, for whatever reason. Report it, then decide whether the
   transaction continues. *)

aitfDevices[ActiveDevice].OnStepResult(StepIndex := StepIndex,
                                   Failed := Failed,
                                   pData := pData,
                                   Count := Count);

StepsRun		:= StepsRun + 1;
StepsExecuted	:= StepsExecuted + 1;

IF Failed THEN
	Failures		:= Failures + 1;
	StepFailures	:= StepFailures + 1;
END_IF

IF Failed AND eSteps[StepIndex].AbortOnError THEN
	(* The step that everything after it depended on. Skipping the rest is the
	   point: a read-back published after a failed write would report a value
	   the device never took. *)
	iState := 4;

ELSE
	StepIndex := StepIndex + 1;
	IF StepIndex >= iStepCount THEN
		iState := 4;
	ELSE
		bSilenceRun		:= TRUE;
		bRestartSilence	:= TRUE;
		iState			:= 3;
	END_IF
END_IF

(* Registration order no longer decides who is served first - that is the point
   of the cursor - so aitfDevices can be registered in whatever order reads best at
   the call site. *)
IF iDevicesCount <= DINT_TO_INT(UPPER_BOUND(aitfDevices, 1)) THEN
	aitfDevices[iDevicesCount]	:= device;
	iDevicesCount			:= iDevicesCount + 1;
	RegisterDevice			:= TRUE;
ELSE
	RegisterDevice := FALSE;
END_IF

THIS^.Transport := Transport;

(* Zero means "keep the default", so a call site can supply only what it cares
   about and the block still starts with sane timings. *)
IF StartupDelay > T#0S THEN
	THIS^.StartupDelay := StartupDelay;
END_IF
IF SilenceTime > T#0S THEN
	THIS^.SilenceTime := SilenceTime;
END_IF
IF StepTimeout > T#0S THEN
	THIS^.StepTimeout := StepTimeout;
END_IF

bInitialised := TRUE;

IF Index >= 0 AND Index < iDevicesCount THEN
	GetDevice := aitfDevices[Index];
END_IF

(* Nothing configured, nothing to hold the bus off for. A commissioner that was
   never Init'ed must not stop a bus from working - the failure mode of the
   alternative is a silent bus with no error to show for it. *)
IF NOT bInitialised THEN
	Done := TRUE;
	RETURN;
END_IF

CASE iState OF

0:	IF NOT Enabled OR pController = 0 THEN
		iState := 90;
	ELSE
		iDeviceIdx := 0;
		iState := 1;
	END_IF

1:	(* Ask the next registered device. This is the whole of what makes the sequence
	   device-agnostic: what to probe, what to write and which rates are worth
	   trying all come back from the device itself. *)
	IF iDeviceIdx >= pController^.DeviceCount() THEN
		iState := 90;
	ELSE
		device := pController^.GetDevice(Index := iDeviceIdx);
		Asked := Asked + 1;
		IF device.GetCommissioning(BusBaudrate := BusBaudrate, pRequest := ADR(stRequest)) THEN
			Requested		:= Requested + 1;
			iBaudIdx			:= 0;
			iStopIdx			:= 0;
			udiFoundBaud		:= 0;
			byFoundStop		:= 0;
			udiMaxRx			:= 0;
			udiMaxRxBaud		:= 0;
			byMaxRxStop		:= 0;
			udiDeviceProbes	:= 0;
			bDeviceWritten	:= FALSE;
			iState			:= 2;
		ELSE
			iState := 80;
		END_IF
	END_IF

2:	(* Bring the bus to the setting under test. Short timeouts: a probe that is
	   going to fail should fail quickly, because most of them will. *)
	IF Transport.Retune(
			Baudrate		:= stRequest.Bauds[iBaudIdx],
			StopBitsRaw		:= stRequest.StopBits[iStopIdx],
			ReplyTimeout	:= T#200MS,
			GapTime			:= T#20MS) THEN
		fbDelay(IN := FALSE);
		iState := 3;
	ELSE
		(* A transport that cannot be re-tuned cannot be swept. Give up rather than
		   probe at a setting only believed to be applied. *)
		iState := 70;
	END_IF

3:	(* Let Service actually re-open the port before anything is sent into it. *)
	fbDelay(IN := TRUE, PT := T#200MS);
	Transport.Service();
	IF fbDelay.Q THEN
		fbDelay(IN := FALSE);
		iState := 4;
	END_IF

4:	(* Probe. The point is not what comes back - it is that something did. *)
	stStep.DeviceId		:= stRequest.DeviceId;
	stStep.FunctionCode	:= stRequest.ProbeFunction;
	stStep.Address		:= stRequest.ProbeAddress;
	stStep.Quantity		:= stRequest.ProbeQuantity;
	stStep.AbortOnError	:= FALSE;

	fbDelay(IN := TRUE, PT := T#2S);
	IF Transport.Start(pStep := ADR(stStep)) THEN
		fbDelay(IN := FALSE);
		udiDeviceProbes	:= udiDeviceProbes + 1;
		Probes			:= Probes + 1;
		iState			:= 5;
	ELSIF fbDelay.Q THEN
		(* Port never opened at this setting. A miss, not a fault. *)
		fbDelay(IN := FALSE);
		iState := 6;
	END_IF

5:	eOutcome := Transport.Service();
	IF eOutcome <> E_RS485_STEP_STATE.BUSY THEN
		(* Bytes arriving at all is the useful signal when none of them frame: it
		   separates a device that is present and mis-configured from a bus with
		   nothing on it, which is the difference between sweeping on and going to
		   look at the wiring. *)
		IF Transport.LastRxCount() > udiMaxRx THEN
			udiMaxRx		:= Transport.LastRxCount();
			udiMaxRxBaud	:= stRequest.Bauds[iBaudIdx];
			byMaxRxStop	:= stRequest.StopBits[iStopIdx];
		END_IF
		IF eOutcome = E_RS485_STEP_STATE.OK THEN
			udiFoundBaud	:= stRequest.Bauds[iBaudIdx];
			byFoundStop	:= stRequest.StopBits[iStopIdx];
			iState		:= 7;
		ELSE
			iState := 6;
		END_IF
	END_IF

6:	(* Next rate; when the rates run out, the next framing; when both run out, this
	   device cannot be reached at any setting it named. *)
	IF iBaudIdx < stRequest.BaudCount - 1 THEN
		iBaudIdx	:= iBaudIdx + 1;
		iState	:= 2;
	ELSIF iStopIdx < stRequest.StopCount - 1 THEN
		iBaudIdx		:= 0;
		iStopIdx		:= iStopIdx + 1;
		iState		:= 2;
	ELSE
		iState := 70;
	END_IF

7:	(* Found it. Already where it belongs? Then there is nothing to write, which is
	   the normal eOutcome on every boot after the first. *)
	IF udiFoundBaud = BusBaudrate THEN
		iState := 70;
	ELSE
		iState := 8;
	END_IF

8:	(* Write the value the device asked for into the register it named. Nothing here
	   knows what that value means. *)
	stStep.DeviceId		:= stRequest.DeviceId;
	stStep.FunctionCode	:= stRequest.WriteFunction;
	stStep.Address		:= stRequest.WriteAddress;
	stStep.Quantity		:= 1;
	stStep.Data[0]		:= stRequest.WriteValue;
	stStep.AbortOnError	:= FALSE;

	fbDelay(IN := TRUE, PT := T#2S);
	IF Transport.Start(pStep := ADR(stStep)) THEN
		fbDelay(IN := FALSE);
		bDeviceWritten	:= TRUE;
		Written			:= Written + 1;
		iState			:= 9;
	ELSIF fbDelay.Q THEN
		fbDelay(IN := FALSE);
		iState := 70;
	END_IF

9:	(* The acknowledgement comes back at the NEW setting and this end will not hear
	   it, so the eOutcome is deliberately ignored: a failure here is the expected
	   result of success, and nothing may retry on it. *)
	IF Transport.Service() <> E_RS485_STEP_STATE.BUSY THEN
		iState := 70;
	END_IF

70:	(* Put the bus back the way the program configured it, whatever happened. *)
	Transport.RestoreTuning();
	fbDelay(IN := FALSE);
	iState := 71;

71:	fbDelay(IN := TRUE, PT := T#500MS);
	Transport.Service();
	IF fbDelay.Q THEN
		fbDelay(IN := FALSE);
		iState := 72;
	END_IF

72:	(* Publish the eOutcome, retained, so it can be read off the broker at any time.
	   The alternative is an online debug session, and on this hardware that is the
	   least reliable thing in the chain - the runtime drops the session long before
	   it drops MQTT. A commissioning result nobody can read is not a result.

	   Built up a piece at a time rather than nested: CONCAT takes exactly two
	   arguments, and a seven-deep nest of it is unreadable even when correct. *)
	sReport := CONCAT('probes=', UDINT_TO_STRING(udiDeviceProbes));
	sReport := CONCAT(sReport, ' found=');
	sReport := CONCAT(sReport, UDINT_TO_STRING(udiFoundBaud));
	sReport := CONCAT(sReport, '/');
	sReport := CONCAT(sReport, BYTE_TO_STRING(byFoundStop));
	sReport := CONCAT(sReport, ' maxrx=');
	sReport := CONCAT(sReport, UDINT_TO_STRING(udiMaxRx));
	sReport := CONCAT(sReport, ' at=');
	sReport := CONCAT(sReport, UDINT_TO_STRING(udiMaxRxBaud));
	sReport := CONCAT(sReport, '/');
	sReport := CONCAT(sReport, BYTE_TO_STRING(byMaxRxStop));
	sReport := CONCAT(sReport, ' written=');
	sReport := CONCAT(sReport, BOOL_TO_STRING(bDeviceWritten));
	LastReport := sReport;

	IF pQueue <> 0 AND psTopicPrefix <> 0 AND stRequest.ReportTopic <> '' THEN
		pQueue^.AddMessage(
			Payload := sReport,
			Topic := CONCAT(psTopicPrefix^, stRequest.ReportTopic),
			Qos := MQTT.QoS.ExactlyOnce,
			MqttRetain := TRUE);
	END_IF

	iState := 80;

80:	iDeviceIdx	:= iDeviceIdx + 1;
	iState		:= 1;

90:	(* Nothing left to do. The bus is on its own settings and the scheduler can
	   have it. *)
	Done := TRUE;

END_CASE

THIS^.Transport		:= Transport;
THIS^.pController	:= pController;
THIS^.BusBaudrate	:= BusBaudrate;
THIS^.pQueue		:= pMqttPublishQueue;
THIS^.psTopicPrefix	:= MqttPublishPrefix;
THIS^.Enabled		:= Enable;

bInitialised := TRUE;

(* Queues a single-register write for the next time this device is granted the
   bus. HasWork reports COMMAND while one is pending, so it goes ahead of routine
   polling on this and every other device.

   Registers worth knowing, from the DFRobot reference:
     16#04  baud rate    0..9 = 2400, 4800, 9600, 19200, 38400, 57600,
                         115200, 230400, 460800, 921600
     16#1A  slave id     16#00..16#FE
     16#08  measurement interval, 1..1000 ms
     16#36  measurement mode  1 = up to 1.3 m, 2 = up to 3 m, 3 = up to 4 m
     16#00  write 1 to restore factory settings

   Writing the baud rate takes effect immediately, so the sensor answers - if at
   all - at the NEW rate and this end will not hear it. That is expected and is
   why OnTransactionDone does not retry. *)
IF NOT bConfigPending THEN
	stConfigStep.DeviceId		:= stStep.DeviceId;
	stConfigStep.FunctionCode	:= 6;
	stConfigStep.Address		:= Register;
	stConfigStep.Quantity		:= 1;
	stConfigStep.Data[0]		:= Value;
	stConfigStep.AbortOnError	:= FALSE;
	bConfigPending			:= TRUE;
	RequestConfigWrite		:= TRUE;
ELSE
	RequestConfigWrite		:= FALSE;
END_IF

(* One decision per transaction, and one re-arm of the timer.

   The re-arm belongs here rather than in OnStepResult because a stStep skipped by
   an AbortOnError predecessor is never reported, and a sensor that has stopped
   answering must still be retried. OnTransactionDone always runs. *)
fbTimerData.IN := TRUE;

(* A configuration write is finished either way. It is deliberately not retried:
   the write that changes the baud rate cannot be confirmed at the old baud rate,
   so a retry loop here would spin forever on a sensor that had in fact obeyed.
   It also says nothing about availability - a write that cannot be acknowledged
   is not evidence the sensor has gone away. *)
IF bConfigPending THEN
	bConfigPending := FALSE;
	RETURN;
END_IF

IF StepsRun = 0 THEN
	RETURN;
END_IF

(* Two independent verdicts on the same transaction, because they answer
   different questions. iAvailFailures decides whether the sensor is reachable at
   all and needs hysteresis to be worth reading. The quality window records how
   well it is doing and deliberately has none - the whole point is to move while
   availability is still, so that a sensor which is degrading rather than
   disconnected is visible. *)
IF Failures >= StepsRun THEN
	IF iAvailFailures < AvailabilityFailLimit THEN
		iAvailFailures := iAvailFailures + 1;
	END_IF
	abQualityWindow[iQualityIdx] := FALSE;
ELSE
	iAvailFailures := 0;
	abQualityWindow[iQualityIdx] := TRUE;
END_IF

iQualityIdx := (iQualityIdx + 1) MOD (DINT_TO_INT(UPPER_BOUND(abQualityWindow, 1)) + 1);
IF iQualitySeen <= DINT_TO_INT(UPPER_BOUND(abQualityWindow, 1)) THEN
	iQualitySeen := iQualitySeen + 1;
END_IF

(* Only over what has actually been observed, so the figure is honest from the
   first transaction rather than starting at a flattering 100 for sixteen. *)
iQualityOk := 0;
FOR iQualityI := 0 TO iQualitySeen - 1 DO
	IF abQualityWindow[iQualityI] THEN
		iQualityOk := iQualityOk + 1;
	END_IF
END_FOR

IF iQualitySeen > 0 THEN
	SuccessRate := INT_TO_USINT((iQualityOk * 100) / iQualitySeen);
	bIsQualityUpdated := TRUE;
END_IF

(* Published only when the verdict changes, and once at startup so a retained
   value exists before anything has gone wrong. Republishing 'online' every two
   seconds for the life of the PLC tells nobody anything and is most of the
   traffic this block would otherwise generate. *)
IF iAvailFailures >= AvailabilityFailLimit THEN
	IF bAvailOnline OR NOT bAvailKnown THEN
		bAvailOnline := FALSE;
		bAvailKnown := TRUE;
		PubMqttMessage(Suffix := '/availability', Data := 'offline');
	END_IF
ELSIF iAvailFailures = 0 THEN
	IF NOT bAvailOnline OR NOT bAvailKnown THEN
		bAvailOnline := TRUE;
		bAvailKnown := TRUE;
		PubMqttMessage(Suffix := '/availability', Data := 'online');
	END_IF
END_IF

(* A configuration write echoes the request back rather than returning data; the
   transport has already checked that echo, so there is nothing to decode here. *)
IF bConfigPending THEN
	RETURN;
END_IF

THIS^.Error := Failed;

(* Count is what actually came back, not what was asked for, so a short reply
   cannot be read past the end of. *)
IF NOT Failed AND Count >= 2 THEN
	THIS^.OUTPUT_STATE		:= WORD_TO_BYTE(pData^[1] AND 16#00FF);
	THIS^.MeasurementValid	:= (THIS^.OUTPUT_STATE = 0);
	THIS^.bIsStateUpdated	:= TRUE;

	(* Hold the last good distance rather than publishing one the sensor has
	   just told us not to trust. A stale reading is visibly stale next to a
	   state that is not 'valid'; a wrong one is not visible at all. *)
	IF THIS^.MeasurementValid THEN
		THIS^.DISTANCE		:= WORD_TO_UINT(pData^[0]);
		THIS^.DataAvailable	:= TRUE;
		THIS^.bIsDataUpdated	:= TRUE;
	END_IF
END_IF

(* A configuration write goes alone and goes first. It is not batched with the
   read because several of these registers change how the sensor talks - the
   baud rate register is the obvious one - and a read queued behind such a write
   would be sent into a sensor that has already stopped listening at this speed. *)
IF bConfigPending THEN
	pSteps^[0]			:= stConfigStep;
	BuildTransaction	:= 1;
ELSIF fbTimerData.Q THEN
	fbTimerData.IN		:= FALSE;
	pSteps^[0]			:= stStep;
	BuildTransaction	:= 1;
ELSE
	BuildTransaction	:= 0;
END_IF

(* Predicate only - the scheduler calls this on every device every cycle, and
   twice when it is looking for commands first. Nothing here may change state. *)
IF bConfigPending THEN
	HasWork := E_RS485_WORK_LEVEL.COMMAND;
ELSIF fbTimerData.Q THEN
	HasWork := E_RS485_WORK_LEVEL.POLL;
ELSE
	HasWork := E_RS485_WORK_LEVEL.NONE;
END_IF

(* Announces the sensor as a device of its own, then one entity per thing it reports. Distance carries no StateClass: it is a position, not a quantity worth averaging or totalling, and Home Assistant's long-term statistics on it would be meaningless. *) IF bInitMqttDone AND NOT bInitMqttDiscoveryDone THEN
id := SUPER^.ResolveEntityId(overruleId := overruleId);
Device^.initDFRobotDevice( name := DeviceName, id := id, Model := Model, availabilityTopic1 := GVL_MQTT.MqttAvailabilityTopic, availabilityTopic2 := CONCAT(THIS^.sMQTTPublishTopic, '/availability'), availabilityOnline := GVL_MQTT.MqttAvailabilityOnlinePayload, availabilityOffline := GVL_MQTT.MqttAvailabilityOfflinePayload, MqttDiscoveryPrefix := GVL_MQTT.MqttHADiscoveryPrefix, MqttDiagnosticTopic := CONCAT(THIS^.sMQTTPublishTopic, '/diagnostic'), pMqttPublishQueue := ADR(GVL_MQTT.fbMqttPublishQueue));
Device^.CreateSensorEntity( Name := 'Distance', Id := CONCAT(id, '_DIST'), StateTopic := CONCAT(THIS^.sMQTTPublishTopic, '/DIST'), DeviceClass := 'distance', UnitOfMeasurement := 'mm');
(* Diagnostic rather than a headline reading: it is what you look at when the distance stops making sense, not something to put on a dashboard. *) Device^.CreateDiagnosticSensorEntity( Name := 'Measurement state', Id := CONCAT(id, '_STATE'), StateTopic := CONCAT(THIS^.sMQTTPublishTopic, '/STATE'));
(* Diagnostic, with a unit and a state class so Home Assistant will graph it and keep statistics. This is the entity to put an automation on: a sensor that starts answering nine polls in ten instead of ten shows up here while availability is still reporting a cheerful 'online'. *) Device^.CreateDiagnosticSensorEntity( Name := 'Link quality', Id := CONCAT(id, '_QUALITY'), StateTopic := CONCAT(THIS^.sMQTTPublishTopic, '/QUALITY'), StateClass := 'measurement', UnitOfMeasurement := '%');
bInitMqttDiscoveryDone := TRUE; END_IF

SUPER^._sInstancePath := THIS^.sInstancePath; // Due to reflection its location is important

(*pass trough*)
THIS^.pMqttPublishQueue := pMqttPublishQueue;
THIS^.psMqttPublishTopicPrefix := MQTTPublishPrefix;
SUPER^.InitBaseMqtt();

(* Modbus address and poll rate describe the wiring, not a mode, so they are fixed for the life of the instance and belong here rather than in a runtime setter. Note the consequence: changing either afterwards means editing the declaration in the IDE - CODESYS stores an instance's FB_init arguments beside the declaration text, where no script can reach them.
16#34 is the measurement data register and 16#35 the output state; they are adjacent, so reading two registers gets both from one reply and they describe the same measurement rather than two moments a poll apart.
Function 3, not 4: this sensor exposes everything - readings and settings alike - as holding registers. *) THIS^.stStep.DeviceId := DeviceAddress; THIS^.stStep.FunctionCode := 3; THIS^.stStep.Address := 16#34; THIS^.stStep.Quantity := 2;
(* --- the poll rate is a hardware limit, not a preference -------------------- This sensor will not be read every two seconds. Measured on a PFC200 with the sensor alone on the bus, nothing else registered:
poll every 2 s ~19 requests per 30 s, ~4 answered - 25% success poll every 7 s ~4 requests per 30 s, ~4 answered - 100% poll every 10 s 3 requests per 30 s, 3 answered - 100%, zero failures
It answers roughly once every six or seven seconds however often it is asked, and the requests in between are simply dropped. Ask faster and the only thing that changes is the proportion that fail, which is what made the Home Assistant connectivity sensor flap: three consecutive misses is easy to reach at 2 s and impossible at 10 s.
So the interval is clamped rather than trusted. A caller asking for something this device cannot sustain gets a working sensor and a slower one, which is the better failure: the alternative is a reading that is right a quarter of the time and an entity that keeps going unavailable. *) IF DataPollingInterval < ctSen0492MinPoll THEN THIS^.fbTimerData.PT := ctSen0492MinPoll; ELSE THIS^.fbTimerData.PT := DataPollingInterval; END_IF THIS^.fbTimerData.IN := TRUE;
FB_init := TRUE;

IF pRequest = 0 THEN
	GetCommissioning := FALSE;
	RETURN;
END_IF

(* Can this sensor even be told to use the bus rate? The iCode is the index of the
   rate in its own table, so a rate that is not in the table has no iCode, and the
   honest answer is then to withdraw: moving the sensor to a rate it can express
   but the bus does not use would leave it just as inaudible, at a setting nobody
   went looking for. *)
iCode := -1;
FOR iI := 0 TO DINT_TO_INT(UPPER_BOUND(caudiBaudRates, 1)) DO
	IF caudiBaudRates[iI] = BusBaudrate THEN
		iCode := iI;
	END_IF
END_FOR

IF iCode < 0 THEN
	GetCommissioning := FALSE;
	RETURN;
END_IF

(* Where to probe, and what a reply means. Everything on this sensor - readings and
   settings alike - is a holding register, so it is function 3 to read and 6 to
   write. The probe is the same measurement read the block polls with, because the
   point is not the distance: it is that something answered at this setting. *)
pRequest^.DeviceId			:= stStep.DeviceId;
pRequest^.ProbeFunction		:= 3;
pRequest^.ProbeAddress		:= stStep.Address;
pRequest^.ProbeQuantity		:= stStep.Quantity;
pRequest^.WriteFunction		:= 6;
pRequest^.WriteAddress		:= cuiRegBaudrate;
pRequest^.WriteValue		:= INT_TO_WORD(iCode);

(* The bus rate first, so a sensor that has already been moved costs one exchange
   and the sweep ends there - the normal case after the first successful boot. The
   factory rate second, because that is where a fresh or factory-reset sensor is.
   Then the rest, for a sensor somebody has left half-configured. *)
pRequest^.Bauds[0] := BusBaudrate;
iN := 1;
IF cudiFactoryBaud <> BusBaudrate THEN
	pRequest^.Bauds[iN] := cudiFactoryBaud;
	iN := iN + 1;
END_IF
FOR iI := 0 TO DINT_TO_INT(UPPER_BOUND(caudiBaudRates, 1)) DO
	IF caudiBaudRates[iI] <> BusBaudrate AND caudiBaudRates[iI] <> cudiFactoryBaud THEN
		pRequest^.Bauds[iN] := caudiBaudRates[iI];
		iN := iN + 1;
	END_IF
END_FOR
pRequest^.BaudCount := iN;

(* Framing as well as rate, because those are the two things that silence a device
   on a working pair. 255 leaves the port's own framing - the ordinary case, tried
   first - and 1..3 force the raw SysCom iCode, which is how two stop bits is
   reached without depending on an enumerator name this runtime may spell
   differently. The sensor's own forum traffic reports 8N2; this bench found one
   stop bit answering on the first probe, so the sweep keeps both. *)
pRequest^.StopBits[0]	:= 255;
pRequest^.StopBits[1]	:= 1;
pRequest^.StopBits[2]	:= 2;
pRequest^.StopBits[3]	:= 3;
pRequest^.StopCount		:= 4;

(* Where the outcome is published, retained, under the bus prefix. *)
pRequest^.ReportTopic := 'SEN0492_COMMISSION';

GetCommissioning := TRUE;

fbTimerData();

FOR iLoopCounter := 2 TO 30 DO
	afbNodes[iLoopCounter]();
END_FOR

THIS^.fbTimerData.PT := DataPollingInterval;

THIS^.stMasterStep.DeviceId		:= DeviceAddress;
THIS^.stMasterStep.FunctionCode	:= 4;
THIS^.stMasterStep.Address		:= 10;
THIS^.stMasterStep.Quantity		:= 6;

(* Address and value are filled in by PublishReceived when a command arrives. *)
THIS^.stWriteStep.DeviceId		:= DeviceAddress;
THIS^.stWriteStep.FunctionCode	:= 6;
THIS^.stWriteStep.Quantity		:= 1;

THIS^.fbTimerData.IN := TRUE;

THIS^.bInitRS485Done := TRUE;

SUPER^._sInstancePath := THIS^.sInstancePath; // Due to reflection its location is important

(*pass trough*)
THIS^.pMqttPublishQueue := pMqttPublishQueue;
THIS^.psMqttPublishTopicPrefix := MQTTPublishPrefix;
THIS^.psMqttSubscribeTopicPrefix := MQTTSubscribePrefix;
SUPER^.InitBaseMqtt();

// register the FB agains the collector so mqtt events can be received
pMqttCallbackCollector^.put(instance:= THIS^);


FOR iLoopCounter := 2 TO 30 DO
		afbNodes[iLoopCounter].InitMqtt(
			MQTTPublishPrefix := MQTTPublishPrefix,
			MqttPublishTopicSuffix := THIS^.MqttPublishTopicSuffix,
			pMqttPublishQueue := pMqttPublishQueue
		);
END_FOR

//first check if Mqtt is initialized, otherwise do nothing
IF NOT(bInitMqttDone) THEN
	//mark the interface call from the collector as done
	PublishReceived := TRUE;
//check if the packet is for this FB
ELSIF sMQTTSubscribeTopic = LEFT(Data.TopicOut^, LEN(sMQTTSubscribeTopic)) THEN
	//mark the interface call from the collector as done
	PublishReceived := TRUE;
	// process the data
	(* Parse by delimiter rather than by fixed width. The old code took the last
	   nine characters and then one character each for the node and the register,
	   so a command on '.../12/write/3' parsed as node 2 - a write silently aimed
	   at a different physical device. This block supports afbNodes 2..30. *)
	sSubTopic := RIGHT(Data.TopicOut^, LEN(Data.TopicOut^) - LEN(sMQTTSubscribeTopic));
	iWritePos := FIND(sSubTopic, '/write/');

	IF iWritePos >= 3 THEN
		// sSubTopic is '/<node>/write/<register>', so the node digits occupy
		// positions 2..iWritePos-1 and the register is everything past '/write/'.
		NodeNumber := MID(sSubTopic, iWritePos - 2, 2);
		sNodeRegister := RIGHT(sSubTopic, LEN(sSubTopic) - (iWritePos + 6));
	ELSE
		NodeNumber := '';
		sNodeRegister := '';
	END_IF

	IF iWritePos >= 3 AND
		OSCAT_BASIC.IS_NUM(NodeNumber) AND
		OSCAT_BASIC.IS_NUM(sNodeRegister) AND
		OSCAT_BASIC.IS_NUM(Data.PayloadString^) AND
		STRING_TO_UINT(NodeNumber) >= 2 AND
		STRING_TO_UINT(NodeNumber) < THIS^.uiNodePointer THEN
			stWriteStep.Address := (STRING_TO_UINT(NodeNumber) * 10) + STRING_TO_UINT(sNodeRegister);
			stWriteStep.Data[0] := STRING_TO_WORD(Data.PayloadString^);
			sWriteQuerySuffix := sSubTopic;
			sWriteQueryPayload := Data.PayloadString^;
			bWriteQueryReady := TRUE;
	END_IF
END_IF

(* afbNodes is ARRAY[2..30]. Without this bound the 30th call wrote past the end of
   it, and the unassigned return value left the caller unable to notice. *)
IF uiNodePointer <= 30 THEN
	THIS^.afbNodes[uiNodePointer].InitNode(
		DeviceAddress := THIS^.stMasterStep.DeviceId,
		NodeNumber := uiNodePointer - 1,
		DataPollingInterval := DataPollingInterval
	);

	uiNodePointer := uiNodePointer + 1;
	AddNode := TRUE;
ELSE
	AddNode := FALSE;
END_IF

iN := 0;

IF bWriteQueryReady THEN
	bWriteQueryReady := FALSE;

	(* Write, then read the same register straight back, with the bus held
	   across both. What this block used to do was publish the payload it had
	   just sent, as though sending it were proof - so Home Assistant showed a
	   value the Ducobox might never have taken. AbortOnError on the write is
	   what stops the read-back running, and therefore stops anything being
	   published, when the write itself fails. *)
	pSteps^[iN]				:= stWriteStep;
	pSteps^[iN].AbortOnError	:= TRUE;
	aiStepMap[iN]				:= 2;
	iN						:= iN + 1;

	stReadBackStep.DeviceId		:= stWriteStep.DeviceId;
	(* Function 3: the register was written as a holding register, so that is
	   where it reads back from. If a Ducobox turns out to mirror these into the
	   input register space instead, this is the one line that changes. *)
	stReadBackStep.FunctionCode	:= 3;
	stReadBackStep.Address		:= stWriteStep.Address;
	stReadBackStep.Quantity		:= 1;

	pSteps^[iN]	:= stReadBackStep;
	aiStepMap[iN]	:= 3;
	iN			:= iN + 1;
END_IF

IF fbTimerData.Q THEN
	fbTimerData.IN	:= FALSE;
	pSteps^[iN]		:= stMasterStep;
	aiStepMap[iN]		:= 1;
	iN				:= iN + 1;
END_IF

(* One node per transaction, taken in turn from iNodeCursor. *)
FOR iK := 0 TO 28 DO
	iI := 2 + ((iNodeCursor - 2 + iK) MOD 29);
	IF iI < UINT_TO_INT(uiNodePointer) THEN
		IF afbNodes[iI].RequestBusTime() THEN
			pSteps^[iN]	:= afbNodes[iI].GetStep();
			aiStepMap[iN]	:= 10 + iI;
			iN			:= iN + 1;
			iNodeCursor	:= 2 + ((iI - 1) MOD 29);
			EXIT;
		END_IF
	END_IF
END_FOR

BuildTransaction := iN;

(* Pure predicate. afbNodes[].RequestBusTime is one too, so asking them here costs
   nothing and cannot disturb anything - which is the reason the node kept that
   method while the parent's own version was replaced. *)
IF NOT bInitRS485Done THEN
	HasWork := E_RS485_WORK_LEVEL.NONE;
	RETURN;
END_IF

IF bWriteQueryReady THEN
	(* Somebody is waiting on this: it arrived over MQTT, from Home Assistant or
	   a person. Ahead of routine polling, but still round-robin against other
	   devices' commands. *)
	HasWork := E_RS485_WORK_LEVEL.COMMAND;
	RETURN;
END_IF

IF fbTimerData.Q THEN
	HasWork := E_RS485_WORK_LEVEL.POLL;
	RETURN;
END_IF

HasWork := E_RS485_WORK_LEVEL.NONE;
FOR iK := 2 TO 30 DO
	IF iK < UINT_TO_INT(uiNodePointer) THEN
		IF afbNodes[iK].RequestBusTime() THEN
			HasWork := E_RS485_WORK_LEVEL.POLL;
			RETURN;
		END_IF
	END_IF
END_FOR

IF StepIndex < 0 OR StepIndex > DINT_TO_INT(UPPER_BOUND(aiStepMap, 1)) THEN
	RETURN;
END_IF

iStepKind := aiStepMap[StepIndex];

IF iStepKind = 1 THEN
	(* Master unit *)
	THIS^.Error := Failed;
	THIS^.fbTimerData.IN := TRUE;
	IF NOT Failed AND Count >= 6 THEN
		PubMqttMessage(Suffix := '/1/read/0', Data := WORD_TO_STRING(pData^[0]));
		PubMqttMessage(Suffix := '/1/read/1', Data := WORD_TO_STRING(pData^[1]));
		PubMqttMessage(Suffix := '/1/read/2', Data := WORD_TO_STRING(pData^[2]));
		PubMqttMessage(Suffix := '/1/read/3', Data := WORD_TO_STRING(pData^[3]));
		PubMqttMessage(Suffix := '/1/read/4', Data := WORD_TO_STRING(pData^[4]));
		PubMqttMessage(Suffix := '/1/read/5', Data := WORD_TO_STRING(pData^[5]));
	END_IF

ELSIF iStepKind = 2 THEN
	(* The write. Deliberately publishes nothing: the value is only news once
	   the device has been read back and agrees. *)
	THIS^.Error := Failed;

ELSIF iStepKind = 3 THEN
	(* The read-back. This is the value the device actually holds, which is the
	   whole point of pairing the two. *)
	IF NOT Failed AND Count >= 1 THEN
		(* Suffix already begins with '/', so this leading one doubles it. Kept
		   as it was: the topic is what Home Assistant is already subscribed to,
		   and it cannot be re-checked without a Ducobox on the bench. *)
		PubMqttMessage(Suffix := CONCAT('/', sWriteQuerySuffix), Data := WORD_TO_STRING(pData^[0]));
	END_IF

ELSIF iStepKind >= 12 AND iStepKind <= 40 THEN
	afbNodes[iStepKind - 10].OnStepResult(Failed := Failed, pData := pData, Count := Count);
END_IF

(* One announcement per transaction, at the point the bus is released. *)
IF StepsRun > 0 AND Failures >= StepsRun THEN
	PubMqttMessage(Suffix := '/availability', Data := 'offline');
ELSIF StepsRun > 0 THEN
	PubMqttMessage(Suffix := '/availability', Data := 'online');
END_IF

IF NOT bNodeInitialized THEN	
	RequestBusTime := FALSE;
ELSIF fbTimerData.Q THEN
	RequestBusTime := TRUE;
ELSE
	RequestBusTime := FALSE;	
END_IF

THIS^.stStep.DeviceId		:= DeviceAddress;
THIS^.stStep.FunctionCode	:= 4;
THIS^.stStep.Address		:= (NodeNumber * 10) + 10;
THIS^.stStep.Quantity		:= 6;

THIS^.fbTimerData.PT := DataPollingInterval;
THIS^.NodeNumber := NodeNumber + 1;

THIS^.fbTimerData.IN := TRUE;

THIS^.bNodeInitialized := TRUE;

THIS^.psMqttPublishTopicPrefix := MQTTPublishPrefix;
THIS^.MqttPublishTopicSuffix := MqttPublishTopicSuffix;
THIS^.pMqttPublishQueue := pMqttPublishQueue;

THIS^.bInitMqttDone := TRUE;

THIS^.fbTimerData.IN := TRUE;

IF NOT Failed AND Count >= 6 THEN
	PubMqttMessage(Suffix := '/read/0', Data := WORD_TO_STRING(pData^[0]));
	PubMqttMessage(Suffix := '/read/1', Data := WORD_TO_STRING(pData^[1]));
	PubMqttMessage(Suffix := '/read/2', Data := WORD_TO_STRING(pData^[2]));
	PubMqttMessage(Suffix := '/read/3', Data := WORD_TO_STRING(pData^[3]));
	PubMqttMessage(Suffix := '/read/4', Data := WORD_TO_STRING(pData^[4]));
	PubMqttMessage(Suffix := '/read/5', Data := WORD_TO_STRING(pData^[5]));
END_IF

(* Modbus address, meter model and poll rate all describe the wiring rather than
   a mode, so they are fixed for the life of the instance and belong here rather
   than in a runtime setter. Note the consequence: changing any of them
   afterwards means editing the declaration in the IDE - CODESYS stores an
   instance's FB_init arguments beside the declaration text, where no script can
   reach them.

   DeviceType decides which register is read, and it is also the model this block
   announces itself to Home Assistant as. Setting it here means both are settled
   before the first cycle, so the discovery config cannot be published against a
   model that has not been chosen yet. *)
THIS^.stStepSmallMeter.DeviceId		:= DeviceAddress;
THIS^.stStepSmallMeter.FunctionCode	:= 4;
THIS^.stStepSmallMeter.Address		:= 12;	(* SDM120 / SDM220 active power *)
THIS^.stStepSmallMeter.Quantity		:= 2;

THIS^.stStepSDM630.DeviceId		:= DeviceAddress;
THIS^.stStepSDM630.FunctionCode	:= 4;
THIS^.stStepSDM630.Address		:= 52;	(* SDM630 total active power *)
THIS^.stStepSDM630.Quantity		:= 2;

THIS^.DeviceType := DeviceType;

THIS^.fbTimerData.PT := DataPollingInterval;
THIS^.fbTimerData.IN := TRUE;

FB_init := TRUE;

SUPER^._sInstancePath := THIS^.sInstancePath; // Due to reflection its location is important

(*pass trough*)
THIS^.pMqttPublishQueue := pMqttPublishQueue;
THIS^.psMqttPublishTopicPrefix := MQTTPublishPrefix;
SUPER^.InitBaseMqtt();

BuildTransaction := 0;

IF fbTimerData.Q THEN
	fbTimerData.IN := FALSE;

	IF DeviceType = E_RS485_EASTRON_SDM_DEVICE.SDM630 THEN
		pSteps^[0]			:= stStepSDM630;
		BuildTransaction	:= 1;
	ELSIF DeviceType = E_RS485_EASTRON_SDM_DEVICE.SDM120
	   OR DeviceType = E_RS485_EASTRON_SDM_DEVICE.SDM220 THEN
		pSteps^[0]			:= stStepSmallMeter;
		BuildTransaction	:= 1;
	END_IF
	(* An unset DeviceType returns 0: the scheduler releases the bus and moves
	   on rather than sending a frame nobody asked for. *)
END_IF

THIS^.Error := Failed;
THIS^.fbTimerData.IN := TRUE;

IF NOT Failed AND Count >= 2 THEN
	THIS^.ACTIVEPOWER := F_SWAP_WORDS_TO_REAL(pData^[0], pData^[1]);
	THIS^.DataAvailable := TRUE;
	THIS^.bIsDataUpdated := TRUE;
END_IF

(* One announcement per transaction, at the point the bus is released. *)
IF StepsRun > 0 AND Failures >= StepsRun THEN
	PubMqttMessage(Suffix := '/availability', Data := 'offline');
ELSIF StepsRun > 0 THEN
	PubMqttMessage(Suffix := '/availability', Data := 'online');
END_IF

(* Announces the meter as a device carrying one sensor: active power. Unlike the SDM220 and SDM630 blocks this one serves three meter models, so the model string is derived from DeviceType rather than fixed - InitRS485 must therefore have run before this does, which is what the self-wiring prologue waits for. Pass Model explicitly to overrule the derivation. *) IF bInitMqttDone AND NOT bInitMqttDiscoveryDone THEN
IF Model <> '' THEN sResolvedModel := Model; ELSE CASE DeviceType OF E_RS485_EASTRON_SDM_DEVICE.SDM120: sResolvedModel := 'SDM120'; E_RS485_EASTRON_SDM_DEVICE.SDM220: sResolvedModel := 'SDM220'; E_RS485_EASTRON_SDM_DEVICE.SDM630: sResolvedModel := 'SDM630'; ELSE sResolvedModel := 'unknown'; END_CASE END_IF
id := SUPER^.ResolveEntityId(overruleId := overruleId);
Device^.initEastronDevice( name := DeviceName, id := id, Model := sResolvedModel, availabilityTopic1 := GVL_MQTT.MqttAvailabilityTopic, availabilityTopic2 := CONCAT(THIS^.sMQTTPublishTopic, '/availability'), availabilityOnline := GVL_MQTT.MqttAvailabilityOnlinePayload, availabilityOffline := GVL_MQTT.MqttAvailabilityOfflinePayload, MqttDiscoveryPrefix := GVL_MQTT.MqttHADiscoveryPrefix, MqttDiagnosticTopic := CONCAT(THIS^.sMQTTPublishTopic, '/diagnostic'), pMqttPublishQueue := ADR(GVL_MQTT.fbMqttPublishQueue));
Device^.CreateSensorEntity( Name := 'Active Power', Id := CONCAT(id, '_ACTP'), StateTopic := CONCAT(THIS^.sMQTTPublishTopic, '/ACTP'), DeviceClass := 'power', StateClass := 'measurement', UnitOfMeasurement := 'W');
bInitMqttDiscoveryDone := TRUE; END_IF

(* --- self-wiring prologue ----------------------------------------------------
   Makes the InitMqtt and InitMqttDiscovery calls optional. Set FriendlyName at
   the declaration site and this block wires itself from GVL_MQTT on its
   first cyclic call, then announces itself to Home Assistant.

   Deliberately in the body rather than in FB_init: it dereferences GVL members
   and reads the reflection instance path, and doing that during initialisation
   would rely on an ordering nothing enforces and the compiler cannot check.

   Dormant while FriendlyName is empty, so existing projects and existing call
   sites keep working untouched.

   A block wired this way MUST be called cyclically. An instance whose body never
   runs is unwired and absent from Home Assistant, and nothing warns about that. *)
IF FriendlyName <> '' THEN

	IF NOT bInitMqttDone THEN
		THIS^.InitMqtt(
			MQTTPublishPrefix := ADR(GVL_MQTT.MqttPubRS485Prefix),
			pMqttPublishQueue := ADR(GVL_MQTT.fbMqttPublishQueue));
	END_IF

	IF bInitMqttDone AND NOT bInitMqttDiscoveryDone THEN
		THIS^.InitMqttDiscovery(
			Device := ADR(THIS^.fbMqttDiscoveryDevice),
			DeviceName := FriendlyName);
	END_IF

END_IF

fbTimerData();

(* Published through PubMqttMessage rather than by building each topic inline.
   The inline form concatenated the prefix and suffix at every one of these
   fourteen call sites, which is the same string sMQTTPublishTopic already holds -
   and the discovery configs advertise sMQTTPublishTopic. Two ways of spelling one
   topic is how a state topic and its discovery config drift apart. *)
IF bUpdate1 THEN
	bUpdate1 := FALSE;
	DataAvailable1 := TRUE;

	PubMqttMessage(Suffix := '/VOLT', Data := REAL_TO_STRING(VOLTAGE));
	PubMqttMessage(Suffix := '/CURR', Data := REAL_TO_STRING(CURRENT));
	PubMqttMessage(Suffix := '/ACTP', Data := REAL_TO_STRING(ACTIVEPOWER));
	PubMqttMessage(Suffix := '/APPP', Data := REAL_TO_STRING(APPARENT_POWER));
	PubMqttMessage(Suffix := '/REAP', Data := REAL_TO_STRING(REACTIVE_POWER));
	PubMqttMessage(Suffix := '/POWF', Data := REAL_TO_STRING(POWER_FACTOR));
	PubMqttMessage(Suffix := '/PHAA', Data := REAL_TO_STRING(PHASE_ANGLE));
END_IF

IF bUpdate2 THEN
	bUpdate2 := FALSE;
	DataAvailable2 := TRUE;

	PubMqttMessage(Suffix := '/FREQ', Data := REAL_TO_STRING(FREQUENCY));
	PubMqttMessage(Suffix := '/IMAE', Data := REAL_TO_STRING(IMPORT_ACTIVE_ENERGY));
	PubMqttMessage(Suffix := '/EXAE', Data := REAL_TO_STRING(EXPORT_ACTIVE_ENERGY));
	PubMqttMessage(Suffix := '/IMRE', Data := REAL_TO_STRING(IMPORT_REACTIVE_ENERGY));
	PubMqttMessage(Suffix := '/EXRE', Data := REAL_TO_STRING(EXPORT_REACTIVE_ENERGY));
END_IF

IF bUpdate3 THEN
	bUpdate3 := FALSE;
	DataAvailable3 := TRUE;

	PubMqttMessage(Suffix := '/TOTAE', Data := REAL_TO_STRING(TOTAL_ACTIVE_ENERGY));
	PubMqttMessage(Suffix := '/TOTRE', Data := REAL_TO_STRING(TOTAL_REACTIVE_ENERGY));
END_IF

SUPER^._sInstancePath := THIS^.sInstancePath; // Due to reflection its location is important

(*pass trough*)
THIS^.pMqttPublishQueue := pMqttPublishQueue;
THIS^.psMqttPublishTopicPrefix := MQTTPublishPrefix;
SUPER^.InitBaseMqtt();

(* The whole meter in one grant of the bus. Three register blocks used to mean
   winning the bus three separate times, with every other device's traffic in
   between; and while they were separately timed, which of the three were due
   varied from round to round. They now always go together.

   aiStepMap records which block each step came from, because OnStepResult is told
   the step index and nothing else. *)
IF fbTimerData.Q THEN
	fbTimerData.IN := FALSE;

	pSteps^[0] := astSteps[0];		aiStepMap[0] := 1;
	pSteps^[1] := astSteps[1];		aiStepMap[1] := 2;
	pSteps^[2] := astSteps[2];		aiStepMap[2] := 3;

	BuildTransaction := 3;
ELSE
	BuildTransaction := 0;
END_IF

IF StepIndex < 0 OR StepIndex > DINT_TO_INT(UPPER_BOUND(aiStepMap, 1)) THEN
	RETURN;
END_IF

(* Count is what actually came back, not what was asked for, so a short reply
   cannot be read past the end of. The timer is not re-armed here - see
   OnTransactionDone. *)
CASE aiStepMap[StepIndex] OF

1:	THIS^.Error1 := Failed;
	IF NOT Failed AND Count >= 38 THEN
		THIS^.VOLTAGE			:= F_SWAP_WORDS_TO_REAL(pData^[0], pData^[1]);
		THIS^.CURRENT			:= F_SWAP_WORDS_TO_REAL(pData^[6], pData^[7]);
		THIS^.ACTIVEPOWER		:= F_SWAP_WORDS_TO_REAL(pData^[12], pData^[13]);
		THIS^.APPARENT_POWER	:= F_SWAP_WORDS_TO_REAL(pData^[18], pData^[19]);
		THIS^.REACTIVE_POWER	:= F_SWAP_WORDS_TO_REAL(pData^[24], pData^[25]);
		THIS^.POWER_FACTOR		:= F_SWAP_WORDS_TO_REAL(pData^[30], pData^[31]);
		THIS^.PHASE_ANGLE		:= F_SWAP_WORDS_TO_REAL(pData^[36], pData^[37]);
		THIS^.bUpdate1 := TRUE;
	END_IF

2:	THIS^.Error2 := Failed;
	IF NOT Failed AND Count >= 10 THEN
		THIS^.FREQUENCY					:= F_SWAP_WORDS_TO_REAL(pData^[0], pData^[1]);
		THIS^.IMPORT_ACTIVE_ENERGY		:= F_SWAP_WORDS_TO_REAL(pData^[2], pData^[3]);
		THIS^.EXPORT_ACTIVE_ENERGY		:= F_SWAP_WORDS_TO_REAL(pData^[4], pData^[5]);
		THIS^.IMPORT_REACTIVE_ENERGY	:= F_SWAP_WORDS_TO_REAL(pData^[6], pData^[7]);
		THIS^.EXPORT_REACTIVE_ENERGY	:= F_SWAP_WORDS_TO_REAL(pData^[8], pData^[9]);
		THIS^.bUpdate2 := TRUE;
	END_IF

3:	THIS^.Error3 := Failed;
	IF NOT Failed AND Count >= 4 THEN
		THIS^.TOTAL_ACTIVE_ENERGY	:= F_SWAP_WORDS_TO_REAL(pData^[0], pData^[1]);
		THIS^.TOTAL_REACTIVE_ENERGY	:= F_SWAP_WORDS_TO_REAL(pData^[2], pData^[3]);
		THIS^.bUpdate3 := TRUE;
	END_IF

END_CASE

(* One announcement per transaction, and one re-arm of the timer.

   The re-arm belongs here rather than in OnStepResult because a step skipped by
   an AbortOnError predecessor is never reported, and a meter that has stopped
   answering must still be retried. OnTransactionDone always runs. *)
fbTimerData.IN := TRUE;

IF StepsRun > 0 AND Failures >= StepsRun THEN
	PubMqttMessage(Suffix := '/availability', Data := 'offline');
ELSIF StepsRun > 0 THEN
	PubMqttMessage(Suffix := '/availability', Data := 'online');
END_IF

(* Announces the meter as a device of its own, then one sensor entity per measurement. StateClass is what puts the energy totals into the Home Assistant energy dashboard; the instantaneous values are 'measurement', and power factor and phase angle carry none because neither is meaningful to sum or average over time.
The three kvarh counters use DeviceClass 'reactive_energy', which Home Assistant gained in 2025.9. On an older Home Assistant an unrecognised device class makes it reject the whole discovery config, so those three entities would not appear at all - the symptom is a missing entity, not a wrong one. *) IF bInitMqttDone AND NOT bInitMqttDiscoveryDone THEN
id := SUPER^.ResolveEntityId(overruleId := overruleId);
Device^.initEastronDevice( name := DeviceName, id := id, Model := Model, availabilityTopic1 := GVL_MQTT.MqttAvailabilityTopic, availabilityTopic2 := CONCAT(THIS^.sMQTTPublishTopic, '/availability'), availabilityOnline := GVL_MQTT.MqttAvailabilityOnlinePayload, availabilityOffline := GVL_MQTT.MqttAvailabilityOfflinePayload, MqttDiscoveryPrefix := GVL_MQTT.MqttHADiscoveryPrefix, MqttDiagnosticTopic := CONCAT(THIS^.sMQTTPublishTopic, '/diagnostic'), pMqttPublishQueue := ADR(GVL_MQTT.fbMqttPublishQueue));
(* --- register block 1: the instantaneous electrical values ------------- *)
Device^.CreateSensorEntity( Name := 'Voltage', Id := CONCAT(id, '_VOLT'), StateTopic := CONCAT(THIS^.sMQTTPublishTopic, '/VOLT'), DeviceClass := 'voltage', StateClass := 'measurement', UnitOfMeasurement := 'V');
Device^.CreateSensorEntity( Name := 'Current', Id := CONCAT(id, '_CURR'), StateTopic := CONCAT(THIS^.sMQTTPublishTopic, '/CURR'), DeviceClass := 'current', StateClass := 'measurement', UnitOfMeasurement := 'A');
Device^.CreateSensorEntity( Name := 'Active Power', Id := CONCAT(id, '_ACTP'), StateTopic := CONCAT(THIS^.sMQTTPublishTopic, '/ACTP'), DeviceClass := 'power', StateClass := 'measurement', UnitOfMeasurement := 'W');
Device^.CreateSensorEntity( Name := 'Apparent Power', Id := CONCAT(id, '_APPP'), StateTopic := CONCAT(THIS^.sMQTTPublishTopic, '/APPP'), DeviceClass := 'apparent_power', StateClass := 'measurement', UnitOfMeasurement := 'VA');
Device^.CreateSensorEntity( Name := 'Reactive Power', Id := CONCAT(id, '_REAP'), StateTopic := CONCAT(THIS^.sMQTTPublishTopic, '/REAP'), DeviceClass := 'reactive_power', StateClass := 'measurement', UnitOfMeasurement := 'var');
Device^.CreateSensorEntity( Name := 'Power Factor', Id := CONCAT(id, '_POWF'), StateTopic := CONCAT(THIS^.sMQTTPublishTopic, '/POWF'), DeviceClass := 'power_factor', UnitOfMeasurement := '');
Device^.CreateSensorEntity( Name := 'Phase Angle', Id := CONCAT(id, '_PHAA'), StateTopic := CONCAT(THIS^.sMQTTPublishTopic, '/PHAA'), DeviceClass := '', UnitOfMeasurement := '°');
(* --- register block 2: frequency and the four energy counters ---------- *)
Device^.CreateSensorEntity( Name := 'Frequency', Id := CONCAT(id, '_FREQ'), StateTopic := CONCAT(THIS^.sMQTTPublishTopic, '/FREQ'), DeviceClass := 'frequency', StateClass := 'measurement', UnitOfMeasurement := 'Hz');
Device^.CreateSensorEntity( Name := 'Import Active Energy', Id := CONCAT(id, '_IMAE'), StateTopic := CONCAT(THIS^.sMQTTPublishTopic, '/IMAE'), DeviceClass := 'energy', StateClass := 'total_increasing', UnitOfMeasurement := 'kWh');
Device^.CreateSensorEntity( Name := 'Export Active Energy', Id := CONCAT(id, '_EXAE'), StateTopic := CONCAT(THIS^.sMQTTPublishTopic, '/EXAE'), DeviceClass := 'energy', StateClass := 'total_increasing', UnitOfMeasurement := 'kWh');
Device^.CreateSensorEntity( Name := 'Import Reactive Energy', Id := CONCAT(id, '_IMRE'), StateTopic := CONCAT(THIS^.sMQTTPublishTopic, '/IMRE'), DeviceClass := 'reactive_energy', StateClass := 'total_increasing', UnitOfMeasurement := 'kvarh');
Device^.CreateSensorEntity( Name := 'Export Reactive Energy', Id := CONCAT(id, '_EXRE'), StateTopic := CONCAT(THIS^.sMQTTPublishTopic, '/EXRE'), DeviceClass := 'reactive_energy', StateClass := 'total_increasing', UnitOfMeasurement := 'kvarh');
(* --- register block 3: the totals -------------------------------------- *)
Device^.CreateSensorEntity( Name := 'Total Active Energy', Id := CONCAT(id, '_TOTAE'), StateTopic := CONCAT(THIS^.sMQTTPublishTopic, '/TOTAE'), DeviceClass := 'energy', StateClass := 'total_increasing', UnitOfMeasurement := 'kWh');
Device^.CreateSensorEntity( Name := 'Total Reactive Energy', Id := CONCAT(id, '_TOTRE'), StateTopic := CONCAT(THIS^.sMQTTPublishTopic, '/TOTRE'), DeviceClass := 'reactive_energy', StateClass := 'total_increasing', UnitOfMeasurement := 'kvarh');
bInitMqttDiscoveryDone := TRUE; END_IF

(* Modbus address and poll rate describe the wiring, not a mode, so they are
   fixed for the life of the instance and belong here rather than in a runtime
   setter. Note the consequence: changing either afterwards means editing the
   declaration in the IDE - CODESYS stores an instance's FB_init arguments beside
   the declaration text, where no script can reach them.

   ONE interval covers the whole meter. The SDM220 will not return more than 40
   registers in a reply and its measurements are not in one contiguous run, so
   reading it takes three requests - but that is a property of the meter, not a
   decision a caller should be asked to make. All three go out together as a
   single transaction, so they cost one turn of the bus rather than three. *)
THIS^.astSteps[0].DeviceId		:= DeviceAddress;
THIS^.astSteps[0].FunctionCode	:= 4;
THIS^.astSteps[0].Address		:= 0;	(* voltage through phase angle *)
THIS^.astSteps[0].Quantity		:= 40;

THIS^.astSteps[1].DeviceId		:= DeviceAddress;
THIS^.astSteps[1].FunctionCode	:= 4;
THIS^.astSteps[1].Address		:= 70;	(* frequency, import and export energy *)
THIS^.astSteps[1].Quantity		:= 10;

THIS^.astSteps[2].DeviceId		:= DeviceAddress;
THIS^.astSteps[2].FunctionCode	:= 4;
THIS^.astSteps[2].Address		:= 342;	(* totals *)
THIS^.astSteps[2].Quantity		:= 4;

THIS^.fbTimerData.PT := DataPollingInterval;
THIS^.fbTimerData.IN := TRUE;

FB_init := TRUE;

(* --- self-wiring prologue ----------------------------------------------------
   Makes the InitMqtt and InitMqttDiscovery calls optional. Set FriendlyName at
   the declaration site and this block wires itself from GVL_MQTT on its
   first cyclic call, then announces itself to Home Assistant.

   Deliberately in the body rather than in FB_init: it dereferences GVL members
   and reads the reflection instance path, and doing that during initialisation
   would rely on an ordering nothing enforces and the compiler cannot check. The
   body is the same lifecycle phase the init actions used, so this is not merely
   safe, it is the phase that already works today.

   The wiring calls this block's own unmodified InitMqtt / InitMqttDiscovery
   methods, so anything published - topics and discovery JSON alike - is produced
   by exactly the code that produces it today. Only the trigger moved.

   Dormant while FriendlyName is empty, so existing projects and existing call
   sites keep working untouched.

   A block wired this way MUST be called cyclically. An instance whose body never
   runs is now unwired and absent from Home Assistant, where the init action used
   to wire it regardless. Nothing warns about that.  *)
IF FriendlyName <> '' THEN

	IF NOT bInitMqttDone THEN
		THIS^.InitMqtt(
			MQTTPublishPrefix := ADR(GVL_MQTT.MqttPubRS485Prefix),
			pMqttPublishQueue := ADR(GVL_MQTT.fbMqttPublishQueue));
	END_IF

	IF bInitMqttDone AND NOT bInitMqttDiscoveryDone THEN
		THIS^.InitMqttDiscovery(
			Device := ADR(THIS^.fbMqttDiscoveryDevice),
			DeviceName := FriendlyName);
	END_IF

END_IF

fbTimerData();

(* Publish on change of data rather than on a timer: ProcessDataArray sets the
   flag when a response arrives, so the publish rate follows DataPollingInterval
   and nothing is republished while the bus is quiet. PubMqttMessage is a no-op
   until InitMqtt has run, so this needs no further guard. *)
IF bIsDataUpdated THEN
	bIsDataUpdated := FALSE;

	PubMqttMessage(Suffix := '/L1_ACTP', Data := REAL_TO_STRING(L1_ACTIVEPOWER));
	PubMqttMessage(Suffix := '/L2_ACTP', Data := REAL_TO_STRING(L2_ACTIVEPOWER));
	PubMqttMessage(Suffix := '/L3_ACTP', Data := REAL_TO_STRING(L3_ACTIVEPOWER));
	PubMqttMessage(Suffix := '/L1_VA', Data := REAL_TO_STRING(L1_VA));
	PubMqttMessage(Suffix := '/L2_VA', Data := REAL_TO_STRING(L2_VA));
	PubMqttMessage(Suffix := '/L3_VA', Data := REAL_TO_STRING(L3_VA));
	PubMqttMessage(Suffix := '/L1_VAR', Data := REAL_TO_STRING(L1_VAR));
	PubMqttMessage(Suffix := '/L2_VAR', Data := REAL_TO_STRING(L2_VAR));
	PubMqttMessage(Suffix := '/L3_VAR', Data := REAL_TO_STRING(L3_VAR));
	PubMqttMessage(Suffix := '/L1_PF', Data := REAL_TO_STRING(L1_PF));
	PubMqttMessage(Suffix := '/L2_PF', Data := REAL_TO_STRING(L2_PF));
	PubMqttMessage(Suffix := '/L3_PF', Data := REAL_TO_STRING(L3_PF));
	PubMqttMessage(Suffix := '/L1_PHI', Data := REAL_TO_STRING(L1_PHI));
	PubMqttMessage(Suffix := '/L2_PHI', Data := REAL_TO_STRING(L2_PHI));
	PubMqttMessage(Suffix := '/L3_PHI', Data := REAL_TO_STRING(L3_PHI));
	PubMqttMessage(Suffix := '/AVG_V', Data := REAL_TO_STRING(AVG_LN_V));
	PubMqttMessage(Suffix := '/AVG_I', Data := REAL_TO_STRING(AVG_LINE_I));
	PubMqttMessage(Suffix := '/SUM_I', Data := REAL_TO_STRING(SUM_LINE_I));
	PubMqttMessage(Suffix := '/ACTP', Data := REAL_TO_STRING(ACTIVEPOWER));
	PubMqttMessage(Suffix := '/TOT_VA', Data := REAL_TO_STRING(TOTAL_VA));
	PubMqttMessage(Suffix := '/TOT_VAR', Data := REAL_TO_STRING(TOTAL_VAR));
	PubMqttMessage(Suffix := '/TOT_PF', Data := REAL_TO_STRING(TOTAL_PF));
	PubMqttMessage(Suffix := '/TOT_PHI', Data := REAL_TO_STRING(TOTAL_PHI));
	PubMqttMessage(Suffix := '/FREQ', Data := REAL_TO_STRING(FREQUENCY));
	PubMqttMessage(Suffix := '/IMPE', Data := REAL_TO_STRING(TOTAL_IMPORT_ENERGY));
	PubMqttMessage(Suffix := '/EXPE', Data := REAL_TO_STRING(TOTAL_EXPORT_ENERGY));
END_IF

IF fbTimerData.Q THEN
	HasWork := E_RS485_WORK_LEVEL.POLL;
ELSE
	HasWork := E_RS485_WORK_LEVEL.NONE;
END_IF

THIS^.Error := Failed; THIS^.fbTimerData.IN := TRUE;
IF NOT Failed AND Count >= 64 THEN (* Every value is a big-endian IEEE float across two consecutive words, so the word index is the register offset from 16#000C doubled. Gaps below are registers the SDM630 reserves. *) THIS^.L1_ACTIVEPOWER := F_SWAP_WORDS_TO_REAL(pData^[0], pData^[1]); // 16#000C L1 Active Power THIS^.L2_ACTIVEPOWER := F_SWAP_WORDS_TO_REAL(pData^[2], pData^[3]); // 16#000E L2 Active Power THIS^.L3_ACTIVEPOWER := F_SWAP_WORDS_TO_REAL(pData^[4], pData^[5]); // 16#0010 L3 Active Power THIS^.L1_VA := F_SWAP_WORDS_TO_REAL(pData^[6], pData^[7]); // 16#0012 L1 Apparent Power THIS^.L2_VA := F_SWAP_WORDS_TO_REAL(pData^[8], pData^[9]); // 16#0014 L2 Apparent Power THIS^.L3_VA := F_SWAP_WORDS_TO_REAL(pData^[10], pData^[11]); // 16#0016 L3 Apparent Power THIS^.L1_VAR := F_SWAP_WORDS_TO_REAL(pData^[12], pData^[13]); // 16#0018 L1 Reactive Power THIS^.L2_VAR := F_SWAP_WORDS_TO_REAL(pData^[14], pData^[15]); // 16#001A L2 Reactive Power THIS^.L3_VAR := F_SWAP_WORDS_TO_REAL(pData^[16], pData^[17]); // 16#001C L3 Reactive Power THIS^.L1_PF := F_SWAP_WORDS_TO_REAL(pData^[18], pData^[19]); // 16#001E L1 Power Factor THIS^.L2_PF := F_SWAP_WORDS_TO_REAL(pData^[20], pData^[21]); // 16#0020 L2 Power Factor THIS^.L3_PF := F_SWAP_WORDS_TO_REAL(pData^[22], pData^[23]); // 16#0022 L3 Power Factor THIS^.L1_PHI := F_SWAP_WORDS_TO_REAL(pData^[24], pData^[25]); // 16#0024 L1 Phase Angle THIS^.L2_PHI := F_SWAP_WORDS_TO_REAL(pData^[26], pData^[27]); // 16#0026 L2 Phase Angle THIS^.L3_PHI := F_SWAP_WORDS_TO_REAL(pData^[28], pData^[29]); // 16#0028 L3 Phase Angle THIS^.AVG_LN_V := F_SWAP_WORDS_TO_REAL(pData^[30], pData^[31]); // 16#002A Average L-iN Voltage THIS^.AVG_LINE_I := F_SWAP_WORDS_TO_REAL(pData^[32], pData^[33]); // 16#002C Average Line Current THIS^.SUM_LINE_I := F_SWAP_WORDS_TO_REAL(pData^[34], pData^[35]); // 16#002E Sum of Line Currents THIS^.ACTIVEPOWER := F_SWAP_WORDS_TO_REAL(pData^[40], pData^[41]); // 16#0034 Active Power THIS^.TOTAL_VA := F_SWAP_WORDS_TO_REAL(pData^[44], pData^[45]); // 16#0038 Total Apparent Power THIS^.TOTAL_VAR := F_SWAP_WORDS_TO_REAL(pData^[48], pData^[49]); // 16#003C Total Reactive Power THIS^.TOTAL_PF := F_SWAP_WORDS_TO_REAL(pData^[50], pData^[51]); // 16#003E Total Power Factor THIS^.TOTAL_PHI := F_SWAP_WORDS_TO_REAL(pData^[54], pData^[55]); // 16#0042 Total Phase Angle THIS^.FREQUENCY := F_SWAP_WORDS_TO_REAL(pData^[58], pData^[59]); // 16#0046 Frequency THIS^.TOTAL_IMPORT_ENERGY := F_SWAP_WORDS_TO_REAL(pData^[60], pData^[61]); // 16#0048 Total Import Energy THIS^.TOTAL_EXPORT_ENERGY := F_SWAP_WORDS_TO_REAL(pData^[62], pData^[63]); // 16#004A Total Export Energy
THIS^.DataAvailable := TRUE; THIS^.bIsDataUpdated := TRUE; END_IF

IF fbTimerData.Q THEN
	pSteps^[0]			:= stStep;
	fbTimerData.IN		:= FALSE;
	BuildTransaction	:= 1;
ELSE
	BuildTransaction := 0;
END_IF

(* Announces the meter as a device of its own, then one sensor entity per measurement. StateClass is what puts the two kWh totals into the Home Assistant energy dashboard; the instantaneous values are 'measurement' and power factor, phase angle, voltage, current and frequency carry none. *) IF bInitMqttDone AND NOT bInitMqttDiscoveryDone THEN
id := SUPER^.ResolveEntityId(overruleId := overruleId);
Device^.initEastronDevice( name := DeviceName, id := id, Model := Model, availabilityTopic1 := GVL_MQTT.MqttAvailabilityTopic, availabilityTopic2 := CONCAT(THIS^.sMQTTPublishTopic, '/availability'), availabilityOnline := GVL_MQTT.MqttAvailabilityOnlinePayload, availabilityOffline := GVL_MQTT.MqttAvailabilityOfflinePayload, MqttDiscoveryPrefix := GVL_MQTT.MqttHADiscoveryPrefix, MqttDiagnosticTopic := CONCAT(THIS^.sMQTTPublishTopic, '/diagnostic'), pMqttPublishQueue := ADR(GVL_MQTT.fbMqttPublishQueue));
Device^.CreateSensorEntity( Name := 'L1 Active Power', Id := CONCAT(id, '_L1_ACTP'), StateTopic := CONCAT(THIS^.sMQTTPublishTopic, '/L1_ACTP'), DeviceClass := 'power', StateClass := 'measurement', UnitOfMeasurement := 'W');
Device^.CreateSensorEntity( Name := 'L2 Active Power', Id := CONCAT(id, '_L2_ACTP'), StateTopic := CONCAT(THIS^.sMQTTPublishTopic, '/L2_ACTP'), DeviceClass := 'power', StateClass := 'measurement', UnitOfMeasurement := 'W');
Device^.CreateSensorEntity( Name := 'L3 Active Power', Id := CONCAT(id, '_L3_ACTP'), StateTopic := CONCAT(THIS^.sMQTTPublishTopic, '/L3_ACTP'), DeviceClass := 'power', StateClass := 'measurement', UnitOfMeasurement := 'W');
Device^.CreateSensorEntity( Name := 'L1 Apparent Power', Id := CONCAT(id, '_L1_VA'), StateTopic := CONCAT(THIS^.sMQTTPublishTopic, '/L1_VA'), DeviceClass := 'apparent_power', StateClass := 'measurement', UnitOfMeasurement := 'VA');
Device^.CreateSensorEntity( Name := 'L2 Apparent Power', Id := CONCAT(id, '_L2_VA'), StateTopic := CONCAT(THIS^.sMQTTPublishTopic, '/L2_VA'), DeviceClass := 'apparent_power', StateClass := 'measurement', UnitOfMeasurement := 'VA');
Device^.CreateSensorEntity( Name := 'L3 Apparent Power', Id := CONCAT(id, '_L3_VA'), StateTopic := CONCAT(THIS^.sMQTTPublishTopic, '/L3_VA'), DeviceClass := 'apparent_power', StateClass := 'measurement', UnitOfMeasurement := 'VA');
Device^.CreateSensorEntity( Name := 'L1 Reactive Power', Id := CONCAT(id, '_L1_VAR'), StateTopic := CONCAT(THIS^.sMQTTPublishTopic, '/L1_VAR'), DeviceClass := 'reactive_power', StateClass := 'measurement', UnitOfMeasurement := 'var');
Device^.CreateSensorEntity( Name := 'L2 Reactive Power', Id := CONCAT(id, '_L2_VAR'), StateTopic := CONCAT(THIS^.sMQTTPublishTopic, '/L2_VAR'), DeviceClass := 'reactive_power', StateClass := 'measurement', UnitOfMeasurement := 'var');
Device^.CreateSensorEntity( Name := 'L3 Reactive Power', Id := CONCAT(id, '_L3_VAR'), StateTopic := CONCAT(THIS^.sMQTTPublishTopic, '/L3_VAR'), DeviceClass := 'reactive_power', StateClass := 'measurement', UnitOfMeasurement := 'var');
Device^.CreateSensorEntity( Name := 'L1 Power Factor', Id := CONCAT(id, '_L1_PF'), StateTopic := CONCAT(THIS^.sMQTTPublishTopic, '/L1_PF'), DeviceClass := 'power_factor', UnitOfMeasurement := '');
Device^.CreateSensorEntity( Name := 'L2 Power Factor', Id := CONCAT(id, '_L2_PF'), StateTopic := CONCAT(THIS^.sMQTTPublishTopic, '/L2_PF'), DeviceClass := 'power_factor', UnitOfMeasurement := '');
Device^.CreateSensorEntity( Name := 'L3 Power Factor', Id := CONCAT(id, '_L3_PF'), StateTopic := CONCAT(THIS^.sMQTTPublishTopic, '/L3_PF'), DeviceClass := 'power_factor', UnitOfMeasurement := '');
Device^.CreateSensorEntity( Name := 'L1 Phase Angle', Id := CONCAT(id, '_L1_PHI'), StateTopic := CONCAT(THIS^.sMQTTPublishTopic, '/L1_PHI'), DeviceClass := '', UnitOfMeasurement := '°');
Device^.CreateSensorEntity( Name := 'L2 Phase Angle', Id := CONCAT(id, '_L2_PHI'), StateTopic := CONCAT(THIS^.sMQTTPublishTopic, '/L2_PHI'), DeviceClass := '', UnitOfMeasurement := '°');
Device^.CreateSensorEntity( Name := 'L3 Phase Angle', Id := CONCAT(id, '_L3_PHI'), StateTopic := CONCAT(THIS^.sMQTTPublishTopic, '/L3_PHI'), DeviceClass := '', UnitOfMeasurement := '°');
Device^.CreateSensorEntity( Name := 'Average L-N Voltage', Id := CONCAT(id, '_AVG_V'), StateTopic := CONCAT(THIS^.sMQTTPublishTopic, '/AVG_V'), DeviceClass := 'voltage', UnitOfMeasurement := 'V');
Device^.CreateSensorEntity( Name := 'Average Line Current', Id := CONCAT(id, '_AVG_I'), StateTopic := CONCAT(THIS^.sMQTTPublishTopic, '/AVG_I'), DeviceClass := 'current', UnitOfMeasurement := 'A');
Device^.CreateSensorEntity( Name := 'Sum of Line Currents', Id := CONCAT(id, '_SUM_I'), StateTopic := CONCAT(THIS^.sMQTTPublishTopic, '/SUM_I'), DeviceClass := 'current', UnitOfMeasurement := 'A');
Device^.CreateSensorEntity( Name := 'Active Power', Id := CONCAT(id, '_ACTP'), StateTopic := CONCAT(THIS^.sMQTTPublishTopic, '/ACTP'), DeviceClass := 'power', StateClass := 'measurement', UnitOfMeasurement := 'W');
Device^.CreateSensorEntity( Name := 'Total Apparent Power', Id := CONCAT(id, '_TOT_VA'), StateTopic := CONCAT(THIS^.sMQTTPublishTopic, '/TOT_VA'), DeviceClass := 'apparent_power', StateClass := 'measurement', UnitOfMeasurement := 'VA');
Device^.CreateSensorEntity( Name := 'Total Reactive Power', Id := CONCAT(id, '_TOT_VAR'), StateTopic := CONCAT(THIS^.sMQTTPublishTopic, '/TOT_VAR'), DeviceClass := 'reactive_power', StateClass := 'measurement', UnitOfMeasurement := 'var');
Device^.CreateSensorEntity( Name := 'Total Power Factor', Id := CONCAT(id, '_TOT_PF'), StateTopic := CONCAT(THIS^.sMQTTPublishTopic, '/TOT_PF'), DeviceClass := 'power_factor', UnitOfMeasurement := '');
Device^.CreateSensorEntity( Name := 'Total Phase Angle', Id := CONCAT(id, '_TOT_PHI'), StateTopic := CONCAT(THIS^.sMQTTPublishTopic, '/TOT_PHI'), DeviceClass := '', UnitOfMeasurement := '°');
Device^.CreateSensorEntity( Name := 'Frequency', Id := CONCAT(id, '_FREQ'), StateTopic := CONCAT(THIS^.sMQTTPublishTopic, '/FREQ'), DeviceClass := 'frequency', UnitOfMeasurement := 'Hz');
Device^.CreateSensorEntity( Name := 'Total Import Energy', Id := CONCAT(id, '_IMP_ENERG'), StateTopic := CONCAT(THIS^.sMQTTPublishTopic, '/IMPE'), DeviceClass := 'energy', StateClass := 'total_increasing', UnitOfMeasurement := 'kWh');
Device^.CreateSensorEntity( Name := 'Total Export Energy', Id := CONCAT(id, '_EXP_ENERG'), StateTopic := CONCAT(THIS^.sMQTTPublishTopic, '/EXPE'), DeviceClass := 'energy', StateClass := 'total_increasing', UnitOfMeasurement := 'kWh');
bInitMqttDiscoveryDone := TRUE; END_IF

SUPER^._sInstancePath := THIS^.sInstancePath; // Due to reflection its location is important

(*pass trough*)
THIS^.pMqttPublishQueue := pMqttPublishQueue;
THIS^.psMqttPublishTopicPrefix := MQTTPublishPrefix;

SUPER^.InitBaseMqtt();

(* Modbus address and poll rate describe the wiring, not a mode, so they are
   fixed for the life of the instance and belong here rather than in a runtime
   setter. Note the consequence: changing either afterwards means editing the
   declaration in the IDE - CODESYS stores an instance's FB_init arguments beside
   the declaration text, where no script can reach them. *)
THIS^.stStep.DeviceId		:= DeviceAddress;
THIS^.stStep.FunctionCode	:= 4;
THIS^.stStep.Address		:= 12;	(* 16#000C, phase 1 active power *)
THIS^.stStep.Quantity		:= 64;	(* through 16#004B, total export energy *)

THIS^.fbTimerData.PT := DataPollingInterval;
THIS^.fbTimerData.IN := TRUE;

FB_init := TRUE;

(* One announcement per transaction, at the point the bus is released. *)
IF StepsRun > 0 AND Failures >= StepsRun THEN
	PubMqttMessage(Suffix := '/availability', Data := 'offline');
ELSIF StepsRun > 0 THEN
	PubMqttMessage(Suffix := '/availability', Data := 'online');
END_IF

IF fbTimerData.Q THEN
	HasWork := E_RS485_WORK_LEVEL.POLL;
ELSE
	HasWork := E_RS485_WORK_LEVEL.NONE;
END_IF

THIS^.fbTimerData.IN := TRUE;

(* Register 12 is the gateway's own status word for this sensor: non-zero means
   the gateway answered but the 1-Wire device behind it did not. A short reply
   is treated the same way - there is no status to trust. *)
IF Failed OR Count < 17 OR WORD_TO_INT(pData^[12]) <> 0 THEN
	THIS^.Error := TRUE;
	(* A single miss is normal on a 1-Wire bus, so availability only drops after
	   uiAllowedErrorCount of them in a row. *)
	IF THIS^.uiCurrentErrorCount >= THIS^.uiAllowedErrorCount THEN
		PubMqttMessage(Suffix := '/availability', Data := 'offline');
	END_IF
	THIS^.uiCurrentErrorCount := THIS^.uiCurrentErrorCount + 1;
	RETURN;
END_IF

THIS^.Error := FALSE;
THIS^.DataAvailable := TRUE;
THIS^.uiCurrentErrorCount := 0;
PubMqttMessage(Suffix := '/availability', Data := 'online');

IF bInitMqttDiscoveryDone THEN
	THIS^.pMqttDiscoveryDevice^.SendDeviceUpdate(Model := WORD_TO_STRING(pData^[16]));
END_IF

// Data handling
IF pData^[16] = 11151 OR pData^[16] = 11152 THEN // Temperature, humidity & air quality
	ProcessTemperature(pData^[0]);
	ProcessOwdVoltage(pData^[2]);
	ProcessHumidity(pData^[4]);
	ProcessDewPoint(pData^[6]);
	ProcessAirQuality(pData^[8]);
ELSIF pData^[16] = 11102 OR pData^[16] = 11113 OR pData^[16] = 11120 OR pData^[16] = 11148 OR pData^[16] = 11150 OR pData^[16] = 11160 THEN // Temperature, humidity
	ProcessTemperature(pData^[0]);
	ProcessOwdVoltage(pData^[2]);
	ProcessHumidity(pData^[4]);
	ProcessDewPoint(pData^[6]);
ELSIF pData^[16] = 11121 OR pData^[16] = 11132 OR pData^[16] = 11134 OR pData^[16] = 11135 THEN // Temperature, humidity, brightness
	ProcessTemperature(pData^[0]);
	ProcessOwdVoltage(pData^[2]);
	ProcessHumidity(pData^[4]);
	ProcessDewPoint(pData^[6]);
	ProcessBrigthness(pData^[8]);
ELSIF pData^[16] = 1820 THEN // Temperature DS18B20
	ProcessTemperature(pData^[0]);
END_IF

IF fbTimerData.Q THEN
	pSteps^[0]			:= stStep;
	fbTimerData.IN		:= FALSE;
	BuildTransaction	:= 1;
ELSE
	BuildTransaction := 0;
END_IF

IF bInitMqttDone AND NOT bInitMqttDiscoveryDone THEN
THIS^.pMqttDiscoveryDevice := Device;
id := SUPER^.ResolveEntityId(overruleId := '');
Device^.init1WireDevice( name := DeviceName, id := id, deviceAvailabilityTopic := CONCAT(THIS^.sMQTTPublishTopic, '/availability'), deviceDiagnosticTopic := CONCAT(THIS^.sMQTTPublishTopic, '/diagnostic'));
IF SupportsTemperature THEN Device^.CreateSensorEntity( Name := 'Temperature', Id := CONCAT(id, '_TEMP'), StateTopic := CONCAT(THIS^.sMQTTPublishTopic, '/TEMP'), DeviceClass := 'temperature', UnitOfMeasurement := '°C'); END_IF;
IF SupportsHumidity THEN Device^.CreateSensorEntity( Name := 'Humidity', Id := CONCAT(id, '_HUM'), StateTopic := CONCAT(THIS^.sMQTTPublishTopic, '/HUM'), DeviceClass := 'humidity', UnitOfMeasurement := '%'); END_IF;
IF SupportsCO2 THEN Device^.CreateSensorEntity( Name := 'Carbon Dioxide', Id := CONCAT(id, '_CO2'), StateTopic := CONCAT(THIS^.sMQTTPublishTopic, '/CO2'), DeviceClass := 'carbon_dioxide', UnitOfMeasurement := 'ppm'); END_IF;
IF SupportsDewPoint THEN Device^.CreateSensorEntity( Name := 'Dew Point', Id := CONCAT(id, '_DEWP'), StateTopic := CONCAT(THIS^.sMQTTPublishTopic, '/DEWP'), DeviceClass := 'temperature', UnitOfMeasurement := '°C'); END_IF;
IF SupportsBrightness THEN Device^.CreateSensorEntity( Name := 'Brightness', Id := CONCAT(id, '_ILLUM'), StateTopic := CONCAT(THIS^.sMQTTPublishTopic, '/ILLUM'), DeviceClass := 'illuminance'); END_IF;
IF SupportsOwdVoltage THEN Device^.CreateDiagnosticSensorEntity( Name := 'Operating Voltage', Id := CONCAT(id, '_OWDV'), StateTopic := CONCAT(THIS^.sMQTTPublishTopic, '/OWDV')); END_IF;
bInitMqttDiscoveryDone := TRUE; END_IF

SUPER^._sInstancePath := THIS^.sInstancePath; // Due to reflection its location is important

(*pass trough*)
THIS^.pMqttPublishQueue := pMqttPublishQueue;
THIS^.psMqttPublishTopicPrefix:=MQTTPublishPrefix;
SUPER^.InitBaseMqtt();

THIS^.BRIGHTNESS := WORD_TO_REAL(Data) / 100;
(* /ILLUM, matching the entity id and the StateTopic in InitMqttDiscovery.
   This published to /BNESS, so the illuminance entity never received a value. *)
PubMqttMessage(Suffix := '/ILLUM', Data := REAL_TO_STRING(BRIGHTNESS));

THIS^.stStep.DeviceId		:= DeviceAddress;
THIS^.stStep.FunctionCode	:= 3;
THIS^.stStep.Address		:= OwdNumber * 100;
THIS^.stStep.Quantity		:= 17;

THIS^.fbTimerData.PT := DataPollingInterval;
THIS^.OwdNumber := OwdNumber;

THIS^.fbTimerData.IN := TRUE;

FB_Init := TRUE;

(* ---------------------------------------------------------------- the port *)
IF bReopenRequest THEN
	bReopenRequest := FALSE;
	IF PortOpen THEN
		SysCom.SysComClose(hPort);
	END_IF
	PortOpen	:= FALSE;
	PortError	:= FALSE;
	iState		:= 0;
	eOutcome		:= E_RS485_STEP_STATE.IDLE;
END_IF

IF bConfigured AND NOT PortOpen AND NOT PortError THEN
	hPort		:= SysCom.SysComOpen2(pSettings := ADR(stSettings), pSettingsEx := 0, pResult := ADR(eRtsResult));
	PortError	:= (hPort = RTS_INVALID_HANDLE OR eRtsResult <> 0);
	PortOpen	:= NOT PortError;
END_IF

(* Both timers are called unconditionally. A TON left with IN true while the
   iState machine is elsewhere goes on counting, and would then fire instantly
   on the next stStep. *)
fbGap(IN := (iState = 1) AND NOT bRestartGap, PT := GapTime);
fbReplyTimer(IN := (iState = 1) AND NOT bRestartReply, PT := ReplyTimeout);
bRestartGap		:= FALSE;
bRestartReply	:= FALSE;

(* ------------------------------------------------------- the stStep in flight *)
CASE iState OF

0:	(* Idle. OK and FAILED were each returned for exactly one cycle, by the
	   return at the bottom of the cycle that reached iState 2. *)
	eOutcome := E_RS485_STEP_STATE.IDLE;

1:	(* Collect until the line has been quiet for GapTime, which is how RTU
	   delimits a frame, or until the slave has clearly not answered at all. *)
	IF udiRxCount < SIZEOF(abyRx) THEN
		pbyRx := ADR(abyRx);
		pbyRx := pbyRx + udiRxCount;
		udiN := SysCom.SysComRead(hPort, pbyRx, SIZEOF(abyRx) - udiRxCount, 0, ADR(eRtsResult));
		IF udiN > 0 THEN
			udiRxCount		:= udiRxCount + udiN;
			bRestartGap	:= TRUE;
		END_IF
	END_IF

	(* A frame whose wCrc already checks out is complete by definition, so there
	   is nothing left to wait for. Waiting anyway costs about three task cycles
	   per stStep, and on a 200 ms task that is most of what a Modbus exchange
	   takes: measured at 1.87 s per stStep before this check, against roughly
	   100 ms of actual wire time at 9600 baud.

	   The silence timer stays as the fallback for everything that does not
	   frame cleanly - a partial reply, a burst of noise, a slave that answers
	   with something we cannot parse. *)
	count := UDINT_TO_INT(udiRxCount);
	IF count >= 5 AND THIS^.Frame() THEN
		iState := 2;
	ELSIF (udiRxCount > 0 AND fbGap.Q) OR fbReplyTimer.Q OR udiRxCount >= SIZEOF(abyRx) THEN
		iState := 2;
	END_IF

2:	THIS^.Judge();
	iState := 0;

END_CASE

Service := eOutcome;

Start := FALSE;

IF pStep = 0 OR NOT PortOpen OR iState <> 0 THEN
	RETURN;
END_IF

(* Private copy. The scheduler's stStep list is scratch that it reuses for the
   next device, so nothing may be read back out of it later - the echo checks
   below run against this copy. *)
stStep := pStep^;
iQty := UINT_TO_INT(stStep.Quantity);

CASE stStep.FunctionCode OF

3, 4:	(* read holding / read input registers *)
	IF iQty < 1 OR iQty > (DINT_TO_INT(UPPER_BOUND(Data, 1)) + 1) THEN
		RETURN;
	END_IF
	abyTx[0] := stStep.DeviceId;
	abyTx[1] := stStep.FunctionCode;
	abyTx[2] := UINT_TO_BYTE(SHR(stStep.Address, 8));
	abyTx[3] := UINT_TO_BYTE(stStep.Address AND 16#00FF);
	abyTx[4] := UINT_TO_BYTE(SHR(stStep.Quantity, 8));
	abyTx[5] := UINT_TO_BYTE(stStep.Quantity AND 16#00FF);
	iTxLen := 6;

6:	(* write single register: the value goes where the quantity would *)
	abyTx[0] := stStep.DeviceId;
	abyTx[1] := 16#06;
	abyTx[2] := UINT_TO_BYTE(SHR(stStep.Address, 8));
	abyTx[3] := UINT_TO_BYTE(stStep.Address AND 16#00FF);
	abyTx[4] := WORD_TO_BYTE(SHR(stStep.Data[0], 8));
	abyTx[5] := WORD_TO_BYTE(stStep.Data[0] AND 16#00FF);
	iTxLen := 6;

16:	(* write multiple registers: header, byte count, then the payload *)
	IF iQty < 1 OR iQty > (DINT_TO_INT(UPPER_BOUND(stStep.Data, 1)) + 1) THEN
		RETURN;
	END_IF
	abyTx[0] := stStep.DeviceId;
	abyTx[1] := 16#10;
	abyTx[2] := UINT_TO_BYTE(SHR(stStep.Address, 8));
	abyTx[3] := UINT_TO_BYTE(stStep.Address AND 16#00FF);
	abyTx[4] := UINT_TO_BYTE(SHR(stStep.Quantity, 8));
	abyTx[5] := UINT_TO_BYTE(stStep.Quantity AND 16#00FF);
	abyTx[6] := INT_TO_BYTE(iQty * 2);
	FOR iI := 0 TO iQty - 1 DO
		abyTx[7 + 2 * iI] := WORD_TO_BYTE(SHR(stStep.Data[iI], 8));
		abyTx[8 + 2 * iI] := WORD_TO_BYTE(stStep.Data[iI] AND 16#00FF);
	END_FOR
	iTxLen := 7 + 2 * iQty;

ELSE
	(* Refused, not guessed at. Guessing is precisely the bug this replaces:
	   every function code used to be framed from the read fields, so an FC6
	   write went out as "write register 0 := 0" and its echoed reply was then
	   parsed as though byte 2 were a length. *)
	RETURN;

END_CASE

(* Anything still in the receive buffer belongs to the previous exchange and
   would otherwise be collected as this one's reply. *)
udiN := SysCom.SysComRead(hPort, ADR(abyFlush), SIZEOF(abyFlush), 0, ADR(eRtsResult));

wCrc := THIS^.Crc16(pBuf := ADR(abyTx), Len := iTxLen);
abyTx[iTxLen]		:= WORD_TO_BYTE(wCrc AND 16#00FF);
abyTx[iTxLen + 1]	:= WORD_TO_BYTE(SHR(wCrc, 8));

SysCom.SysComWrite(hPort, ADR(abyTx), INT_TO_UDINT(iTxLen + 2), 100, ADR(eRtsResult));

udiRxCount			:= 0;
iRegCount		:= 0;
bRestartGap		:= TRUE;
bRestartReply	:= TRUE;
eOutcome			:= E_RS485_STEP_STATE.BUSY;
iState			:= 1;
Start			:= TRUE;

count		:= UDINT_TO_INT(udiRxCount);
bGotFrame	:= THIS^.Frame();

(* Leading glitch bytes are the slave's driver enabling onto an undriven pair,
   trailing ones its releasing. Both are normal on this hardware. *)
IF iFirst > 0 THEN
	LeadNulls := LeadNulls + 1;
END_IF
IF bGotFrame AND iLast < count THEN
	TrailNulls := TrailNulls + 1;
END_IF

iFrameLen	:= iLast - iFirst;
iRegCount	:= 0;
bDataValid		:= FALSE;

IF count = 0 OR (count - iFirst) = 0 THEN
	NoReply := NoReply + 1;

ELSIF (count - iFirst) < 5 THEN
	ShortFrame := ShortFrame + 1;

ELSIF NOT bGotFrame THEN
	CrcFail := CrcFail + 1;

	(* Capture what actually arrived. Two theories about these failures have now
	   been wrong - leading glitch bytes, then a framer that could not
	   resynchronise - and both were argued from counters rather than from
	   bytes. A counter says a frame did not check out; it cannot say whether
	   what arrived was half a reply, two replies, an echo, or noise. Decimal
	   rather than hex because there is no hex helper in scope and the point is
	   to read it off an MQTT topic, not to look pretty. *)
	LastFailLen := udiRxCount;

	(* Whose window this landed in. Without it the bytes are unattributable, and
	   a frame that looks like somebody else's request is exactly the case that
	   needs telling apart from a mangled reply. *)
	LastFailAddr := stStep.DeviceId;
	LastFailFunc := stStep.FunctionCode;

	LastFailBytes := '';
	FOR iI := 0 TO count - 1 DO
		IF iI >= 24 THEN
			EXIT;
		END_IF
		LastFailBytes := CONCAT(LastFailBytes, BYTE_TO_STRING(abyRx[iI]));
		LastFailBytes := CONCAT(LastFailBytes, ' ');
	END_FOR
	FOR iI := 0 TO count - 1 DO
		IF iI >= 24 THEN
			EXIT;
		END_IF
		LastFailBytes := CONCAT(LastFailBytes, BYTE_TO_STRING(abyRx[iI]));
		LastFailBytes := CONCAT(LastFailBytes, ' ');
	END_FOR

ELSIF abyRx[iFirst] <> stStep.DeviceId THEN
	(* Well formed, intact, and not ours. On a shared bus that is somebody
	   else's traffic; on this one it means the reply was mis-framed. *)
	BadAddress := BadAddress + 1;

ELSIF abyRx[iFirst + 1] = (stStep.FunctionCode OR 16#80) THEN
	Exceptions		:= Exceptions + 1;
	LastException	:= abyRx[iFirst + 2];

ELSIF abyRx[iFirst + 1] <> stStep.FunctionCode THEN
	BadFunction := BadFunction + 1;

ELSE
	CASE stStep.FunctionCode OF

	3, 4:	(* addr, fc, byte count, data, crc16 *)
		iBytecount := BYTE_TO_INT(abyRx[iFirst + 2]);
		IF iBytecount < 2 OR iBytecount > (iFrameLen - 5) THEN
			ShortFrame := ShortFrame + 1;
		ELSE
			iRegCount := iBytecount / 2;
			IF iRegCount > (DINT_TO_INT(UPPER_BOUND(Data, 1)) + 1) THEN
				iRegCount := DINT_TO_INT(UPPER_BOUND(Data, 1)) + 1;
			END_IF
			(* Registers are big-endian on the wire, which is the order
			   F_SWAP_WORDS_TO_REAL expects at the far end. *)
			FOR iI := 0 TO iRegCount - 1 DO
				Data[iI] := SHL(BYTE_TO_WORD(abyRx[iFirst + 3 + 2 * iI]), 8)
				           OR BYTE_TO_WORD(abyRx[iFirst + 4 + 2 * iI]);
			END_FOR
			Ok		:= Ok + 1;
			bDataValid	:= TRUE;
		END_IF

	6:	(* The reply is the request echoed back. There is no byte count in it,
		   and reading byte 2 as one - which is what this code did for every
		   function code before - reads an address high byte as a length. *)
		IF iFrameLen < 8 THEN
			ShortFrame := ShortFrame + 1;
		ELSE
			uiEchoAddr	:= SHL(BYTE_TO_UINT(abyRx[iFirst + 2]), 8) OR BYTE_TO_UINT(abyRx[iFirst + 3]);
			uiEchoValue	:= SHL(BYTE_TO_UINT(abyRx[iFirst + 4]), 8) OR BYTE_TO_UINT(abyRx[iFirst + 5]);
			IF uiEchoAddr <> stStep.Address OR uiEchoValue <> WORD_TO_UINT(stStep.Data[0]) THEN
				(* The slave acknowledged something other than what was asked.
				   Never report this as success: a read-after-write would then
				   publish a confirmation for a write that did not happen. *)
				BadEcho := BadEcho + 1;
			ELSE
				Ok		:= Ok + 1;
				bDataValid	:= TRUE;
			END_IF
		END_IF

	16:	(* addr, 16, start address, quantity written, crc16 *)
		IF iFrameLen < 8 THEN
			ShortFrame := ShortFrame + 1;
		ELSE
			uiEchoAddr	:= SHL(BYTE_TO_UINT(abyRx[iFirst + 2]), 8) OR BYTE_TO_UINT(abyRx[iFirst + 3]);
			uiEchoValue	:= SHL(BYTE_TO_UINT(abyRx[iFirst + 4]), 8) OR BYTE_TO_UINT(abyRx[iFirst + 5]);
			IF uiEchoAddr <> stStep.Address OR uiEchoValue <> stStep.Quantity THEN
				BadEcho := BadEcho + 1;
			ELSE
				Ok		:= Ok + 1;
				bDataValid	:= TRUE;
			END_IF
		END_IF

	END_CASE
END_IF

IF bDataValid THEN
	eOutcome := E_RS485_STEP_STATE.OK;
ELSE
	eOutcome := E_RS485_STEP_STATE.FAILED;
END_IF

(* Modbus RTU CRC16: polynomial 16#A001, seed 16#FFFF, transmitted low byte
   iFirst. A whole bDataValid frame including its own wCrc therefore checksums to zero,
   which is how a received frame is judged - no need to know where the data
   ends before deciding whether it is intact. *)
wAcc := 16#FFFF;
pbyP := pBuf;

FOR iI := 0 TO Len - 1 DO
	wAcc := wAcc XOR BYTE_TO_WORD(pbyP[iI]);
	FOR iB := 0 TO 7 DO
		IF (wAcc AND 16#0001) <> 0 THEN
			wAcc := SHR(wAcc, 1) XOR 16#A001;
		ELSE
			wAcc := SHR(wAcc, 1);
		END_IF
	END_FOR
END_FOR

Crc16 := wAcc;

(* stSettings are assigned here rather than in a declaration initialiser. A value
   inside an existing structured initialiser cannot be changed from a script -
   the compiler goes on reading the stored structValue - and having them in code
   means Reopen can bring the port back up with different stSettings from an
   online session. *)
stSettings.sPort			:= Port;
stSettings.ulBaudrate		:= Baudrate;
stSettings.byParity		:= Parity;
stSettings.byStopBits		:= StopBits;
stSettings.ulTimeout		:= 0;
stSettings.ulBufferSize	:= 256;

IF ReplyTimeout > T#0S THEN
	THIS^.ReplyTimeout := ReplyTimeout;
END_IF
IF GapTime > T#0S THEN
	THIS^.GapTime := GapTime;
END_IF

(* Remember all of it, so Retune can wander off and RestoreTuning can come back
   without the caller repeating itself. Taken after the defaults above have been
   applied, so what is saved is what the port is actually running. *)
stConfiguredSettings		:= stSettings;
tConfiguredReplyTimeout	:= THIS^.ReplyTimeout;
tConfiguredGapTime		:= THIS^.GapTime;

bConfigured := TRUE;

(* Re-open if the port was already up, so calling Init twice is not a silent
   no-op with the old stSettings still in force. *)
bReopenRequest := PortOpen;

(* One field at a time, which is what a sweep needs: everything not named here
   stays as Init bConfigured it. Takes effect on the next Service, like Reopen. *)
IF NOT bConfigured THEN
	Retune := FALSE;
	RETURN;
END_IF

IF Baudrate > 0 THEN
	stSettings.ulBaudrate := Baudrate;
END_IF
IF StopBitsRaw <> 255 THEN
	stSettings.byStopBits := StopBitsRaw;
END_IF
IF ReplyTimeout > T#0S THEN
	THIS^.ReplyTimeout := ReplyTimeout;
END_IF
IF GapTime > T#0S THEN
	THIS^.GapTime := GapTime;
END_IF

Reopen();
Retune := TRUE;

(* Whatever a sweep did to stSettings, this is the way back. Reopen rather than an
   immediate close: the port is only ever touched from Service, so that a caller
   cannot pull the bus out from under a frame in flight. *)
IF NOT bConfigured THEN
	RETURN;
END_IF

stSettings		:= stConfiguredSettings;
ReplyTimeout	:= tConfiguredReplyTimeout;
GapTime			:= tConfiguredGapTime;

Reopen();

