(* fbDoCover001 keeps the relays it always had. The position-capable block gets DO_005 and DO_006, freed in HVAC_RUN for exactly this - two LEDs on the second output module that can be watched while the cover is commanded from Home Assistant, which is what makes the position logic verifiable at a glance.
One writer per coil, in one task. DO_005..DO_008 used to be written from HvacTask, and a second writer here would have made both meaningless without the compiler saying a word. *) fbDoCover001( TOGGLE:=fbDiPb001.P_LONG, MU=>DO_003, MD=>DO_004 );
fbDoCover002( T_TravelUp := T#20S, T_TravelDown := T#20S, MU => DO_005, MD => DO_006 );

fbDiPb001(PB:= DI_001); (* Provide the input FB the correct phyical input to validate each cyclus *)
fbDiPb002(PB:= DI_002);
(* The RTD channel is read here because this action is the one the chart runs
   every cycle to take the physical inputs in, and an analog channel is a
   physical input. It would sit better in an action of its own - the name of
   this one is now half a lie - but an action has to be associated with a step
   in the SFC chart to be called at all, and a chart cannot be edited from a
   script. Moving it is an IDE job worth doing the next time this program is
   open. *)
fbAiRtd001(Raw := RTD_001, HeartbeatInterval := tRtdPublishInterval,
	ProcessImageValid := Pfc200Bus.xConfigFinished);
fbAiRtd002(Raw := RTD_002, HeartbeatInterval := tRtdPublishInterval,
	ProcessImageValid := Pfc200Bus.xConfigFinished);
fbAiRtd003(Raw := RTD_003, HeartbeatInterval := tRtdPublishInterval,
	ProcessImageValid := Pfc200Bus.xConfigFinished);
fbAiRtd004(Raw := RTD_004, HeartbeatInterval := tRtdPublishInterval,
	ProcessImageValid := Pfc200Bus.xConfigFinished);
fbAiRtd005(Raw := RTD_005, HeartbeatInterval := tRtdPublishInterval,
	ProcessImageValid := Pfc200Bus.xConfigFinished);
fbAiRtd006(Raw := RTD_006, HeartbeatInterval := tRtdPublishInterval,
	ProcessImageValid := Pfc200Bus.xConfigFinished);
fbAiRtd007(Raw := RTD_007, HeartbeatInterval := tRtdPublishInterval,
	ProcessImageValid := Pfc200Bus.xConfigFinished);
fbAiRtd008(Raw := RTD_008, HeartbeatInterval := tRtdPublishInterval,
	ProcessImageValid := Pfc200Bus.xConfigFinished);


(* K-BUS CONTROL. Written every cycle so that setting either flag in an online
   view is enough; see their declarations for what they do and in which order.
   Pfc200Bus() is called explicitly because that is what reads xRestart - the
   implicit bus cycle call does not. *)
Pfc200Bus.EnableIoCheck := bKbusEnableIoCheck;
Pfc200Bus.xRestart := bKbusRestart;
Pfc200Bus();

(* MQTT wiring no longer lives here.
Every block that extends FB_MQTT_BASE now wires itself from GVL_MQTT on its first cyclic call and announces itself to Home Assistant, driven by the FriendlyName set on its declaration above. What remains in this action is the behavioural configuration that genuinely is per-instance and is not MQTT, which is now only the E_DIMMER's timings. *)
(* ALTER THE E_DIMMER OUTPUT DEFAULT BEHAVIOR *) fbAoDimmer001.ConfigureFunctionBlock( T_Debounce:=T#10MS, T_Reconfig:=T#10S, T_On_Max:=T#0S, T_Dimm_Start:=T#400MS, T_Dimm:=T#3S, Min_On:=50, Max_On:=255, Soft_Dimm:=TRUE, Rst_Out:=FALSE, OUT_LinearScaleMin:=11000, OUT_LinearScaleMax:=32767 );
(* Cover timings now travel through FB_init at the instance declaration. *)
(* DALI *) (* FB_DALI_1_ADR0.InitMqtt(MQTTPublishPrefix:= ADR(GVL_MQTT.MqttPubDimmerPrefix), MQTTSubscribePrefix:= ADR(GVL_MQTT.MqttSubDimmerPrefix), pMqttPublishQueue := ADR(GVL_MQTT.fbMqttPublishQueue), pMqttCallbackCollector := ADR(GVL_MQTT.collector_FB_DIMMER_MQTT) );
FB_DALI_1_ADR0.InitMqttDiscovery(ADR(GVL_MQTT.PLC_Device), 'Keuken'); *)
GVL_MQTT.PLC_Device.SendLogMessage('Init finished', 'MAIN_INIT');

fbDoBin001(OUT	=>		DO_001,										(* couple the function block to the physical output *)
	PRIO_HIGH				:=FALSE,  									(* brings the output high regardless of other input values *)
	PRIO_LOW				:=FALSE, 									(* brings the output low regardless of other input values. NOTE: PRIO_HIGH overrules PRIO_LOW input *)
	TOGGLE					:=fbDiPb001.SINGLE 						(* for toggling the output *)	
);

fbAoDimmer001(
	SINGLE:=fbDiPb001.SINGLE,
	LONG:=fbDiPb001.LONG, 
	P_LONG:=fbDiPb001.P_LONG, 
	Q_OUT => wTestOUT,
	SET:=  fbDiPb001.DOUBLE,
	VAL:=125
);

fbDoBistable001();

// Run the master before anything else
(*
M1_DALIMASTER(
	bPortDALI:=1,
	I_Port:=IoConfig_Globals.DALI_MULTI_MASTER_MODULE);

// Run individual DALI FB
FB_DALI_1_ADR0(
	BALLAST := GVL_DALI.M1_Light1,
	TOGGLE := fbDiPb002.SINGLE,
	P_LONG := fbDiPb002.P_LONG,
	STATUS_LED => DO_002);
	*)

IF init = FALSE THEN
	init := TRUE;
	//https://art-net.org.uk/how-it-works/streaming-packets/artdmx-packet-definition/
	(* Write DMX header character in the buffer *) 
	stSBuf1.BUFFER [0]:= BYTE#16#41; // A
	stSBuf1.BUFFER [1]:= BYTE#16#72; // R	
	stSBuf1.BUFFER [2]:= BYTE#16#74; // T
	stSBuf1.BUFFER [3]:= BYTE#16#2D; // -
	stSBuf1.BUFFER [4]:= BYTE#16#4E; // N
	stSBuf1.BUFFER [5]:= BYTE#16#65; // E
	stSBuf1.BUFFER [6]:= BYTE#16#74; // T
	stSBuf1.BUFFER [7]:= BYTE#16#00; // 0 zero

	stSBuf1.BUFFER [8]:= BYTE#16#00;	// Opcode ArtDMX (0x5000) little endian
	stSBuf1.BUFFER [9]:= BYTE#16#50; // Opcode ArtDMX (0x5000) little endian

	stSBuf1.BUFFER [10]:= BYTE#16#00; // Protocol Version Hi (0)
	stSBuf1.BUFFER [11]:= BYTE#16#0E; // Protocol Version Lo (14)

	stSBuf1.BUFFER [12]:= BYTE#16#00; // Sequence
	stSBuf1.BUFFER [13]:= BYTE#16#00; // Physical

	stSBuf1.BUFFER [16]:= BYTE#16#02; // Length Hi
	stSBuf1.BUFFER [17]:= BYTE#16#00; // Length Lo (2 to 512, even)
	(* the DMX channels that are next have already been written to the buffer *) 

	IF iUniverse = 1 THEN
		stSBuf1.BUFFER [14]:= BYTE#16#01; // iUniverse little endian
		stSBuf1.BUFFER [15]:= BYTE#16#00; // iUniverse little endian
	END_IF
	IF iUniverse = 2 THEN
		stSBuf1.BUFFER [14]:= BYTE#16#02; // iUniverse little endian
		stSBuf1.BUFFER [15]:= BYTE#16#00; // iUniverse little endian
	END_IF
END_IF;


size := 512+18;
FOR iI:= 0 TO 511 DO (* check whether the DMX values ​​in the global variable have changed *)
	// iI+2 is strange, buffers are not the same, its often offset with 2 sometimes by 1, todo
	IF stSBuf1.BUFFER[iI+18] <> GVL_DMX.DMX.BUFFER[iI+2] THEN
   		stSBuf1.BUFFER[iI+18]:= GVL_DMX.DMX.BUFFER[iI+2];
		iStep := 1;
	END_IF
END_FOR



fbErrorTrig(CLK := IP_C.ERROR <> 0);

CASE iStep OF
	0:
		//passive

	1:
		IP_C.C_MODE := 1; (* Mode: UDP+ACTIVE+Port+IP *)
		IP_C.C_ENABLE := TRUE; (* Release connection *)
		IP_C.TIME_RESET := TRUE; (*Reset TIME monitoring * *)
		IP_C.R_OBSERVE := TRUE; (* Monitor data receive *)
		stRBuf1.SIZE:= 0; (* Reset Home length *)
		IP_C.C_IP:= oscat_network.IP4_DECODE (GVL_DMX.IP);
		IP_C.C_PORT:= WORD#6454;

		stSBuf1.SIZE := size;
		iStep:=2;

	2:
		IP_CONTROL2 (TIME_OUT:= T#1S, IP_C:= IP_C, S_BUF:= stSBuf1, R_BUF:= stRBuf1);

		IF IP_C.ERROR <> 0  THEN
			iStep:=666;
		END_IF
	666:		
     	PFC.SetLed(which:=PFC.LED.U3, how:=PFC.LedState.BLINK_RED);
		IF fbErrorTrig.Q AND IP_C.ERROR = 33554432 THEN
		GVL_MQTT.PLC_Device.SendLogMessage(CONCAT('ERROR|DMX has a connection error ', DWORD_TO_STRING(IP_C.ERROR)));

		END_IF;

		bErrorSend := TRUE;
		stRBuf1.SIZE := 0;
		IP_C.C_ENABLE:= FALSE; (* Enable connection establishment *) 
		IP_C.TIME_RESET:= FALSE;
		init:=FALSE;
		(* Leave the error state. Without this the branch re-ran every scan; init is
		   FALSE so the header is rebuilt, and the change-detect loop re-arms iStep. *)
		iStep := 0;
	ELSE
	  iStep := 0;
END_CASE



// Check IP_C1.error
// 33554432 = 0x02000000
// Initialization of the socket interface failed (only WinNT).
// code = 0x 02 00 00 00 (hexadecimal)
//           !   !    ! 
//           !   !    Receive error 
//           !   Send error
//           Connect error

(* allow the device to do its work *) GVL_MQTT.PLC_Device();
(* The MQTT client reports its own state on an output, so copy it in before anything looks at it. Nothing populated stMQTTInfo before this line existed, which is why MQTT_CONNECTED was permanently FALSE: no edge could ever fire, so the U1 LED never went green and the birth message was left to the heartbeat alone. *) stMQTTInfo := MQTT_IN_OUT.clientFB.MQTT_INFO;
(* Healthy means the client has a session AND the broker is really reachable, and the second half is not redundant: MQTT_CONNECTED does not notice a pulled network cable. TCP has nothing to report until a retransmit finally gives up, so the client holds a dead socket open for minutes and goes on claiming a session. Verified on the bench: LAN cable out, MQTT_CONNECTED still TRUE, U1 still green. GVL_MQTT.bBrokerReachable is an ICMP check owned by the Ping task. *) bBrokerHealthy := stMQTTInfo.MQTT_CONNECTED AND GVL_MQTT.bBrokerReachable;
(* U1 makes broker health readable from the cabinet without a laptop: steady green while it is healthy, blinking red while it is not.
Written only when it changes, because SetLed is a runtime call - but from a remembered state rather than from a pair of edge detectors, so there is one code path instead of two. Two is how this was broken before: the falling-edge detector was called once, from MQTT_INIT, so its Q could never become TRUE and the LED could never go red, while the rising-edge half looked perfectly fine. bLedShowsHealthy also reports what the LED is showing, which a one-cycle Q cannot, so a test can read the colour back. *) IF bBrokerHealthy <> bLedShowsHealthy THEN IF bBrokerHealthy THEN PFC.SetLed(which := PFC.LED.U1, how := PFC.LedState.STATIC_GRN); ELSE PFC.SetLed(which := PFC.LED.U1, how := PFC.LedState.BLINK_RED); END_IF bLedShowsHealthy := bBrokerHealthy; END_IF
(* Rising edge of the MQTT session, which is what the birth message wants - not bBrokerHealthy, because announcing availability is about having a session to announce it on. *) fbMQTTConnectTrigger(CLK := stMQTTInfo.MQTT_CONNECTED);
(* allow the pulse generator to generate a pulse, used for birth message hartbeat *) fbMQTTBirthHartbeat(ENQ:=TRUE, PTH:=T#0S, PTL:=GVL_MQTT.MQTTAvailabilityHartbeatTime);
(* Check if this is a new connection due to startup or connection issues *) IF initMqtt AND (fbMQTTConnectTrigger.Q OR fbMQTTBirthHartbeat.Q) THEN bMQTTPublishBirth := TRUE; END_IF
(* On connect or reconnect publish a birth message using the dedicated birth publisher *) IF bMQTTPublishBirth THEN fbMQTTBirthPublisher.PublishMessage(MqttMessage := stMQTTBirthMessage); bMQTTPublishBirth:=FALSE; END_IF
(* Check if Mqtt is initialized AND if there are elements on the queue to process AND if a stMQTTBirthMessage has been published successfully *) IF initMqtt AND GVL_MQTT.fbMqttPublishQueue.HasMessage() AND bMQTTPublishBirth = FALSE AND fbMQTTBirthPublisher.SendDone THEN (* Loop through all free afbPublishers untill there are no more elements in the queue or no more free afbPublishers *) FOR udiI:=0 TO (udiIpublishers-1) DO (* use the afbPublishers that are free *) IF afbPublishers[udiI].SendDone AND GVL_MQTT.fbMqttPublishQueue.HasMessage() THEN (* Pass message from the queue to a publisher *) afbPublishers[udiI].PublishMessage(MqttMessage:= GVL_MQTT.fbMqttPublishQueue.GetMessage()); ELSIF NOT GVL_MQTT.fbMqttPublishQueue.HasMessage() THEN (* Queue is empty, jump out of the for loop *) EXIT; END_IF END_FOR END_IF
(* If MQTT is initialized, let the MqttPublishWorkers do their work *) IF initMqtt THEN MQTT_IN_OUT.clientFB( MQTT_IN_OUT:= MQTT_IN_OUT, ENABLE:= TRUE, URL:= GVL_MQTT.broker, TIMEOUT:= T#1S, TLS:= FALSE);
fbMQTTBirthPublisher();
FOR udiI := 0 TO (udiIpublishers-1) DO afbPublishers[udiI](); END_FOR
END_IF

IF NOT initMqtt THEN
	initMqtt := TRUE;
	(* Basic MQTT config *)
	MQTT_IN_OUT.ClientID := GVL_MQTT.clientID;

	(* Set the LWT topic / payload *)
	MQTT_IN_OUT.BuildWillTopicAndMessage := FALSE;
	MQTT_IN_OUT.WillTopicBase := '';
	MQTT_IN_OUT.ClientWillTopic := GVL_MQTT.MqttAvailabilityTopic;
	MQTT_IN_OUT.ClientWillMessage := GVL_MQTT.MqttAvailabilityOfflinePayload;

	(* Set the birth message *)
	stMQTTBirthMessage.Payload := GVL_MQTT.MqttAvailabilityOnlinePayload;
	stMQTTBirthMessage.Topic := GVL_MQTT.MqttAvailabilityTopic;
	stMQTTBirthMessage.Qos := GVL_MQTT.MQTT_QOS_EXACTLY_ONCE;
	stMQTTBirthMessage.MqttRetain := FALSE;

	(* Nothing is connected yet, so start U1 from the disconnected state and record
	   that that is what it shows. Without this the LED keeps whatever the runtime
	   left on it, because MQTT_PUBLISH only writes on a change and at a cold start
	   its remembered state and the real state already agree. *)
	PFC.SetLed(which := PFC.LED.U1, how := PFC.LedState.BLINK_RED);
	bLedShowsHealthy := FALSE;

	(* Configure the dedicated MQTTBirth publisher *)
	fbMQTTBirthPublisher.Init(inputMQTT_IN_OUT:= ADR(MQTT_IN_OUT));

	(* Configure the pulse generator for the birth message hartbeat *)
	 fbMQTTBirthHartbeat(ENQ:=TRUE, PTH:=T#0S, PTL:=GVL_MQTT.MQTTAvailabilityHartbeatTime);

	(* INIT MQTT PUBLISH STUFF *)
	FOR udiIcounter := 0 TO (udiIpublishers-1) DO		
		afbPublishers[udiIcounter].Init(inputMQTT_IN_OUT:= ADR(MQTT_IN_OUT));
	END_FOR 

	(* INIT MQTT SUBSCRIBE STUFF *)
	fbSubscriberFbOutputSwitchMqtt.SetMqttInOut(MQTT_IN_OUT:= MQTT_IN_OUT);	
	fbSubscriberFbOutputCoverMqtt.SetMqttInOut(MQTT_IN_OUT:= MQTT_IN_OUT);
	fbSubscriberFbDimmerMqtt.SetMqttInOut(MQTT_IN_OUT:= MQTT_IN_OUT);
	fbSubscriberFbRs485Mqtt.SetMqttInOut(MQTT_IN_OUT:= MQTT_IN_OUT);
	fbSubscriberFbHvacMqtt.SetMqttInOut(MQTT_IN_OUT:= MQTT_IN_OUT);
END_IF

(* The thermostats, the pumps and the burner now wire and announce themselves from
   their FriendlyName, set where they are declared. What is left here is the one
   block a name cannot describe.

   fbPump2Collector keeps BOTH of its calls, and they belong together: its
   discovery config carries eight separate valve names, so it cannot be driven from
   a single FriendlyName - and because InitMqttDiscovery does nothing until
   InitMqttDone is TRUE, moving only its wiring into the block would leave this
   discovery call running a cycle too early, silently announcing nothing. *)

IF NOT bInitHvacDone THEN
	bInitHvacDone := TRUE;

	fbPump2Collector.InitMqtt(ADR(GVL_MQTT.MqttPubHVACPrefix), ADR(GVL_MQTT.fbMqttPublishQueue));
	asCollectorValveNames[1] := 'Radiator 1';
	asCollectorValveNames[2] := 'Radiator 2';
	fbPump2Collector.InitMqttDiscovery(ADR(GVL_MQTT.PLC_Device), asCollectorValveNames);
END_IF

// HVAC flow 1
// 1. A thermostat requests heat once:
// 		1.1 The measured temperature is below the target temperature (hysteresis possible)
//		1.2 The thermostat is in 'heat' mode (or auto mode)
//		1.3 The temperature sensor used in the thermostat is not in error
//		1.4 The measured temperature is not above the configured max temperature
// 2. The Thermostat connects to a heating Valve turning it on/open when heat is required
//		2.1 The heating valve takes X amount of time to switch fully open
//		2.2 The heating valve can only turn on the pump once it's fully open
// 		2.3 The heating valve can only start closing once the pump has completed its minimum cycle time
// 3. The Heating valve is part of PUMP circuit together with other valves:
//		3.1 The pump can only turn off if it has ran for its minimum cycle time
//		3.2 Whenever the pump is running it should request heat from the heating system
// 4. The heating system should provide heat from the moment one pump requires it
//		4.1 A system might have multiple pumps
//		4.2 The heating system might have a minimum cycle time 

// 1. A thermostat requests heat once:
// 		1.1 The measured temperature is below the target temperature (hysteresis possible)
//		1.2 The thermostat is in 'heat' mode (or auto mode)
//		1.3 The temperature sensor used in the thermostat is not in error
//		1.4 The measured temperature is not above the configured max temperature
// 2. The Thermostat connects to a pump turning it on when heat is required
//		2.1 The pump can only turn off if it has ran for its minimum cycle time
//		2.2 Whenever the pump is running it should request heat from the heating system
// 3. The heating system should provide heat from the moment one pump requires it
//		3.1 A system might have multiple pumps
//		3.2 The heating system might have a minimum cycle time 


// FLoorheating
fbThermostat1(MEASURED_TEMP := GVL_RS485.FB_RS485_1WIRE_MULTISENSOR_01.TEMPERATURE, MEASURED_HUM := GVL_RS485.FB_RS485_1WIRE_MULTISENSOR_01.HUMIDITY, SENSOR_VALID := GVL_RS485.FB_RS485_1WIRE_MULTISENSOR_01.DataAvailable AND NOT GVL_RS485.FB_RS485_1WIRE_MULTISENSOR_01.Error);
fbPump1(
	IN := fbThermostat1.OUT
	(* Coil dropped: DO_005..DO_008 are the bench's spare LEDs now, and the
	   cover block uses two of them. The pump logic and its MQTT entity are
	   untouched - only the physical output is gone. *)
);


// Radiators
fbThermostat2(MEASURED_TEMP := GVL_RS485.FB_RS485_1WIRE_MULTISENSOR_01.TEMPERATURE, MEASURED_HUM := GVL_RS485.FB_RS485_1WIRE_MULTISENSOR_01.HUMIDITY, SENSOR_VALID := GVL_RS485.FB_RS485_1WIRE_MULTISENSOR_01.DataAvailable AND NOT GVL_RS485.FB_RS485_1WIRE_MULTISENSOR_01.Error);
fbThermostat3(MEASURED_TEMP := GVL_RS485.FB_RS485_1WIRE_MULTISENSOR_01.TEMPERATURE, MEASURED_HUM := GVL_RS485.FB_RS485_1WIRE_MULTISENSOR_01.HUMIDITY, SENSOR_VALID := GVL_RS485.FB_RS485_1WIRE_MULTISENSOR_01.DataAvailable AND NOT GVL_RS485.FB_RS485_1WIRE_MULTISENSOR_01.Error);

(* Circuit 1 is Radiator 1, circuit 2 is Radiator 2; circuits 3..8 are unwired and
   their valves stay closed. The indices match asCollectorValveNames above and the
   VALVE_n names published to MQTT. *)
fbPump2Collector.THERMOSTAT[1] := fbThermostat2.OUT;
fbPump2Collector.THERMOSTAT[2] := fbThermostat3.OUT;

(* Requirement 2.3 above: the manifold may not start closing while the pump is
   still running out its minimum on-time, or the pump ends up turning against
   shut valves. fbPump2 already computed the signal for it and nothing read it.

   The collector is called before the pump, so it acts on last cycle's value -
   one task cycle of lag on a two-minute timer, and the safe direction: the hold
   is released a cycle late, never engaged a cycle late. *)
fbPump2Collector.PUMP_MIN_ONTIME_ACTIVE := fbPump2.MIN_ONTIME_ACTIVE;

fbPump2Collector();


fbPump2(
	IN := fbPump2Collector.PUMP
);

// Heat source for both pumps
fbBurnerGas(
	IN := fbPump2.HEAT_REQUEST OR fbPump1.HEAT_REQUEST,
	//OUT => DO_013
);

IF NOT InitRS485 THEN
	InitRS485 := TRUE;

(* THE WIRE.
   COM1 is the only port the PFC200 runtime exposes - COM2, COM3 and COM4 were
   all tried and none of them opens. The port must also have been put into RS485
   mode once per controller with `serialmode RS485` from the CODESYS PLC shell.
   That is a commissioning step: no IEC code can do it, it survives a reboot,
   and until it is done the bus is silent with no error to show for it. *)
fbRs485Transport.Init(
	Port			:= SysCom.SYS_COM_PORTS.SYS_COMPORT1,
	Baudrate		:= cudiBusBaudrate,
	Parity			:= SysCom.SYS_COM_PARITY.SYS_NOPARITY,
	StopBits		:= SysCom.SYS_COM_STOPBITS.SYS_ONESTOPBIT,
	ReplyTimeout	:= T#1S,			(* nothing at all by now means no reply *)
	GapTime			:= T#50MS			(* quiet line ends a frame *)
);

(* WHO GETS IT.
   Registration order no longer decides who is served first: selection resumes
   at a cursor and wraps, so the device registered last is polled as often as
   the device registered first. *)
fbRS485BusController.Init(
	Transport		:= fbRs485Transport,
	StartupDelay	:= T#5S,			(* let the slaves finish booting *)
	SilenceTime		:= T#50MS,			(* between frames, and between transactions *)
	StepTimeout		:= T#3S				(* watchdog on the transport, not on the slave *)
);

fbRS485BusController.RegisterDevice(device := GVL_RS485.FB_RS485_EASTRON_SDM220_1);
fbRS485BusController.RegisterDevice(device := GVL_RS485.FB_RS485_EASTRON_SDM630_1);
//fbRS485BusController.RegisterDevice(device := GVL_RS485.FB_RS485_DUCO_DUCOBOX_HOME);
//fbRS485BusController.RegisterDevice(device := GVL_RS485.FB_RS485_1WIRE_MULTISENSOR_01);
fbRS485BusController.RegisterDevice(device := GVL_RS485.FB_RS485_EASTRON_SDM_POWER_1);
fbRS485BusController.RegisterDevice(device := GVL_RS485.FB_RS485_SEN0492_1);

(* WHAT CANNOT BE SPOKEN TO YET.
   Asked of every device registered above, before the bus controller is allowed to
   start. Nothing here names a device or a register: what has to be written, and
   where, is each device's own answer - see I_RS485_DEVICE.GetCommissioning. A device
   that needs nothing costs one method call.

   It holds the bus off while it runs, because a device being hunted for at some
   other baud rate makes the whole pair unusable for as long as that takes. *)
fbRS485Commissioner.Init(
	Transport			:= fbRs485Transport,
	pController			:= ADR(fbRS485BusController),
	BusBaudrate			:= cudiBusBaudrate,
	pMqttPublishQueue	:= ADR(GVL_MQTT.fbMqttPublishQueue),
	MqttPublishPrefix	:= ADR(GVL_MQTT.MqttPubRS485Prefix),
	Enable				:= GVL_RS485.RS485_COMMISSION_ON_BOOT
);

(* INIT RS485 DEVICE STUFF.
   Nothing to do for the three Eastron meters. Modbus address, poll rate and -
   for the SDM_POWER block - the meter model all reach them through FB_init at
   their declaration in GVL_RS485, and FriendlyName wires up MQTT and Home
   Assistant on the first cyclic call. Registration above is the whole of it. *)

GVL_RS485.FB_RS485_DUCO_DUCOBOX_HOME.InitRS485(
	DataPollingInterval := T#3S,		(* Polling interval for data array *)
	DeviceAddress := 3					(* Device address of the modbus device *)
);

// Nodes: valves for example
GVL_RS485.FB_RS485_DUCO_DUCOBOX_HOME.AddNode(
	DataPollingInterval := T#15S
);
GVL_RS485.FB_RS485_DUCO_DUCOBOX_HOME.AddNode(
	DataPollingInterval := T#15S
);

GVL_RS485.FB_RS485_DUCO_DUCOBOX_HOME.InitMqtt(
	MQTTPublishPrefix:= ADR(GVL_MQTT.MqttPubRS485Prefix),
	MQTTSubscribePrefix:= ADR(GVL_MQTT.MqttSubRS485Prefix),
	pMqttPublishQueue := ADR(GVL_MQTT.fbMqttPublishQueue),
	pMqttCallbackCollector := ADR(GVL_MQTT.collector_FB_RS485_MQTT)
);


GVL_RS485.FB_RS485_1WIRE_MULTISENSOR_01.InitMqtt(
	MQTTPublishPrefix:= ADR(GVL_MQTT.MqttPubRS485Prefix),
	pMqttPublishQueue := ADR(GVL_MQTT.fbMqttPublishQueue)
);
GVL_RS485.FB_RS485_1WIRE_MULTISENSOR_01.InitMqttDiscovery(
	Device := ADR(GVL_MQTT.OWD_MULTISENSOR_01),
	ParentDevice:= ADR(GVL_MQTT.PLC_Device),
	DeviceName := 'Lab PLC 1-Wire sensorhub',
	SupportsTemperature := TRUE,
	SupportsHumidity := TRUE,
	SupportsDewPoint := TRUE,
	SupportsOwdVoltage := TRUE);


END_IF

(* Commissioning owns the bus while it runs, so the scheduler is held off until it
   is finished - a device being hunted for at another baud rate makes the pair
   unusable for anything else. With nothing to commission it finishes on its first
   cycle, and this costs one comparison from then on.

   Neither call knows what is on the bus: the commissioner asks every registered
   device whether it needs anything (I_RS485_DEVICE.GetCommissioning), and the bus
   controller asks every registered device whether it wants the bus (HasWork). *)
IF NOT fbRS485Commissioner.Done THEN
	fbRS485Commissioner();
ELSE
	(* The bus controller drives the transport - it calls Service every cycle, which
	   is what opens and re-opens the serial port as well as carrying frames - so
	   there is nothing to do here but call it. *)
	fbRS485BusController();
END_IF

(* --- bus health, published where it can actually be read -----------------------
   The transport's counters are the only instrument this bus has, and reading
   them has meant an online debug session - the least reliable thing in the
   chain on this hardware. Published every thirty seconds instead, retained, so
   the answer to "is the bus healthy" is a topic rather than an expedition.

   The pair that matters is CrcFail against NoReply. Bytes that arrive and never
   frame are a different fault from no bytes at all: the first is framing or
   noise, the second is a device that did not answer. Everything else here is
   context for those two. *)
fbDiagTimer(IN := NOT fbDiagTimer.Q, PT := T#30S);
IF fbDiagTimer.Q THEN
	sDiagReport := CONCAT('ok=', UDINT_TO_STRING(fbRs485Transport.Ok));
	sDiagReport := CONCAT(sDiagReport, ' noreply=');
	sDiagReport := CONCAT(sDiagReport, UDINT_TO_STRING(fbRs485Transport.NoReply));
	sDiagReport := CONCAT(sDiagReport, ' crc=');
	sDiagReport := CONCAT(sDiagReport, UDINT_TO_STRING(fbRs485Transport.CrcFail));
	sDiagReport := CONCAT(sDiagReport, ' short=');
	sDiagReport := CONCAT(sDiagReport, UDINT_TO_STRING(fbRs485Transport.ShortFrame));
	sDiagReport := CONCAT(sDiagReport, ' badaddr=');
	sDiagReport := CONCAT(sDiagReport, UDINT_TO_STRING(fbRs485Transport.BadAddress));
	sDiagReport := CONCAT(sDiagReport, ' badfunc=');
	sDiagReport := CONCAT(sDiagReport, UDINT_TO_STRING(fbRs485Transport.BadFunction));
	sDiagReport := CONCAT(sDiagReport, ' exc=');
	sDiagReport := CONCAT(sDiagReport, UDINT_TO_STRING(fbRs485Transport.Exceptions));
	sDiagReport := CONCAT(sDiagReport, ' lead=');
	sDiagReport := CONCAT(sDiagReport, UDINT_TO_STRING(fbRs485Transport.LeadNulls));
	sDiagReport := CONCAT(sDiagReport, ' trail=');
	sDiagReport := CONCAT(sDiagReport, UDINT_TO_STRING(fbRs485Transport.TrailNulls));
	sDiagReport := CONCAT(sDiagReport, ' tx=');
	sDiagReport := CONCAT(sDiagReport, UDINT_TO_STRING(fbRS485BusController.Transactions));
	sDiagReport := CONCAT(sDiagReport, ' steps=');
	sDiagReport := CONCAT(sDiagReport, UDINT_TO_STRING(fbRS485BusController.StepsExecuted));
	sDiagReport := CONCAT(sDiagReport, ' fail=');
	sDiagReport := CONCAT(sDiagReport, UDINT_TO_STRING(fbRS485BusController.StepFailures));
	sDiagReport := CONCAT(sDiagReport, ' lastfail=dev');
	sDiagReport := CONCAT(sDiagReport, BYTE_TO_STRING(fbRs485Transport.LastFailAddr));
	sDiagReport := CONCAT(sDiagReport, '/fc');
	sDiagReport := CONCAT(sDiagReport, BYTE_TO_STRING(fbRs485Transport.LastFailFunc));
	sDiagReport := CONCAT(sDiagReport, '/n');
	sDiagReport := CONCAT(sDiagReport, UDINT_TO_STRING(fbRs485Transport.LastFailLen));
	sDiagReport := CONCAT(sDiagReport, ' [');
	sDiagReport := CONCAT(sDiagReport, fbRs485Transport.LastFailBytes);
	sDiagReport := CONCAT(sDiagReport, ']');

	GVL_MQTT.fbMqttPublishQueue.AddMessage(
		Payload := sDiagReport,
		Topic := CONCAT(GVL_MQTT.MqttPubRS485Prefix, 'BUS_COUNTERS'),
		Qos := MQTT.QoS.ExactlyOnce,
		MqttRetain := TRUE);
END_IF

(* RS485 devices. Called even while commissioning runs: their bodies only
   publish and self-wire, and the scheduler is the only thing that talks to the
   bus on their behalf. *)
GVL_RS485.FB_RS485_EASTRON_SDM220_1();
GVL_RS485.FB_RS485_DUCO_DUCOBOX_HOME();
GVL_RS485.FB_RS485_1WIRE_MULTISENSOR_01();
GVL_RS485.FB_RS485_EASTRON_SDM630_1();
GVL_RS485.FB_RS485_EASTRON_SDM_POWER_1();
GVL_RS485.FB_RS485_SEN0492_1();

(* Ping the DMX artNet node *)
udiDMXnodeReachable := SysSockPing(szIPAddress:=GVL_DMX.IP, ulTimeout:=100, pulReplyTime:= ADR(udiPingTime));

IF udiDMXnodeReachable = 0 THEN
    PFC.SetLed(which:=PFC.LED.U3, how:=PFC.LedState.STATIC_GRN);
	IF udiDMXnodeReachable <> udiPreviousReachable THEN
		GVL_MQTT.PLC_Device.SendLogMessage('DMX ping OK');
	END_IF
ELSIF udiDMXnodeReachable = 5 THEN
     PFC.SetLed(which:=PFC.LED.U3, how:=PFC.LedState.BLINK_RED);
	IF udiDMXnodeReachable <> udiPreviousReachable THEN
		GVL_MQTT.PLC_Device.SendLogMessage('DMX ping Error');
	END_IF
END_IF

udiPreviousReachable := udiDMXnodeReachable;

(* Ping the MQTT broker as well, because U1 needs something the MQTT client cannot
   tell it. MQTT_CONNECTED does not notice a pulled network cable: a TCP socket with
   nothing to report stays open until a retransmit finally gives up, which is minutes
   rather than seconds, so the client goes on believing it has a session. Verified on
   the bench - LAN cable out, MQTT_CONNECTED still TRUE, U1 still green. ICMP notices
   in one task cycle, and the debounce below spends one more, so U1 turns red within
   about 20 s of the cable coming out and green within 10 s of it going back in.

   PRG_MQTT owns the LED; this only reports what it found. *)
iColon := FIND(GVL_MQTT.broker, ':');
IF iColon > 1 THEN
	sBrokerHost := LEFT(GVL_MQTT.broker, iColon - 1);
ELSE
	(* No port in the address, so it is already just the host. FIND returns 0 when
	   it matches nothing, which this also covers. *)
	sBrokerHost := GVL_MQTT.broker;
END_IF

udiBrokerReachable := SysSockPing(szIPAddress := sBrokerHost, ulTimeout := 100,
	pulReplyTime := ADR(udiBrokerPingTime));

(* Debounced, because one lost packet is not an outage. A success clears the count
   immediately, so recovery is as fast as the task; failures have to stack up. *)
IF udiBrokerReachable = 0 THEN
	uiBrokerPingFails := 0;
ELSIF uiBrokerPingFails < cuiBrokerPingFailsForRed THEN
	uiBrokerPingFails := uiBrokerPingFails + 1;
END_IF

GVL_MQTT.bBrokerReachable := (uiBrokerPingFails < cuiBrokerPingFailsForRed);

(* Log the debounced verdict, not the raw return code - otherwise a run of odd
   codes would log on every one of them. *)
IF GVL_MQTT.bBrokerReachable <> bPreviousBrokerReachable THEN
	IF GVL_MQTT.bBrokerReachable THEN
		GVL_MQTT.PLC_Device.SendLogMessage('MQTT broker ping OK');
	ELSE
		(* This one cannot be delivered while the broker is away; it queues and
		   arrives on reconnect, which is what makes the outage visible after the
		   fact rather than not at all. *)
		GVL_MQTT.PLC_Device.SendLogMessage('MQTT broker ping Error');
	END_IF
	bPreviousBrokerReachable := GVL_MQTT.bBrokerReachable;
END_IF

// Run the master before anything else, bound to the 753-647 on this device's own
// K-bus. This binding is the whole point of the second controller: I_Port wants a
// WagoTypesModule_753_647.I_Port_753_647, which only WAGO's device description
// creates, and that description does not fit the G1 lab device's bus.
fbDaliMaster(
	bPortDALI := 1,
	I_Port := IoConfig_Globals.DALI_753_647);

// The block under test. No InitMqtt and no InitMqttDiscovery: this application
// never runs, and calling them would only invent a Home Assistant entity for a
// controller that does not exist.
fbDimmer(
	BALLAST := Ballast,
	TOGGLE := FALSE,
	P_LONG := FALSE);
